def days_for_category(cat):
    """Which Day options make sense for a given category:
    Weekday -> Mon-Fri only (never Sat/Sun); Saturday -> only Saturday;
    Sunday -> only Sunday; Public Holiday -> every day is open (a PH can fall on any day)."""
    if cat=="Weekday": return WEEKDAY_DAYS
    if cat=="Saturday": return ["Saturday"]
    if cat=="Sunday": return ["Sunday"]
    return DAYS   # Public Holiday (or unset) — all days open
import sys
def _app_folder():
    """Folder containing the EXE/source. Used only for bundled resources."""
    if getattr(sys, "frozen", False):
        return os.path.dirname(sys.executable)
    return os.path.dirname(os.path.abspath(__file__))

def _data_folder():
    """Private Allocate Pro working folder under Windows AppData."""
    base = os.environ.get("LOCALAPPDATA")
    if not base:
        base = os.path.join(os.path.expanduser("~"), "AppData", "Local")
    path = os.path.join(base, "AllocatePro")
    os.makedirs(path, exist_ok=True)
    return path


PERF_LOG_PATH = os.path.join(_data_folder(), "performance_5_8.log")
_PERF_LOG_LOCK = threading.Lock()
def _perf_log(label, seconds, detail=""):
    """Tiny diagnostic log for operations slower than 50 ms."""
    try:
        seconds=float(seconds)
        if seconds < 0.05:
            return
        line=f"{datetime.now().isoformat(timespec='seconds')} | {label} | {seconds:.3f}s"
        if detail:
            line += " | "+str(detail).replace("\n"," ")[:300]
        with _PERF_LOG_LOCK:
            with open(PERF_LOG_PATH,"a",encoding="utf-8") as fh:
                fh.write(line+"\n")
    except Exception:
        pass

def _resource_path(name):
    """Path to a bundled PyInstaller resource or a development file."""
    if getattr(sys, "frozen", False) and hasattr(sys, "_MEIPASS"):
        return os.path.join(sys._MEIPASS, name)
    return os.path.join(_app_folder(), name)

