# ---------- CLOUD ENGINE IN ITS OWN PROCESS (11.6) ----------
# The libsql driver keeps Python's GIL while it waits on the network, so every cloud save
# (several round trips to Turso in Tokyo) and every replica sync froze the WHOLE window —
# the login screen, typing, folding the sidebar — for as long as the network took. Now the
# driver runs in a small helper process: the window only waits on a pipe (which frees the
# GIL), so it stays smooth while saves and syncs run. Same driver, same SQL, same results —
# only the place it runs changed. If the helper can't start, the app falls back to the
# old in-process driver automatically.
import subprocess as _subprocess, struct as _struct, pickle as _pickle

CLOUD_CHILD_SRC = r"""
import sys, os, struct, pickle, threading, queue, traceback
def _stdio(fd,std,mode):
    try:
        return os.fdopen(fd,mode,0)
    except Exception:
        # a windowed EXE may start without C-level stdin/stdout: open the pipe handles directly
        import msvcrt, ctypes
        h=ctypes.windll.kernel32.GetStdHandle(std)
        return os.fdopen(msvcrt.open_osfhandle(h,(os.O_RDONLY if 'r' in mode else os.O_WRONLY)|getattr(os,'O_BINARY',0)),mode,0)
def _main():
    rin=_stdio(0,-10,'rb'); wout=_stdio(1,-11,'wb')
    wlock=threading.Lock()
    def send(obj):
        b=pickle.dumps(obj,protocol=4)
        with wlock:
            wout.write(struct.pack('>I',len(b))+b); wout.flush()
    def recv():
        h=b''
        while len(h)<4:
            c=rin.read(4-len(h))
            if not c: return None
            h+=c
        n=struct.unpack('>I',h)[0]; b=b''
        while len(b)<n:
            c=rin.read(n-len(b))
            if not c: return None
            b+=c
        return pickle.loads(b)
    try:
        import libsql
    except Exception as e:
        send((0,'err','ImportError',str(e))); return
    conns={}; queues={}; nextid=[1]
    def worker(cid,q):
        while True:
            item=q.get()
            if item is None: return
            rid,op,a=item
            try:
                conn=conns.get(cid)
                if op=='exec':
                    cur=conn.execute(a[0],tuple(a[1]) if a[1] is not None else ())
                    desc=cur.description
                    rows=[tuple(r) for r in cur.fetchall()] if desc else []
                    send((rid,'ok',(rows,[tuple(d)[:2] for d in desc] if desc else None,getattr(cur,'rowcount',-1),getattr(cur,'lastrowid',None))))
                elif op=='many':
                    cur=conn.executemany(a[0],[tuple(x) for x in a[1]])
                    send((rid,'ok',(getattr(cur,'rowcount',-1),)))
                elif op=='script':
                    conn.executescript(a[0]); send((rid,'ok',None))
                elif op=='commit':
                    conn.commit(); send((rid,'ok',None))
                elif op=='rollback':
                    conn.rollback(); send((rid,'ok',None))
                elif op=='sync':
                    r=conn.sync() if hasattr(conn,'sync') else None
                    send((rid,'ok',None))
                elif op=='close':
                    try: conn.close()
                    except Exception: pass
                    conns.pop(cid,None); send((rid,'ok',None)); return
                else:
                    send((rid,'err','ValueError','unknown op '+str(op)))
            except BaseException as e:
                send((rid,'err',type(e).__name__,str(e)))
    send((0,'hello',os.getpid()))
    while True:
        msg=recv()
        if msg is None: break
        rid,op,cid,a=msg
        if op=='connect':
            try:
                conn=libsql.connect(*a[0],**a[1])
                cid=nextid[0]; nextid[0]+=1; conns[cid]=conn
                q=queue.Queue(); queues[cid]=q
                threading.Thread(target=worker,args=(cid,q),daemon=True).start()
                send((rid,'ok',cid))
            except BaseException as e:
                send((rid,'err',type(e).__name__,str(e)))
        elif cid in queues:
            queues[cid].put((rid,op,a))
            if op=='close': queues.pop(cid,None)
        else:
            send((rid,'err','RuntimeError','connection closed'))
    os._exit(0)
_main()
"""

class _CloudChild:
    """The helper process + a reader thread that hands answers back to whoever asked."""
    def __init__(self):
        self.lock=threading.Lock(); self.pending={}; self.next=1; self.proc=None; self.alive=False; self.gen=0
    def start(self):
        if getattr(sys,"frozen",False): cmd=[sys.executable,"--ap-cloud-child"]
        else: cmd=[sys.executable,"-c",CLOUD_CHILD_SRC]
        flags=0x08000000 if os.name=="nt" else 0          # CREATE_NO_WINDOW
        env=dict(os.environ)
        _L=_ap_launcher()
        if _L and _L.get("path"): env["AP_CODE_PATH"]=_L["path"]
        self.proc=_subprocess.Popen(cmd,stdin=_subprocess.PIPE,stdout=_subprocess.PIPE,stderr=_subprocess.DEVNULL,
                                    bufsize=0,creationflags=flags,env=env)
        self.gen+=1
        box=[]
        rt=threading.Thread(target=lambda:box.append(self._read()),daemon=True); rt.start(); rt.join(40)
        hello=box[0] if box else None
        if not hello or hello[1]!="hello":
            try: self.proc.kill()
            except Exception: pass
            raise RuntimeError("cloud helper did not start: "+repr(hello))
        self.alive=True
        threading.Thread(target=self._reader,daemon=True,name="AllocateProCloudReader").start()
    def _read(self):
        f=self.proc.stdout; h=b""
        while len(h)<4:
            c=f.read(4-len(h))
            if not c: return None
            h+=c
        n=_struct.unpack(">I",h)[0]; b=b""
        while len(b)<n:
            c=f.read(n-len(b))
            if not c: return None
            b+=c
        return _pickle.loads(b)
    def _reader(self):
        while True:
            try: msg=self._read()
            except Exception: msg=None
            if msg is None: break
            with self.lock: slot=self.pending.pop(msg[0],None)
            if slot: slot[1].append(msg); slot[0].set()
        self.alive=False
        with self.lock:
            waiting=list(self.pending.values()); self.pending.clear()
        for ev,box in waiting:
            box.append((0,"err","RuntimeError","cloud helper stopped")); ev.set()
    def call(self,op,cid,args,timeout=180):
        if not self.alive: raise RuntimeError("cloud helper is not running")
        ev=threading.Event(); box=[]
        with self.lock:
            rid=self.next; self.next+=1; self.pending[rid]=(ev,box)
            data=_pickle.dumps((rid,op,cid,args),protocol=4)
            try:
                self.proc.stdin.write(_struct.pack(">I",len(data))+data); self.proc.stdin.flush()
            except Exception as exc:
                self.pending.pop(rid,None); self.alive=False
                raise RuntimeError(f"cloud helper stopped: {exc}")
        if not ev.wait(timeout):
            with self.lock: self.pending.pop(rid,None)
            raise TimeoutError("The cloud did not answer in time.")
        msg=box[0]
        if msg[1]=="ok": return msg[2]
        etype,text=msg[2],msg[3]
        if "Integrity" in etype or "UNIQUE constraint" in text or "constraint failed" in text: raise sqlite3.IntegrityError(text)
        if etype=="TimeoutError": raise TimeoutError(text)
        if "Operational" in etype or "no such" in text or "duplicate column" in text: raise sqlite3.OperationalError(text)
        raise RuntimeError(text)

_CLOUD_CHILD=None
_CLOUD_CHILD_LOCK=threading.Lock()
_CLOUD_CHILD_FAILED=False

def _cloud_child():
    """The running helper (started on first use, restarted once if it died)."""
    global _CLOUD_CHILD,_CLOUD_CHILD_FAILED
    with _CLOUD_CHILD_LOCK:
        if _CLOUD_CHILD is not None and _CLOUD_CHILD.alive: return _CLOUD_CHILD
        if _CLOUD_CHILD_FAILED: return None
        if _CLOUD_CHILD is not None and _CLOUD_CHILD.gen>=4:      # died 4 times: stop trying
            _CLOUD_CHILD_FAILED=True; return None
        try:
            ch=_CLOUD_CHILD or _CloudChild()
            t0=time.perf_counter(); ch.start(); _CLOUD_CHILD=ch
            _perf_log("cloud_helper_start",time.perf_counter()-t0,f"pid {ch.proc.pid}")
            return ch
        except Exception as exc:
            _CLOUD_CHILD_FAILED=True
            try: _perf_log("cloud_helper_failed",0.0,str(exc)[:200])
            except Exception: pass
            return None

class _ProcCursor:
    def __init__(self,conn,res=None):
        self._conn=conn; self._set(res)
    def _set(self,res):
        rows,desc,rc,lid=res if res else ([],None,-1,None)
        self._rows=list(rows); self._i=0
        self.description=[tuple(d)+(None,)*5 for d in desc] if desc else None
        self.rowcount=rc; self.lastrowid=lid
    def execute(self,sql,params=()):
        self._set(self._conn._call("exec",(sql,list(params) if params is not None else None))); return self
    def executemany(self,sql,seq):
        self._conn.executemany(sql,seq); return self
    def fetchone(self):
        if self._i>=len(self._rows): return None
        r=self._rows[self._i]; self._i+=1; return r
    def fetchall(self):
        r=self._rows[self._i:]; self._i=len(self._rows); return r
    def fetchmany(self,n=1):
        r=self._rows[self._i:self._i+n]; self._i+=len(r); return r
    def __iter__(self):
        while True:
            r=self.fetchone()
            if r is None: return
            yield r
    def close(self): pass

class _ProcConn:
    """A libsql connection that lives in the helper process. Same calls as the real one."""
    def __init__(self,args,kwargs):
        self._args=(tuple(args),dict(kwargs)); self._cid=None; self._gen=None; self._open()
    def _open(self):
        ch=_cloud_child()
        if ch is None: raise RuntimeError("cloud helper unavailable")
        self._cid=ch.call("connect",0,self._args,timeout=90); self._gen=ch.gen
    def _call(self,op,args=(),timeout=180):
        ch=_cloud_child()
        if ch is None: raise RuntimeError("cloud helper unavailable")
        if self._gen!=ch.gen: self._open()          # helper was restarted: reconnect
        return ch.call(op,self._cid,args,timeout)
    def execute(self,sql,params=()):
        return _ProcCursor(self,self._call("exec",(sql,list(params) if params is not None else None)))
    def executemany(self,sql,seq):
        self._call("many",(sql,[list(x) for x in seq])); return _ProcCursor(self)
    def executescript(self,sql):
        self._call("script",(sql,)); return _ProcCursor(self)
    def cursor(self): return _ProcCursor(self)
    def commit(self): self._call("commit")
    def rollback(self): self._call("rollback")
    def sync(self): self._call("sync",timeout=300)
    def close(self):
        try: self._call("close",timeout=20)
        except Exception: pass
    def __enter__(self): return self
    def __exit__(self,*a): return False

def _libsql_connect(*args,**kwargs):
    """libsql.connect, but running in the helper process when it's available (errors are
    raised exactly like the driver's own); the in-process driver is the fallback."""
    ch=_cloud_child() if CLOUD_PROC_ENABLED else None
    if ch is not None:
        return _ProcConn(args,kwargs)
    import libsql
    return libsql.connect(*args,**kwargs)

