CLOUD_PROC_ENABLED=_cloud_proc_setting()

def _replica_sync_loop():
    """ONE long-lived thread owns the embedded-replica connection.

    This is intentionally separate from the mutation writer. Native libSQL/SQLite
    handles are never passed between threads, eliminating a major source of Windows
    lock/contention stalls seen in older builds.
    """
    conn=None
    while True:
        item=_SYNC_QUEUE.get()
        if item is None:
            _SYNC_QUEUE.task_done(); return
        event,result=item
        started=time.perf_counter()
        try:
            if conn is None:
                import libsql
                conn=_libsql_connect(CLOUD_REPLICA_PATH,sync_url=TURSO_DATABASE_URL,auth_token=TURSO_AUTH_TOKEN)
                try: conn.execute("PRAGMA foreign_keys=ON")
                except Exception: pass
            if hasattr(conn,"sync"): conn.sync()
            result["ok"]=True
        except Exception as exc:
            result["error"]=exc
            try:
                if conn: conn.close()
            except Exception: pass
            conn=None
        finally:
            _perf_log("replica_sync",time.perf_counter()-started)
            with _SYNC_STATE_LOCK:
                global _SYNC_INFLIGHT
                if _SYNC_INFLIGHT is event: _SYNC_INFLIGHT=None
            event.set(); _SYNC_QUEUE.task_done()

def _ensure_sync_thread():
    global _SYNC_THREAD
    if _SYNC_THREAD is not None and _SYNC_THREAD.is_alive(): return
    with _SYNC_THREAD_LOCK:
        if _SYNC_THREAD is None or not _SYNC_THREAD.is_alive():
            _SYNC_THREAD=threading.Thread(target=_replica_sync_loop,daemon=True,name="AllocateProReplicaSync")
            _SYNC_THREAD.start()

def sync_cloud_now(wait=True, timeout=45):
    """Request one coalesced replica pull. Never runs native sync on the caller thread.

    UI/background callers that do not need fresh data use wait=False. Archive/bootstrap
    can wait because they are already off Tk's UI thread. Multiple requests share the
    same in-flight sync instead of stacking.
    """
    global _SYNC_INFLIGHT
    if not CLOUD_ENABLED: return True
    _ensure_sync_thread()
    with _SYNC_STATE_LOCK:
        event=_SYNC_INFLIGHT
        if event is None:
            event=threading.Event(); result={}
            event._allocatepro_result=result
            _SYNC_INFLIGHT=event
            _SYNC_QUEUE.put((event,result))
        else:
            result=getattr(event,"_allocatepro_result",{})
    if not wait: return True
    event.wait(timeout=float(timeout))
    return bool(result.get("ok"))

