def _resolved_palette(name):
    """A palette with every optional key filled in, so older palettes never miss one."""
    pal=dict(_PALETTES.get(name,_NAVY_PALETTE))
    pal.setdefault("SIDEBAR_TITLE",pal["TEXT"])
    pal.setdefault("SELECT_BG",pal["SIDEBAR_ACTIVE"])
    pal.setdefault("SIDEBAR_ACTIVE_TEXT","#FFFFFF" if THEME_IS_DARK.get(name,True) else "#321D53")
    pal.setdefault("MARK_A",pal["PRIMARY"])
    pal.setdefault("MARK_B",pal["SECONDARY"])
    return pal

def _apply_palette(name):
    globals().update(_resolved_palette(name))

