UI_SCALE=1.0
def ui_pt(base):
    """A point size scaled by the current Text Size setting."""
    return max(6,int(round(base*UI_SCALE)))
def ui_px(base):
    """A pixel measure (row heights, paddings) scaled by the current Text Size setting."""
    return max(1,int(round(base*UI_SCALE)))
def _apply_text_size(level):
    global UI_SCALE,FONT,FONTB
    UI_SCALE=TEXT_SIZE_SCALE.get(level,1.0)
    FONT=("Segoe UI", ui_pt(10)); FONTB=("Segoe UI Semibold", ui_pt(10), "bold")
_apply_text_size(APP_TEXT_SIZE)

def row_px(base):
    """Table row height for the current Text Size AND Row Density settings."""
    return ui_px(base if APP_DENSITY!="compact" else int(round(base*0.74)))
def head_pad():
    return ui_px(12 if APP_DENSITY!="compact" else 7)
LOGO_B64=""""""


# ---------- HISTORICAL RECONCILIATION DATA (CareMile, wk end 29 Jun 2025 - 29 Mar 2026) ----------
# Lives in a SEPARATE sidecar file next to the app (ALLOCATE_PRO_HISTORICAL_DATA.json.gz),
# NOT embedded in this source file — keeps ALLOCATE_PRO.py small and easy to open/diff/version.
# Contains the 156 in-range CareMile invoice lines (from Invoices_update (1) Zena.xlsx, split
# proportionally across every week a multi-day service line actually spans) plus the 40 weekly
# CMV bank-reconciliation screenshots + OCR-drafted worker/amount pairs (from
# wages_with_break_down_till_28.06.26.xlsx). This is read-only reference data — what the user
# matches against it (hist_matches / hist_wage_overrides / hist_added_wages / hist_audit) lives
# in the separate HIST_DB_PATH sidecar database, never in this file.
def _historical_data_path():
    return _resource_path("ALLOCATE_PRO_HISTORICAL_DATA.json.gz")
_HIST_DATA_CACHE = None
def get_historical_data():
    """Lazily load+decompress the sidecar historical dataset (cached after first call)."""
    global _HIST_DATA_CACHE
    if _HIST_DATA_CACHE is None:
        path = _historical_data_path()
        if not os.path.exists(path):
            raise FileNotFoundError(
                "ALLOCATE_PRO_HISTORICAL_DATA.json.gz was not found next to the app.\n\n"
                "This file has to sit in the same folder as ALLOCATE_PRO.exe (or ALLOCATE_PRO.py "
                "during development). Copy it there and try again.")
        with gzip.open(path, "rt", encoding="utf-8") as f:
            _HIST_DATA_CACHE = json.load(f)
    return _HIST_DATA_CACHE

# ---------- DATABASE ----------
def connect():
    """Write-capable connection to the active period.

    Live-cloud writes use the Turso primary directly. UI reads NEVER use this
    function; they use read_connect() against the local replica. This split is the
    core 5.7 performance fix.
    """
    target=_context_db_path()
    if CLOUD_ENABLED and target == DEFAULT_DB_PATH:
        return _primary_connect()
    con = sqlite3.connect(target)
    con.execute("PRAGMA foreign_keys=ON")
    con.execute("PRAGMA journal_mode=DELETE")
    return con


def read_connect():
    """Fast local read-only connection used by every UI/render path.

    The libSQL embedded replica is a standard SQLite file. Reading it through
    Python's built-in sqlite3 avoids libSQL FFI/sync contention on Tk's UI
    thread. Writes still use connect() so they continue to reach Turso Cloud.
    """
    target=_context_db_path()
    path = CLOUD_REPLICA_PATH if (CLOUD_ENABLED and target == DEFAULT_DB_PATH) else target
    # The replica is created during _remote_connect()/startup before the main UI.
    # 0.15 s used to be the lock wait; a replica sync holding the file for slightly
    # longer made the whole snapshot reload fail silently and the screen go stale.
    # Waiting up to ~1 s on a rare lock is far better than showing old numbers.
    con = sqlite3.connect(path, timeout=1.0)
    try:
        con.execute("PRAGMA query_only=ON")
        con.execute("PRAGMA busy_timeout=1000")
    except Exception:
        pass
    return con


def _quick_local_user_count():
    """Fast local-only user count. None means the replica/schema is not ready yet."""
    path = CLOUD_REPLICA_PATH if CLOUD_ENABLED else DEFAULT_DB_PATH
    if not os.path.exists(path):
        return None
    con=None
    try:
        con=sqlite3.connect(path,timeout=0.05)
        con.execute("PRAGMA query_only=ON")
        row=con.execute("SELECT COUNT(*) FROM users").fetchone()
        return int(row[0] or 0) if row else 0
    except Exception:
        return None
    finally:
        try:
            if con: con.close()
        except Exception: pass


def _bootstrap_database_worker(callback=None):
    """Cloud/schema startup work that must never run on Tk's UI thread."""
    global STARTUP_ERROR, STARTUP_SNAPSHOT
    err=None; count=None
    try:
        if CLOUD_ENABLED:
            # Initial cloud work is off the UI thread. The dedicated sync worker owns
            # the replica connection; schema writes use the separate primary writer.
            sync_cloud_now(wait=True)
            init_db()
            try:
                refresh_archive_index_from_cloud()
            except Exception:
                pass
            sync_cloud_now(wait=True)
        else:
            init_db(); auto_backup()
        count=_quick_local_user_count()
        if count is None:
            con=read_connect(); count=int(con.execute("SELECT COUNT(*) FROM users").fetchone()[0] or 0); con.close()
        try:
            STARTUP_SNAPSHOT=load_period_snapshot()
        except Exception:
            STARTUP_SNAPSHOT=None
    except Exception as exc:
        err=exc; STARTUP_ERROR=exc
    finally:
        STARTUP_READY.set()
        if callback:
            try: callback(count,err)
            except Exception: pass


def start_database_bootstrap(root,on_done=None):
    global STARTUP_BOOTSTRAP_STARTED
    with STARTUP_BOOTSTRAP_LOCK:
        if STARTUP_BOOTSTRAP_STARTED: return
        STARTUP_BOOTSTRAP_STARTED=True
    # Worker threads never call Tk. They publish a result and the UI thread polls it.
    # This avoids Tcl cross-thread waits that can look like a frozen login window.
    result={"ready":False,"count":None,"err":None}
    def worker_done(count,err):
        result.update({"ready":True,"count":count,"err":err})
    threading.Thread(target=_bootstrap_database_worker,args=(worker_done,),daemon=True,name="AllocateProBootstrap").start()
    def poll():
        if result["ready"]:
            if on_done: on_done(result["count"],result["err"])
            return
        try: root.after(50,poll)
        except Exception: pass
    root.after(50,poll)


def _ensure_column(cur, table, coldef):
    try:
        cur.execute(f"ALTER TABLE {table} ADD COLUMN {coldef}")
    except Exception:
        pass


def init_db():
    con=connect(); c=con.cursor()
    c.execute("""CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,username TEXT UNIQUE,
        salt TEXT,pwhash TEXT,role TEXT,created TEXT)""")
    c.execute("CREATE TABLE IF NOT EXISTS workers(name TEXT PRIMARY KEY)")
    c.execute("CREATE TABLE IF NOT EXISTS worker_week(worker TEXT,week TEXT,wage REAL,PRIMARY KEY(worker,week))")
    # Per-worker rate exceptions. A worker with no row here for a category simply
    # uses GLOBAL_RATES for it — this table only ever holds the exceptions.
    c.execute("CREATE TABLE IF NOT EXISTS worker_rate(worker TEXT,category TEXT,rate REAL,PRIMARY KEY(worker,category))")
    c.execute("CREATE TABLE IF NOT EXISTS clients(name TEXT PRIMARY KEY)")
    c.execute("CREATE TABLE IF NOT EXISTS client_week(client TEXT,week TEXT,category TEXT,hours REAL,PRIMARY KEY(client,week,category))")
    c.execute("CREATE TABLE IF NOT EXISTS client_period(client TEXT,category TEXT,hours REAL,PRIMARY KEY(client,category))")
    c.execute("CREATE TABLE IF NOT EXISTS client_estimate(client TEXT,week TEXT,category TEXT,hours REAL,PRIMARY KEY(client,week,category))")
    # auto=1 marks an estimate this app filled in from the allocations, so it may keep
    # tracking them. A figure the USER typed is auto=0 and is never rewritten.
    _ensure_column(c, "client_estimate", "auto INTEGER DEFAULT 0")
    c.execute("""CREATE TABLE IF NOT EXISTS allocations(id INTEGER PRIMARY KEY,week TEXT,worker TEXT,
        client TEXT,category TEXT,hours REAL,rate REAL,cost REAL,day TEXT,note TEXT,created_by TEXT,created TEXT,
        start_time TEXT,end_time TEXT)""")
    _ensure_column(c, "allocations", "start_time TEXT")
    _ensure_column(c, "allocations", "end_time TEXT")
    c.execute("CREATE TABLE IF NOT EXISTS meta(k TEXT PRIMARY KEY,v TEXT)")
    # filename/data/updated make period archives portable between computers in cloud mode.
    c.execute("""CREATE TABLE IF NOT EXISTS archives(
        id INTEGER PRIMARY KEY,name TEXT,created TEXT,path TEXT,
        filename TEXT,data BLOB,updated TEXT)""")
    _ensure_column(c, "archives", "filename TEXT")
    _ensure_column(c, "archives", "data BLOB")
    _ensure_column(c, "archives", "updated TEXT")
    c.execute("CREATE TABLE IF NOT EXISTS worker_chain(client TEXT,position INTEGER,worker TEXT,PRIMARY KEY(client,position))")
    c.execute("""CREATE TABLE IF NOT EXISTS cmv_week_info(
        id INTEGER PRIMARY KEY, week TEXT, worker TEXT, source_worker TEXT, work_date TEXT, day TEXT,
        client TEXT, service TEXT, hours REAL, start_time TEXT, end_time TEXT, status TEXT,
        source_note TEXT, source_file TEXT, imported_at TEXT
    )""")
    c.execute("CREATE INDEX IF NOT EXISTS idx_cmv_week_worker ON cmv_week_info(week,worker)")
    c.execute("""CREATE TABLE IF NOT EXISTS team_presence(
        session_id TEXT PRIMARY KEY,
        username TEXT,
        role TEXT,
        machine TEXT,
        period TEXT,
        week TEXT,
        activity TEXT,
        last_seen TEXT
    )""")
    c.execute("""CREATE TABLE IF NOT EXISTS team_activity(
        id INTEGER PRIMARY KEY,
        username TEXT,
        machine TEXT,
        period TEXT,
        week TEXT,
        activity TEXT,
        created TEXT
    )""")
    c.execute("""CREATE TABLE IF NOT EXISTS audit_log(
        id INTEGER PRIMARY KEY, created TEXT, username TEXT, action TEXT, entity_type TEXT,
        entity_id TEXT, week TEXT, old_value TEXT, new_value TEXT, detail TEXT
    )""")
    c.execute("""CREATE TABLE IF NOT EXISTS notes(
        id INTEGER PRIMARY KEY, entity_type TEXT, entity_id TEXT, week TEXT,
        note TEXT, author TEXT, created TEXT
    )""")
    c.execute("CREATE TABLE IF NOT EXISTS client_guide(client TEXT PRIMARY KEY, data TEXT, updated TEXT, updated_by TEXT)")
    con.commit(); con.close()


def _table_columns(con, table):
    try:
        return [r[1] for r in con.execute(f"PRAGMA table_info({table})").fetchall()]
    except Exception:
        return []


def _copy_table(src, dst, table, replace=True):
    """Copy rows from a legacy local SQLite table to the cloud using common columns."""
    src_cols = _table_columns(src, table)
    dst_cols = _table_columns(dst, table)
    cols = [c for c in src_cols if c in dst_cols]
    if not cols:
        return 0
    qcols = ",".join(cols)
    rows = src.execute(f"SELECT {qcols} FROM {table}").fetchall()
    if not rows:
        return 0
    ph = ",".join("?" for _ in cols)
    verb = "INSERT OR REPLACE" if replace else "INSERT OR IGNORE"
    for row in rows:
        dst.execute(f"{verb} INTO {table}({qcols}) VALUES({ph})", tuple(row))
    return len(rows)


def migrate_local_data_to_cloud_if_needed():
    """One-time safe import of the existing local Allocate Pro DB into an EMPTY cloud DB.

    It never deletes the old local files. If the cloud already contains users/workers/clients/
    allocations, it assumes the cloud is already established and does not overwrite it.
    """
    if not CLOUD_ENABLED:
        return {"migrated": False, "reason": "local mode"}
    dst = _master_connect()
    try:
        # Do not overwrite an established cloud database.
        counts = 0
        for table in ("users","workers","clients","allocations"):
            try: counts += int(dst.execute(f"SELECT COUNT(*) FROM {table}").fetchone()[0] or 0)
            except Exception: pass
        if counts > 0:
            return {"migrated": False, "reason": "cloud already has data"}

        copied = 0
        if os.path.exists(LOCAL_DB_PATH):
            try:
                src = sqlite3.connect(LOCAL_DB_PATH)
                for table in ("users","workers","worker_week","clients","client_week","client_period",
                              "client_estimate","allocations","meta","worker_chain","cmv_week_info"):
                    copied += _copy_table(src, dst, table)
                # Existing archives are uploaded as portable DB blobs where possible.
                try:
                    for name,created,path in src.execute("SELECT name,created,path FROM archives ORDER BY id").fetchall():
                        if path and os.path.exists(path):
                            data = open(path,"rb").read()
                            fn = os.path.basename(path)
                            dst.execute("""INSERT INTO archives(name,created,path,filename,data,updated)
                                VALUES(?,?,?,?,?,?)""",
                                (name,created,"",fn,data,datetime.now().isoformat(timespec="seconds")))
                except Exception:
                    pass
                src.close()
            except Exception:
                pass

        if os.path.exists(HIST_DB_PATH):
            try:
                hsrc = sqlite3.connect(HIST_DB_PATH)
                for table in ("hist_matches","hist_wage_overrides","hist_added_wages","hist_audit",
                              "hist_sw_roster","hist_period_status"):
                    copied += _copy_table(hsrc, dst, table)
                hsrc.close()
            except Exception:
                pass

        dst.execute("INSERT OR REPLACE INTO meta(k,v) VALUES('cloud_migration',?)",
                    (datetime.now().isoformat(timespec="seconds"),))
        dst.commit()
        return {"migrated": bool(copied), "rows": copied}
    finally:
        dst.close()

# ---------- HISTORICAL RECONCILIATION DB (CareMile, sidecar — see HIST_DB_PATH) ----------
def hist_connect():
    # Historical writes/reads are infrequent; use the primary so they never lock
    # the live UI replica file.
    if CLOUD_ENABLED:
        return _primary_connect()
    con = sqlite3.connect(HIST_DB_PATH)
    con.execute("PRAGMA journal_mode=DELETE")
    return con
def hist_init_db():
    con=hist_connect(); c=con.cursor()
    c.execute("""CREATE TABLE IF NOT EXISTS hist_matches(id TEXT PRIMARY KEY,week_ending TEXT,
        inv_ids TEXT,wage_ids TEXT,inv_summary TEXT,wage_summary TEXT,inv_total REAL,wage_total REAL,
        created_by TEXT,created TEXT)""")
    c.execute("""CREATE TABLE IF NOT EXISTS hist_wage_overrides(wage_id TEXT PRIMARY KEY,
        name TEXT,amount TEXT)""")
    c.execute("""CREATE TABLE IF NOT EXISTS hist_added_wages(id TEXT PRIMARY KEY,week_ending TEXT,
        name TEXT,amount TEXT)""")
    c.execute("""CREATE TABLE IF NOT EXISTS hist_audit(id INTEGER PRIMARY KEY AUTOINCREMENT,
        ts TEXT,action TEXT,week_ending TEXT,detail TEXT,inv_total REAL,wage_total REAL,username TEXT)""")
    c.execute("""CREATE TABLE IF NOT EXISTS hist_sw_roster(worker_name TEXT,participant TEXT,
        created_by TEXT,created TEXT,PRIMARY KEY(worker_name,participant))""")
    c.execute("""CREATE TABLE IF NOT EXISTS hist_period_status(period_index INTEGER PRIMARY KEY,
        status TEXT,saved_by TEXT,saved_at TEXT)""")
    con.commit(); con.close()
def hist_log_audit(action, week_ending, detail, inv_total, wage_total, username):
    con=hist_connect()
    con.execute("INSERT INTO hist_audit(ts,action,week_ending,detail,inv_total,wage_total,username) VALUES(?,?,?,?,?,?,?)",
        (datetime.now().isoformat(timespec="seconds"), action, week_ending, detail, inv_total, wage_total, username))
    con.commit(); con.close()
def hist_list_audit():
    con=hist_connect(); rows=con.execute("SELECT ts,action,week_ending,detail,inv_total,wage_total,username FROM hist_audit ORDER BY id").fetchall(); con.close()
    return rows
def hist_add_match(mid, week_ending, inv_ids, wage_ids, inv_summary, wage_summary, inv_total, wage_total, username):
    con=hist_connect()
    con.execute("""INSERT INTO hist_matches(id,week_ending,inv_ids,wage_ids,inv_summary,wage_summary,inv_total,wage_total,created_by,created)
        VALUES(?,?,?,?,?,?,?,?,?,?)""",
        (mid, week_ending, json.dumps(inv_ids), json.dumps(wage_ids), json.dumps(inv_summary), json.dumps(wage_summary),
         inv_total, wage_total, username, datetime.now().isoformat(timespec="seconds")))
    con.commit(); con.close()
    hist_log_audit("MATCH", week_ending, " | ".join(inv_summary)+"  <->  "+" | ".join(wage_summary), inv_total, wage_total, username)
def hist_remove_match(mid, username):
    con=hist_connect()
    row=con.execute("SELECT week_ending,inv_summary,wage_summary,inv_total,wage_total FROM hist_matches WHERE id=?",(mid,)).fetchone()
    con.execute("DELETE FROM hist_matches WHERE id=?",(mid,))
    con.commit(); con.close()
    if row:
        we,invs,wgs,it,wt = row
        hist_log_audit("UNLINK", we, " | ".join(json.loads(invs))+"  <->  "+" | ".join(json.loads(wgs)), it, wt, username)
def hist_list_matches():
    con=hist_connect()
    rows=con.execute("SELECT id,week_ending,inv_ids,wage_ids,inv_summary,wage_summary,inv_total,wage_total FROM hist_matches ORDER BY created").fetchall()
    con.close()
    out=[]
    for r in rows:
        out.append({"id":r[0],"week_ending":r[1],"inv_ids":json.loads(r[2]),"wage_ids":json.loads(r[3]),
                    "inv_summary":json.loads(r[4]),"wage_summary":json.loads(r[5]),"inv_total":r[6],"wage_total":r[7]})
    return out
def hist_set_wage_override(wage_id, name, amount):
    con=hist_connect()
    con.execute("INSERT INTO hist_wage_overrides(wage_id,name,amount) VALUES(?,?,?) ON CONFLICT(wage_id) DO UPDATE SET name=excluded.name,amount=excluded.amount",
        (wage_id, name, amount))
    con.commit(); con.close()
def hist_list_wage_overrides():
    con=hist_connect(); rows=con.execute("SELECT wage_id,name,amount FROM hist_wage_overrides").fetchall(); con.close()
    return {r[0]:{"name":r[1],"amount":r[2]} for r in rows}
def hist_add_wage(wid, week_ending, name, amount):
    con=hist_connect()
    con.execute("INSERT INTO hist_added_wages(id,week_ending,name,amount) VALUES(?,?,?,?)",(wid,week_ending,name,amount))
    con.commit(); con.close()
def hist_list_added_wages():
    con=hist_connect(); rows=con.execute("SELECT id,week_ending,name,amount FROM hist_added_wages").fetchall(); con.close()
    return [{"id":r[0],"week_ending":r[1],"name":r[2],"amount":r[3]} for r in rows]

# ---- Support-worker roster: which SW(s) support which CareMile participant ----
# A worker can be tagged to more than one participant (composite key), since some
# support workers cover more than one of the four participants across the period.
def hist_add_sw(worker_name, participant, username):
    con=hist_connect()
    con.execute("""INSERT INTO hist_sw_roster(worker_name,participant,created_by,created) VALUES(?,?,?,?)
        ON CONFLICT(worker_name,participant) DO NOTHING""",
        (worker_name.strip(), participant, username, datetime.now().isoformat(timespec="seconds")))
    con.commit(); con.close()
def hist_remove_sw(worker_name, participant):
    con=hist_connect()
    con.execute("DELETE FROM hist_sw_roster WHERE worker_name=? AND participant=?", (worker_name, participant))
    con.commit(); con.close()
def hist_list_sw_roster():
    con=hist_connect()
    rows=con.execute("SELECT worker_name,participant FROM hist_sw_roster ORDER BY participant,worker_name").fetchall()
    con.close()
    return [{"worker_name":r[0],"participant":r[1]} for r in rows]
def hist_roster_map():
    """worker_name (lowercased, trimmed, punctuation stripped) -> participants they're tagged to."""
    m = {}
    for r in hist_list_sw_roster():
        key = re.sub(r'[^a-z0-9 ]', '', r["worker_name"].strip().lower()).strip()
        m.setdefault(key, [])
        if r["participant"] not in m[key]:
            m[key].append(r["participant"])
    return m

# ---- Period status: has this 6-week block been reviewed/saved? (mirrors the app's own
# 6-week period concept, but tracked separately since historical weeks are fixed calendar
# weeks, not the rolling live period) ----
def hist_mark_period_saved(period_index, username):
    con=hist_connect()
    con.execute("""INSERT INTO hist_period_status(period_index,status,saved_by,saved_at) VALUES(?,?,?,?)
        ON CONFLICT(period_index) DO UPDATE SET status=excluded.status,saved_by=excluded.saved_by,saved_at=excluded.saved_at""",
        (period_index, "saved", username, datetime.now().isoformat(timespec="seconds")))
    con.commit(); con.close()
def hist_list_period_status():
    con=hist_connect()
    rows=con.execute("SELECT period_index,status,saved_by,saved_at FROM hist_period_status").fetchall()
    con.close()
    return {r[0]: {"status":r[1],"saved_by":r[2],"saved_at":r[3]} for r in rows}

import shutil
# Local folders are now only for temporary/archive materialisation and optional local-mode backups.
BACKUP_DIR = os.path.join(_data_folder(), "backups")
ARCHIVE_DIR = os.path.join(_data_folder(), "archives")
ARCHIVE_INDEX_CACHE_PATH = os.path.join(_data_folder(), "archive_index.json")
_ARCHIVE_INDEX_LOCK = threading.Lock()

def _load_archive_index_cache():
    try:
        with open(ARCHIVE_INDEX_CACHE_PATH,"r",encoding="utf-8") as fh:
            rows=json.load(fh) or []
        return [r for r in rows if isinstance(r,dict) and r.get("filename")]
    except Exception:
        return []

_ARCHIVE_INDEX_CACHE = _load_archive_index_cache()

def _save_archive_index_cache():
    try:
        tmp=ARCHIVE_INDEX_CACHE_PATH+".tmp"
        with open(tmp,"w",encoding="utf-8") as fh:
            json.dump(_ARCHIVE_INDEX_CACHE,fh,ensure_ascii=False)
        os.replace(tmp,ARCHIVE_INDEX_CACHE_PATH)
    except Exception:
        pass

def _archive_index_rows():
    with _ARCHIVE_INDEX_LOCK:
        return [dict(r) for r in _ARCHIVE_INDEX_CACHE]

def _archive_index_upsert(name,filename,created=None,updated=None,aid=None):
    filename=os.path.basename(filename or "")
    if not filename:return
    now=datetime.now().isoformat(timespec="seconds")
    with _ARCHIVE_INDEX_LOCK:
        found=None
        for r in _ARCHIVE_INDEX_CACHE:
            if r.get("filename")==filename:
                found=r;break
        if found is None:
            found={"id":aid or 0,"name":name or filename,"created":created or now,"filename":filename,"updated":updated or now}
            _ARCHIVE_INDEX_CACHE.insert(0,found)
        else:
            found.update({"name":name or found.get("name") or filename,"updated":updated or now})
            if created:found["created"]=created
            if aid is not None:found["id"]=aid
        _ARCHIVE_INDEX_CACHE.sort(key=lambda r:r.get("created") or "",reverse=True)
        _save_archive_index_cache()

def _archive_index_remove(filename):
    filename=os.path.basename(filename or "")
    with _ARCHIVE_INDEX_LOCK:
        _ARCHIVE_INDEX_CACHE[:] = [r for r in _ARCHIVE_INDEX_CACHE if r.get("filename")!=filename]
        _save_archive_index_cache()

def refresh_archive_index_from_cloud():
    """Fetch only tiny archive metadata, never archive BLOBs. Safe for background use."""
    if not CLOUD_ENABLED:return _archive_index_rows()
    con=_primary_connect()
    try:
        rows=con.execute("SELECT id,name,created,filename,updated FROM archives WHERE filename IS NOT NULL AND filename<>'' ORDER BY id DESC").fetchall()
    finally:
        con.close()
    fresh=[{"id":int(aid or 0),"name":name or fn,"created":created or "","filename":fn,"updated":updated or ""} for aid,name,created,fn,updated in rows if fn]
    with _ARCHIVE_INDEX_LOCK:
        _ARCHIVE_INDEX_CACHE[:] = fresh
        _save_archive_index_cache()
    return _archive_index_rows()


def auto_backup(keep=10):
    """Local-mode safety backup. Cloud mode is already centralised and does not copy a
    live database file because the live database is remote."""
    if CLOUD_ENABLED:
        return
    if not os.path.exists(DB_PATH): return
    try:
        os.makedirs(BACKUP_DIR, exist_ok=True)
        stamp=datetime.now().strftime("%Y%m%d_%H%M%S")
        shutil.copy2(DB_PATH, os.path.join(BACKUP_DIR, f"backup_{stamp}.db"))
        backups=sorted(f for f in os.listdir(BACKUP_DIR) if f.startswith("backup_") and f.endswith(".db"))
        for old in backups[:-keep]:
            try: os.remove(os.path.join(BACKUP_DIR, old))
            except Exception: pass
    except Exception:
        pass


def _archive_blob(path):
    """Compressed archive payload. Old raw archive rows remain readable."""
    with open(path,"rb") as f:
        raw=f.read()
    return gzip.compress(raw,compresslevel=6)


def _archive_path_for(filename):
    os.makedirs(ARCHIVE_DIR, exist_ok=True)
    return os.path.join(ARCHIVE_DIR, os.path.basename(filename))


def register_period(name, path):
    """Register a saved period.

    Cloud mode uploads the BLOB once, but the UI never downloads every BLOB just to
    list periods. A tiny local metadata index is updated immediately after success.
    """
    if not os.path.exists(path):
        raise FileNotFoundError(path)
    if not CLOUD_ENABLED:
        con=sqlite3.connect(DEFAULT_DB_PATH)
        con.execute("INSERT INTO archives(name,created,path) VALUES(?,?,?)",(name,datetime.now().isoformat(),path))
        con.commit(); con.close()
        return name

    fn=os.path.basename(path); data=_archive_blob(path); now=datetime.now().isoformat(timespec="seconds")
    con=_master_connect(); aid=0; created=now
    try:
        row=con.execute("SELECT id,created FROM archives WHERE filename=? ORDER BY id DESC LIMIT 1",(fn,)).fetchone()
        if row:
            aid=int(row[0] or 0); created=row[1] or now
            con.execute("UPDATE archives SET name=?,path='',data=?,updated=? WHERE id=?",(name,data,now,aid))
        else:
            con.execute("INSERT INTO archives(name,created,path,filename,data,updated) VALUES(?,?,?,?,?,?)",(name,now,"",fn,data,now))
        con.commit()
        try:
            if not aid:
                rr=con.execute("SELECT id,created FROM archives WHERE filename=? ORDER BY id DESC LIMIT 1",(fn,)).fetchone()
                if rr: aid=int(rr[0] or 0); created=rr[1] or now
        except Exception: pass
    finally:
        con.close()
    _archive_index_upsert(name,fn,created,now,aid)
    _archive_stamp_write(path, now)
    return name


def _archive_stamp_path(path):
    """Sidecar next to a materialised archive recording which cloud 'updated' version it is."""
    return path + ".synced"

def _archive_stamp_read(path):
    try:
        with open(_archive_stamp_path(path),"r",encoding="utf-8") as fh: return fh.read().strip()
    except Exception:
        return ""

def _archive_stamp_write(path, updated):
    try:
        with open(_archive_stamp_path(path),"w",encoding="utf-8") as fh: fh.write(str(updated or ""))
    except Exception:
        pass

def _sync_archive_blob(path):
    """After an archived period is edited, push its updated file back to the cloud,
    bump its 'updated' version, and remember locally that this file IS that version."""
    if not CLOUD_ENABLED or not path or path == DEFAULT_DB_PATH or not os.path.exists(path):
        return
    try:
        fn = os.path.basename(path)
        data = _archive_blob(path)
        now = datetime.now().isoformat(timespec="seconds")
        con = _master_connect()
        row = con.execute("SELECT id FROM archives WHERE filename=? ORDER BY id DESC LIMIT 1", (fn,)).fetchone()
        if row:
            con.execute("UPDATE archives SET data=?,updated=? WHERE id=?", (data,now,row[0]))
            con.commit()
            _archive_index_upsert(None, fn, updated=now)
            _archive_stamp_write(path, now)
        con.close()
    except Exception as exc:
        try: _perf_log("archive_blob_sync_failed",0.0,f"{os.path.basename(path)}: {exc}")
        except Exception: pass

def archive_fetch_if_newer(path):
    """Make sure the local copy of a saved period is the latest cloud version before it
    is opened. Returns True when a usable file is in place. Downloads when the file is
    missing OR the cloud's 'updated' stamp differs from the version this machine last
    downloaded/uploaded (another computer edited it since). If the cloud can't be
    reached but a local copy exists, the local copy is used."""
    if not CLOUD_ENABLED or not path or path == DEFAULT_DB_PATH:
        return os.path.exists(path) if path else False
    have_local = os.path.exists(path)
    cloud_updated = None
    try:
        con = _master_connect()
        row = con.execute("SELECT updated,created FROM archives WHERE filename=? ORDER BY id DESC LIMIT 1",
                          (os.path.basename(path),)).fetchone()
        con.close()
        if row: cloud_updated = (row[0] or row[1] or "")
    except Exception:
        cloud_updated = None
    if cloud_updated is None:
        return have_local
    if have_local and _archive_stamp_read(path) == cloud_updated:
        return True
    if refresh_archive_from_cloud(path):
        _archive_stamp_write(path, cloud_updated)
        _archive_index_upsert(None, os.path.basename(path), updated=cloud_updated)
        return True
    return have_local

# ---- CareMile historical push: writes tagged wages / estimated hours into a DEDICATED,
# separately-switchable period file — never touches the live/currently-active period ----
def _create_period_schema(path):
    """Same table set as init_db(), but built directly against an arbitrary path via its
    own connection — deliberately does NOT use connect()/DB_PATH, so this can never touch
    whichever period the user currently has open live."""
    con = sqlite3.connect(path); c = con.cursor()
    c.execute("""CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,username TEXT UNIQUE,
        salt TEXT,pwhash TEXT,role TEXT,created TEXT)""")
    c.execute("CREATE TABLE IF NOT EXISTS workers(name TEXT PRIMARY KEY)")
    c.execute("CREATE TABLE IF NOT EXISTS worker_week(worker TEXT,week TEXT,wage REAL,PRIMARY KEY(worker,week))")
    # Per-worker rate exceptions. A worker with no row here for a category simply
    # uses GLOBAL_RATES for it — this table only ever holds the exceptions.
    c.execute("CREATE TABLE IF NOT EXISTS worker_rate(worker TEXT,category TEXT,rate REAL,PRIMARY KEY(worker,category))")
    c.execute("CREATE TABLE IF NOT EXISTS clients(name TEXT PRIMARY KEY)")
    c.execute("CREATE TABLE IF NOT EXISTS client_week(client TEXT,week TEXT,category TEXT,hours REAL,PRIMARY KEY(client,week,category))")
    c.execute("CREATE TABLE IF NOT EXISTS client_period(client TEXT,category TEXT,hours REAL,PRIMARY KEY(client,category))")
    c.execute("CREATE TABLE IF NOT EXISTS client_estimate(client TEXT,week TEXT,category TEXT,hours REAL,PRIMARY KEY(client,week,category))")
    # auto=1 marks an estimate this app filled in from the allocations, so it may keep
    # tracking them. A figure the USER typed is auto=0 and is never rewritten.
    _ensure_column(c, "client_estimate", "auto INTEGER DEFAULT 0")
    c.execute("""CREATE TABLE IF NOT EXISTS allocations(id INTEGER PRIMARY KEY,week TEXT,worker TEXT,
        client TEXT,category TEXT,hours REAL,rate REAL,cost REAL,day TEXT,note TEXT,created_by TEXT,created TEXT,
        start_time TEXT,end_time TEXT)""")
    c.execute("CREATE TABLE IF NOT EXISTS meta(k TEXT PRIMARY KEY,v TEXT)")
    c.execute("""CREATE TABLE IF NOT EXISTS archives(id INTEGER PRIMARY KEY,name TEXT,created TEXT,path TEXT,
        filename TEXT,data BLOB,updated TEXT)""")
    c.execute("CREATE TABLE IF NOT EXISTS worker_chain(client TEXT,position INTEGER,worker TEXT,PRIMARY KEY(client,position))")
    # This same schema is used for an archived period file AND for whatever a period
    # switch points DB_PATH at. Editing/adding while looking at one of those must still
    # be able to write an audit-log line and a note without "no such table" blowing up
    # the save (see audit_write's own belt-and-suspenders guard for when an even OLDER
    # archive file, made before this line existed, still lacks these tables).
    c.execute("""CREATE TABLE IF NOT EXISTS audit_log(
        id INTEGER PRIMARY KEY, created TEXT, username TEXT, action TEXT, entity_type TEXT,
        entity_id TEXT, week TEXT, old_value TEXT, new_value TEXT, detail TEXT
    )""")
    c.execute("""CREATE TABLE IF NOT EXISTS notes(
        id INTEGER PRIMARY KEY, entity_type TEXT, entity_id TEXT, week TEXT,
        note TEXT, author TEXT, created TEXT
    )""")
    # Columns added after a period was first archived. Idempotent, like the CREATEs.
    _ensure_column(c, "allocations", "start_time TEXT")
    _ensure_column(c, "allocations", "end_time TEXT")
    c.execute("""CREATE TABLE IF NOT EXISTS cmv_week_info(
        id INTEGER PRIMARY KEY, week TEXT, worker TEXT, source_worker TEXT, work_date TEXT, day TEXT,
        client TEXT, service TEXT, hours REAL, start_time TEXT, end_time TEXT, status TEXT,
        source_note TEXT, source_file TEXT, imported_at TEXT
    )""")
    c.execute("CREATE INDEX IF NOT EXISTS idx_cmv_week_worker ON cmv_week_info(week,worker)")
    con.commit(); con.close()

def ensure_period_schema(path):
    """Bring a saved period file up to the current schema before it is opened.

    Saved periods are frozen at whatever schema existed the day they were archived;
    nothing else ever migrates them. Every new table or column added to init_db()
    since then would otherwise raise "no such table/column" inside a read path —
    and one swallowed exception in load_period_snapshot() is enough to leave every
    page showing the PREVIOUS period's data. All statements here are IF NOT EXISTS /
    guarded ALTERs, so on an up-to-date file this is a handful of no-ops on a local
    SQLite file — cheap enough to run on every switch."""
    if not path or path == DEFAULT_DB_PATH or not os.path.exists(path):
        return
    try:
        _create_period_schema(path)
    except Exception as exc:
        try: _perf_log("ensure_period_schema_failed",0.0,f"{os.path.basename(path)}: {exc}")
        except Exception: pass

def infer_ap_category(description):
    """Map a CareMile invoice line's description text onto Allocate Pro's own 4 categories
    (Weekday/Saturday/Sunday/Public Holiday) — the description already says which one for
    8 of the 10 real line-item types seen in this data; the 2 that don't say (Early Childhood
    Supports, Skill Development) default to Weekday as the most common case."""
    t = (description or "").lower()
    if "public holiday" in t: return "Public Holiday"
    if "saturday" in t: return "Saturday"
    if "sunday" in t: return "Sunday"
    return "Weekday"

def caremile_push_all_periods(username):
    """Pulls the full 40-week CareMile historical dataset (invoices + bank payments) straight
    into 7 real, dedicated 6-week Allocate Pro periods — no separate matching screen. Safe to
    re-run any time (it only ever clears/rewrites ITS OWN previously-imported rows, identified
    by their note text, never anything you've added by hand afterward); never touches whichever
    period is currently live.
      - Every bank payment becomes a REAL worker with a REAL worker_week wage — the same table
        Wages shows for any worker, whether tagged to a participant or not.
      - Every invoice line becomes REAL allocation rows, one per actual calendar day it covers,
        on the real weekday it fell on — the same 'allocations' ledger Add Allocation writes to
        by hand. If a participant already has support worker(s) tagged (hist_sw_roster, carried
        over from any earlier tagging), hours split across them. Otherwise hours land on a
        clearly-named placeholder worker for that participant (e.g. "Wafaa — Unassigned
        (CareMile)") so the hours are still real, visible, reportable allocations — reassign
        them to the correct real worker any time with the app's own Edit Allocation screen,
        exactly like fixing any manually-entered row.
      - client_estimate / client_period are filled to match, so the period doesn't show a false
        over- or under-allocation flag.
    Hours are estimated as invoice $ ÷ Allocate Pro's own standard category rate — NDIS billing
    rates and Allocate Pro's internal worker rates are different rate structures, so this is a
    consistent approximation, not an exact clocked figure.
    Returns a summary dict, including the path to switch into for Period 1."""
    data = get_historical_data()
    inv_lines = data['invoice_lines']
    all_weeks = sorted(data['weeks'], key=lambda w: w['week_ending'])
    meta = data['meta']
    participants = meta['participants']

    PERIOD_SIZE = 6
    periods = [all_weeks[i:i + PERIOD_SIZE] for i in range(0, len(all_weeks), PERIOD_SIZE)]

    overrides = hist_list_wage_overrides()
    added = hist_list_added_wages()

    def wage_entries_for(week):
        out = []
        for dft in week['ocr_draft']:
            out.append({'id': dft['id'], 'name': dft['name'], 'amount_raw': dft['amount_raw']})
        for a in added:
            if a['week_ending'] == week['week_ending']:
                out.append({'id': a['id'], 'name': a['name'], 'amount_raw': a['amount']})
        return out

    def wage_value(entry):
        ov = overrides.get(entry['id'])
        if ov: return ov['name'], ov['amount']
        return entry['name'], entry['amount_raw']

    def parse_amt(s):
        try: return float(re.sub(r'[^0-9.]', '', str(s)) or 0)
        except Exception: return 0.0

    participant_workers = {}   # participant -> [worker names already tagged to them], if any
    for r in hist_list_sw_roster():
        participant_workers.setdefault(r["participant"], [])
        if r["worker_name"] not in participant_workers[r["participant"]]:
            participant_workers[r["participant"]].append(r["worker_name"])

    folder = os.path.join(ARCHIVE_DIR, "caremile_historical")
    os.makedirs(folder, exist_ok=True)

    total_workers = set()
    total_allocations = 0
    total_unassigned_lines = 0
    total_unassigned_amount = 0.0
    period1_path = None

    for pidx, period_weeks in enumerate(periods):
        path = os.path.join(folder, f"caremile_period_{pidx + 1}.db")
        is_new = not os.path.exists(path)
        _create_period_schema(path)
        if pidx == 0:
            period1_path = path

        period_label = f"CareMile Historical — Period {pidx + 1} ({period_weeks[0]['week_ending']} to {period_weeks[-1]['week_ending']})"
        we_to_label = {wk['week_ending']: f"Week {i + 1}" for i, wk in enumerate(period_weeks)}
        we_set = set(we_to_label)

        pcon = sqlite3.connect(path)
        pcon.execute("INSERT OR REPLACE INTO meta(k,v) VALUES('period_name',?)", (period_label,))
        for we, wl in we_to_label.items():
            pcon.execute("INSERT OR REPLACE INTO meta(k,v) VALUES(?,?)", (f"date_{wl}", we))
        # clear only OUR OWN previously-imported allocations before rewriting — never touches
        # anything the user has added by hand into this same dedicated period since
        pcon.execute("DELETE FROM allocations WHERE note LIKE 'CareMile historical %'")

        # --- wages: EVERY bank payment this period becomes a real worker + real wage ---
        wage_sum = {}
        for wk in period_weeks:
            wl = we_to_label[wk['week_ending']]
            for entry in wage_entries_for(wk):
                name, amt = wage_value(entry)
                name = (name or "").strip()
                if not name: continue
                wage_sum[(name, wl)] = wage_sum.get((name, wl), 0.0) + parse_amt(amt)
                total_workers.add(name)
        for (worker, _wl) in wage_sum:
            pcon.execute("INSERT OR IGNORE INTO workers(name) VALUES(?)", (worker,))
        workers_this_period = {w for (w, _l) in wage_sum}
        for w in workers_this_period:
            for wl in we_to_label.values():
                pcon.execute("INSERT OR IGNORE INTO worker_week(worker,week,wage) VALUES(?,?,0)", (w, wl))
        for (worker, wl), amt in wage_sum.items():
            pcon.execute("INSERT OR REPLACE INTO worker_week(worker,week,wage) VALUES(?,?,?)", (worker, wl, round(amt, 2)))

        # --- clients, estimated hours, and real allocation rows (one per actual day worked) ---
        for p in participants:
            pcon.execute("INSERT OR IGNORE INTO clients(name) VALUES(?)", (p,))

        est = {}
        period_totals = {}
        for l in inv_lines:
            if l['week_ending'] not in we_set: continue
            wl = we_to_label[l['week_ending']]
            cat = infer_ap_category(l['description'])
            line_hours = l['amount'] / global_rates_on(l.get('week_ending'))[cat]
            est[(l['participant'], wl, cat)] = est.get((l['participant'], wl, cat), 0.0) + line_hours

            workers_for_line = participant_workers.get(l['participant'], [])
            placeholder_used = False
            if not workers_for_line:
                placeholder = f"{l['participant']} — Unassigned (CareMile)"
                workers_for_line = [placeholder]
                placeholder_used = True
                pcon.execute("INSERT OR IGNORE INTO workers(name) VALUES(?)", (placeholder,))
                total_workers.add(placeholder)
                total_unassigned_lines += 1
                total_unassigned_amount += l['amount']

            day_names = l.get('day_names_in_week') or []
            n_days = max(1, len(day_names))
            hours_per_day = line_hours / n_days
            hours_per_day_per_worker = hours_per_day / len(workers_for_line)
            rate = GLOBAL_RATES[cat]
            days_to_write = day_names if day_names else [""]
            note = ("CareMile historical — no support worker tagged yet, reassign via Edit Allocation"
                    if placeholder_used else
                    "CareMile historical — auto-imported from invoice/wage data (estimated hours)")
            for day_name in days_to_write:
                for worker in workers_for_line:
                    h = round(hours_per_day_per_worker, 4)
                    if h <= 0: continue
                    cost = round(h * rate, 2)
                    pcon.execute("""INSERT INTO allocations(week,worker,client,category,hours,rate,cost,day,note,created_by,created)
                        VALUES(?,?,?,?,?,?,?,?,?,?,?)""",
                        (wl, worker, l['participant'], cat, h, rate, cost, day_name, note, username, datetime.now().isoformat()))
                    total_allocations += 1
                    period_totals[(l['participant'], cat)] = period_totals.get((l['participant'], cat), 0.0) + h

        for (client, wl, cat), hours in est.items():
            pcon.execute("INSERT OR REPLACE INTO client_estimate(client,week,category,hours) VALUES(?,?,?,?)", (client, wl, cat, round(hours, 2)))
        for (client, cat), hours in period_totals.items():
            pcon.execute("INSERT OR REPLACE INTO client_period(client,category,hours) VALUES(?,?,?)", (client, cat, round(hours, 2)))

        pcon.commit(); pcon.close()
        if is_new:
            try: register_period(period_label, path)
            except Exception: pass

    return {
        "n_periods": len(periods),
        "n_workers": len(total_workers),
        "n_allocations": total_allocations,
        "n_unassigned": total_unassigned_lines,
        "unassigned_amount": round(total_unassigned_amount, 2),
        "period1_path": period1_path,
    }

def suggest_name_from_filename(path):
    """Strip the auto-appended _YYYYMMDD_HHMMSS timestamp that archive_current_period
    adds, recovering the name closest to what was actually typed when it was archived."""
    import re as _re
    base=os.path.splitext(os.path.basename(path))[0]
    stripped=_re.sub(r'_\d{8}_\d{6}$','',base)
    return stripped.replace("_"," ").strip() or base

def scan_unregistered_archives(folder=None):
    """Find every .db file sitting in the archives folder that ISN'T already
    registered (by path) — e.g. files you copied in manually. Returns a list of
    (path, suggested_name). Never touches the registry itself — only PLANS what
    could be registered, for the caller to review before committing."""
    folder=folder or ARCHIVE_DIR
    if not os.path.isdir(folder): return []
    already=set(p for _,p in list_periods())
    found=[]
    for fn in sorted(os.listdir(folder)):
        if not fn.lower().endswith(".db"): continue
        full=os.path.join(folder,fn)
        if full in already: continue
        found.append((full, suggest_name_from_filename(full)))
    return found

def _export_current_period_to_sqlite(path):
    """Create a portable SQLite snapshot of the current cloud period."""
    if os.path.exists(path):
        os.remove(path)
    _create_period_schema(path)
    # Snapshot the already-synced LOCAL replica. This used to iterate every table
    # through a cloud connection while the Archive button was blocking the UI.
    src = read_connect()
    dst = sqlite3.connect(path)
    try:
        # The period snapshot contains the working period and users, not the master archive
        # BLOB registry. worker_rate (per-worker rate exceptions) and notes travel with the
        # period too — without them a re-costed allocation inside the archive silently
        # fell back to global rates and every comment vanished from the saved copy.
        for table in ("users","workers","worker_week","worker_rate","clients","client_week","client_period",
                      "client_estimate","allocations","meta","worker_chain","notes","cmv_week_info"):
            _copy_table(src, dst, table)
        dst.commit()
    finally:
        dst.close(); src.close()


def archive_current_period(name):
    """Save a complete snapshot of CURRENT live data and register it centrally."""
    os.makedirs(ARCHIVE_DIR, exist_ok=True)
    stamp=datetime.now().strftime("%Y%m%d_%H%M%S")
    safe="".join(ch for ch in name if ch.isalnum() or ch in " -_").strip() or "period"
    path=os.path.join(ARCHIVE_DIR, f"{safe}_{stamp}.db")
    if CLOUD_ENABLED:
        # This function is called by the serial background writer in 5.7. Pull any
        # previously committed mutations before taking the portable snapshot. The
        # snapshot is taken from the LOCAL replica, and the very next step (start a
        # new period) wipes the cloud — so a replica that failed to catch up would
        # archive an incomplete copy and then delete the rest for good. Refuse instead.
        if not sync_cloud_now():
            raise RuntimeError("Could not sync with the cloud before archiving — nothing was changed. "
                               "Check the connection and try again.")
        _export_current_period_to_sqlite(path)
        register_period(name, path)
    else:
        con=sqlite3.connect(DEFAULT_DB_PATH); con.commit(); con.close()
        shutil.copy2(DEFAULT_DB_PATH, path)
        con=sqlite3.connect(DEFAULT_DB_PATH)
        con.execute("INSERT INTO archives(name,created,path) VALUES(?,?,?)",(name,datetime.now().isoformat(),path))
        con.commit(); con.close()
    return path


def list_archives():
    """Return archive metadata instantly.

    The old cloud path SELECTed the `data` BLOB for EVERY archive and rewrote every
    saved database file whenever Period Manager opened or search text changed. That
    could transfer megabytes and freeze the app for tens of seconds. 5.7 reads the
    small AppData metadata cache only; a selected archive is downloaded on demand.
    """
    if CLOUD_ENABLED:
        return [(int(r.get("id") or 0),r.get("name") or r.get("filename") or "Saved period",
                 r.get("created") or "",_archive_path_for(r.get("filename")))
                for r in _archive_index_rows() if r.get("filename")]
    con=sqlite3.connect(DEFAULT_DB_PATH); rows=con.execute("SELECT id,name,created,path FROM archives ORDER BY id DESC").fetchall(); con.close()
    return rows


def switch_active_db(path):
    """Switch between live and a materialised archive without re-running schema setup.

    Older builds called init_db() on EVERY period switch. In cloud mode that meant a
    long series of CREATE/ALTER statements against Turso before the screen could move.
    The live schema is already initialised at startup and archive files already carry
    their schema, so switching should be a pointer change only.
    """
    global DB_PATH, APP_LAST_PERIOD
    if path != DEFAULT_DB_PATH and not os.path.exists(path):
        raise FileNotFoundError(path)
    # A saved period is a LOCAL file, so topping up its schema is cheap — and it is the
    # only thing standing between an old archive and "no such table" inside every read.
    ensure_period_schema(path)
    DB_PATH = path
    _week_date_cache_clear()
    # Remember where the user was working. The app always opens on the LIVE period, so
    # without this, hours entered inside a saved period simply vanish from view after a
    # restart and look lost. See App._offer_last_period().
    try:
        APP_LAST_PERIOD = "" if path==DEFAULT_DB_PATH else path
        _save_appearance()
    except Exception:
        pass


def list_periods():
    """All switchable periods from local metadata only; no cloud wait."""
    periods=[("Current (live — cloud)" if CLOUD_ENABLED else "Current (live)", DEFAULT_DB_PATH)]
    if CLOUD_ENABLED:
        periods.extend((name,path) for _aid,name,_created,path in list_archives())
        return periods
    if os.path.exists(DEFAULT_DB_PATH):
        con=sqlite3.connect(DEFAULT_DB_PATH)
        try: rows=con.execute("SELECT id,name,created,path FROM archives ORDER BY id DESC").fetchall()
        except sqlite3.OperationalError: rows=[]
        con.close()
        periods.extend((name,path) for _aid,name,_created,path in rows if os.path.exists(path))
    return periods


def period_date_range(path):
    """Fast Week 1 → Week 6 label for the period manager without switching periods.

    The live cloud period is always read from the local embedded replica so opening an
    archived period never makes this helper look at a stale placeholder database.
    """
    try:
        if path==DB_PATH:
            d1=get_week_date("Week 1"); d6=get_week_date("Week 6")
        else:
            source=(CLOUD_REPLICA_PATH if (CLOUD_ENABLED and path==DEFAULT_DB_PATH) else path)
            if not os.path.exists(source): return "Saved period • opens from cloud"
            con=sqlite3.connect(source,timeout=0.15)
            rows=dict(con.execute("SELECT k,v FROM meta WHERE k IN (?,?)",("date_Week 1","date_Week 6")).fetchall())
            con.close()
            d1=rows.get("date_Week 1",""); d6=rows.get("date_Week 6","")
        a=parse_week_date(d1); b=parse_week_date(d6)
        if a and b: return f"{a.strftime('%d %b %Y')}  →  {b.strftime('%d %b %Y')}"
    except Exception: pass
    return "6-week period"

def rename_period_record(path, new_name):
    new_name=(new_name or "").strip()
    if not new_name: raise ValueError("Period name cannot be blank.")
    if path==DEFAULT_DB_PATH:
        # Current/live period name lives in its meta table.
        old_db=DB_PATH
        if old_db==DEFAULT_DB_PATH:
            set_period_name(new_name)
        else:
            con=_master_connect(); con.execute("INSERT OR REPLACE INTO meta(k,v) VALUES('period_name',?)",(new_name,)); con.commit(); con.close()
        return
    # Keep the snapshot's own name useful if it is opened directly later.
    if os.path.exists(path):
        try:
            con=sqlite3.connect(path); con.execute("INSERT OR REPLACE INTO meta(k,v) VALUES('period_name',?)",(new_name,)); con.commit(); con.close()
        except Exception: pass
    if CLOUD_ENABLED:
        fn=os.path.basename(path); con=_master_connect()
        now=datetime.now().isoformat(timespec='seconds')
        con.execute("UPDATE archives SET name=?,updated=? WHERE filename=?",(new_name,now,fn))
        con.commit(); con.close()
        _archive_index_upsert(new_name,fn,updated=now)
        # Renaming metadata does not require re-uploading the entire period BLOB.
    else:
        con=sqlite3.connect(DEFAULT_DB_PATH); con.execute("UPDATE archives SET name=? WHERE path=?",(new_name,path)); con.commit(); con.close()

def delete_period_record(path):
    """Permanently remove one archived period. Never accepts the current/live period."""
    if path==DEFAULT_DB_PATH: raise ValueError("The current live period cannot be deleted.")
    if CLOUD_ENABLED:
        fn=os.path.basename(path); con=_master_connect(); con.execute("DELETE FROM archives WHERE filename=?",(fn,)); con.commit(); con.close(); _archive_index_remove(fn)
    else:
        con=sqlite3.connect(DEFAULT_DB_PATH); con.execute("DELETE FROM archives WHERE path=?",(path,)); con.commit(); con.close()
    try:
        if os.path.exists(path): os.remove(path)
    except Exception: pass

def active_period_label():
    if DB_PATH==DEFAULT_DB_PATH:
        nm=get_period_name()
        return nm if nm else ("Current (live — cloud)" if CLOUD_ENABLED else "Current (live)")
    # Never contact the archive registry just to paint a top-bar label.
    try:
        con=sqlite3.connect(DB_PATH,timeout=0.1)
        row=con.execute("SELECT v FROM meta WHERE k='period_name'").fetchone(); con.close()
        if row and row[0]: return row[0]
    except Exception:
        pass
    return suggest_name_from_filename(DB_PATH)


def touch_last_edited():
    """Record a data change. The editor session lets the UI ignore its own save refresh."""
    now=datetime.now().isoformat()
    editor=globals().get("TEAM_SESSION_ID","")
    con=connect()
    con.execute("INSERT OR REPLACE INTO meta(k,v) VALUES('last_edited',?)",(now,))
    con.execute("INSERT OR REPLACE INTO meta(k,v) VALUES('last_editor_session',?)",(editor,))
    con.commit(); con.close()
    _sync_archive_blob(DB_PATH)


def database_change_token():
    """Compact token for detecting real data edits, not presence heartbeats."""
    if CLOUD_ENABLED and DB_PATH == DEFAULT_DB_PATH:
        return ("cloud", get_last_edited(DEFAULT_DB_PATH) or "",
                get_last_editor_session(DEFAULT_DB_PATH) or "")
    if CLOUD_ENABLED and DB_PATH != DEFAULT_DB_PATH:
        return ("archive-cloud", archive_cloud_change_token(DB_PATH) or "")
    try:
        return ("file", os.path.getmtime(DB_PATH))
    except Exception:
        return ("none", "")



def get_last_editor_session(path=None):
    p=path or DB_PATH
    if CLOUD_ENABLED and p==DEFAULT_DB_PATH:
        # Same fix as get_last_edited(): read the live replica directly by file,
        # never via read_connect() — which would resolve against whatever period
        # is globally active right now, not necessarily the live one being asked about.
        if not os.path.exists(CLOUD_REPLICA_PATH): return ""
        con=sqlite3.connect(CLOUD_REPLICA_PATH,timeout=0.15)
        try: r=con.execute("SELECT v FROM meta WHERE k='last_editor_session'").fetchone()
        except Exception: r=None
        con.close()
        return r[0] if r else ""
    if not os.path.exists(p):
        return ""
    try:
        con=sqlite3.connect(p)
        r=con.execute("SELECT v FROM meta WHERE k='last_editor_session'").fetchone()
        con.close()
        return r[0] if r else ""
    except Exception:
        return ""

def get_last_edited(path=None):
    p = path or DB_PATH
    if CLOUD_ENABLED and p == DEFAULT_DB_PATH:
        # Read the LIVE period's own local replica file directly — never via
        # read_connect(), which resolves against whatever period is globally active
        # right now. If the caller is asking about the live period specifically
        # (e.g. Period Manager rendering the "Current (live)" row) while a different,
        # saved period is the one currently open, read_connect() would silently
        # report that OTHER period's timestamp here instead of the live one's.
        if not os.path.exists(CLOUD_REPLICA_PATH): return None
        con=sqlite3.connect(CLOUD_REPLICA_PATH,timeout=0.15)
        try: r=con.execute("SELECT v FROM meta WHERE k='last_edited'").fetchone()
        except Exception: r=None
        con.close(); return r[0] if r else None
    if not os.path.exists(p): return None
    con=sqlite3.connect(p)
    try: r=con.execute("SELECT v FROM meta WHERE k='last_edited'").fetchone()
    except sqlite3.OperationalError: r=None
    con.close()
    return r[0] if r else None



# ---------- LIVE TEAM PRESENCE ----------
TEAM_SESSION_ID = uuid.uuid4().hex
TEAM_MACHINE = os.environ.get("COMPUTERNAME") or socket.gethostname() or "Computer"
TEAM_ONLINE_SECONDS = 120

def _parse_iso_dt(value):
    try:
        return datetime.fromisoformat(value)
    except Exception:
        return None


def _team_heartbeat_remote(payload):
    """Network presence write on a daemon thread, never on Tk's UI thread."""
    if not CLOUD_ENABLED:
        return
    username,role,period,week,activity,log_activity=payload
    now=datetime.now().isoformat(timespec="seconds")
    con=None
    try:
        import libsql
        con=_libsql_connect(database=TURSO_DATABASE_URL,auth_token=TURSO_AUTH_TOKEN)
        con.execute("""INSERT INTO team_presence(session_id,username,role,machine,period,week,activity,last_seen)
            VALUES(?,?,?,?,?,?,?,?)
            ON CONFLICT(session_id) DO UPDATE SET
                username=excluded.username,
                role=excluded.role,
                machine=excluded.machine,
                period=excluded.period,
                week=excluded.week,
                activity=excluded.activity,
                last_seen=excluded.last_seen""",
            (TEAM_SESSION_ID,username,role,TEAM_MACHINE,period,week,activity,now))
        # Speed-first: presence only. Detailed click-by-click activity logging was
        # generating unnecessary cloud writes and is intentionally disabled.
        con.commit()
    except Exception:
        pass
    finally:
        try:
            if con: con.close()
        except Exception:
            pass

def team_heartbeat(username, role, period, week, activity, log_activity=False):
    """Publish this user's current screen to the central team database."""
    if not CLOUD_ENABLED or not username:
        return
    now = datetime.now().isoformat(timespec="seconds")
    try:
        con = _master_connect()
        con.execute("""INSERT INTO team_presence(session_id,username,role,machine,period,week,activity,last_seen)
            VALUES(?,?,?,?,?,?,?,?)
            ON CONFLICT(session_id) DO UPDATE SET
                username=excluded.username,
                role=excluded.role,
                machine=excluded.machine,
                period=excluded.period,
                week=excluded.week,
                activity=excluded.activity,
                last_seen=excluded.last_seen""",
            (TEAM_SESSION_ID, username, role, TEAM_MACHINE, period, week, activity, now))
        if log_activity:
            con.execute("""INSERT INTO team_activity(username,machine,period,week,activity,created)
                VALUES(?,?,?,?,?,?)""",
                (username, TEAM_MACHINE, period, week, activity, now))
            con.execute("""DELETE FROM team_activity
                WHERE id NOT IN (SELECT id FROM team_activity ORDER BY id DESC LIMIT 2000)""")
        con.commit()
        con.close()
    except Exception:
        pass

def team_mark_offline():
    if not CLOUD_ENABLED:
        return
    try:
        con = _master_connect()
        con.execute("DELETE FROM team_presence WHERE session_id=?", (TEAM_SESSION_ID,))
        con.commit()
        con.close()
    except Exception:
        pass

def team_online_users(sync_first=False):
    if not CLOUD_ENABLED:
        return []
    try:
        if sync_first:
            sync_cloud_now()
        con = read_connect()
        rows = con.execute("""SELECT session_id,username,role,machine,period,week,activity,last_seen
            FROM team_presence ORDER BY username,machine""").fetchall()
        con.close()
    except Exception:
        return []
    cutoff = datetime.now() - timedelta(seconds=TEAM_ONLINE_SECONDS)
    result=[]
    for row in rows:
        seen=_parse_iso_dt(row[7])
        if seen and seen >= cutoff:
            result.append(row)
    return result

def team_recent_activity(limit=40, sync_first=False):
    if not CLOUD_ENABLED:
        return []
    try:
        if sync_first:
            sync_cloud_now()
        con = read_connect()
        rows = con.execute("""SELECT username,machine,period,week,activity,created
            FROM team_activity ORDER BY id DESC LIMIT ?""", (int(limit),)).fetchall()
        con.close()
        return rows
    except Exception:
        return []

def archive_cloud_change_token(path):
    """Local-only token for a saved period.

    5.6 polled the Turso primary here from Tk every few seconds while an archive was
    open. A slow network could therefore freeze the entire application even when the
    user was not saving anything. Archived periods are snapshots, so the local file
    mtime plus cached archive metadata is the correct lightweight token.
    """
    if not path or path == DEFAULT_DB_PATH:
        return ""
    fn=os.path.basename(path)
    cached=""
    try:
        for row in _archive_index_rows():
            if row.get("filename")==fn:
                cached=row.get("updated") or row.get("created") or ""
                break
    except Exception:
        pass
    try: local=str(os.path.getmtime(path))
    except Exception: local="missing"
    return cached+"|"+local

def refresh_archive_from_cloud(path):
    if not CLOUD_ENABLED or not path or path == DEFAULT_DB_PATH:
        return False
    try:
        con=_master_connect()
        row=con.execute("SELECT data FROM archives WHERE filename=? ORDER BY id DESC LIMIT 1",
                        (os.path.basename(path),)).fetchone()
        con.close()
        if not row or row[0] is None:
            return False
        os.makedirs(os.path.dirname(path),exist_ok=True)
        payload=bytes(row[0])
        if payload[:2]==b"\x1f\x8b":
            try: payload=gzip.decompress(payload)
            except Exception: pass
        with open(path,"wb") as f:
            f.write(payload)
        return True
    except Exception:
        return False

def get_period_name():
    # Period labels are UI data: always read the local replica/cache.
    con=read_connect()
    try: r=con.execute("SELECT v FROM meta WHERE k='period_name'").fetchone()
    except Exception: r=None
    con.close()
    return r[0] if r else None


def set_period_name(name):
    now=datetime.now().isoformat(timespec="seconds")
    con=background_write_connect()
    try:
        con.execute("INSERT OR REPLACE INTO meta(k,v) VALUES('period_name',?)",((name or "").strip(),))
        con.execute("INSERT OR REPLACE INTO meta(k,v) VALUES('last_edited',?)",(now,))
        con.execute("INSERT OR REPLACE INTO meta(k,v) VALUES('last_editor_session',?)",(globals().get("TEAM_SESSION_ID","") or "",))
        con.commit()
    finally: con.close()


def start_new_period(keep_workers, keep_clients, worker_list=None, client_list=None):
    """Reset the live six-week period in one background cloud transaction.

    worker_list / client_list (optional) name EXACTLY who the new period starts with —
    picked from every saved period. worker_list items are (name, rates): rates is the
    special-rate dict to keep, or {} / None for the global rates."""
    if worker_list is not None: keep_workers=True
    if client_list is not None: keep_clients=True
    client_names=[]
    if client_list is not None:
        client_names=[n for n,_x in client_list]
    elif keep_clients:
        rc=read_connect()
        try: client_names=[r[0] for r in rc.execute("SELECT name FROM clients").fetchall()]
        finally: rc.close()
    con=_master_connect(); c=con.cursor(); now=datetime.now().isoformat(timespec="seconds")
    try:
        c.execute("DELETE FROM allocations")
        c.execute("DELETE FROM client_estimate")
        c.execute("DELETE FROM client_period")
        c.execute("DELETE FROM client_week")
        c.execute("DELETE FROM worker_week")
        c.execute("DELETE FROM cmv_week_info")
        # Allocation ids restart from 1 in the new period (no AUTOINCREMENT), so any
        # note left on "allocation 17" last period would otherwise reappear on this
        # period's unrelated allocation 17. Comments belong to the archived copy.
        try: c.execute("DELETE FROM notes WHERE entity_type='allocation'")
        except Exception: pass
        if not keep_workers:
            c.execute("DELETE FROM workers")
            # Their rate exceptions and client chains go with them.
            try: c.execute("DELETE FROM worker_rate")
            except Exception: pass
            try: c.execute("DELETE FROM worker_chain")
            except Exception: pass
        if worker_list is not None:
            keep=[n for n,_r in worker_list]
            have=[r[0] for r in c.execute("SELECT name FROM workers").fetchall()]
            gone=[n for n in have if n not in keep]
            for n in gone:
                c.execute("DELETE FROM workers WHERE name=?",(n,))
                try: c.execute("DELETE FROM worker_chain WHERE worker=?",(n,))
                except Exception: pass
            c.execute("CREATE TABLE IF NOT EXISTS worker_rate(worker TEXT,category TEXT,rate REAL,PRIMARY KEY(worker,category))")
            c.execute("DELETE FROM worker_rate")
            for n,rates in worker_list:
                c.execute("INSERT OR IGNORE INTO workers(name) VALUES(?)",(n,))
                for cat,rate in (rates or {}).items():
                    c.execute("INSERT OR REPLACE INTO worker_rate(worker,category,rate) VALUES(?,?,?)",(n,cat,float(rate)))
        if client_list is not None:
            have=[r[0] for r in c.execute("SELECT name FROM clients").fetchall()]
            for n in have:
                if n not in client_names:
                    c.execute("DELETE FROM clients WHERE name=?",(n,))
                    try: c.execute("DELETE FROM worker_chain WHERE client=?",(n,))
                    except Exception: pass
            for n in client_names: c.execute("INSERT OR IGNORE INTO clients(name) VALUES(?)",(n,))
        if not keep_clients:
            c.execute("DELETE FROM clients")
            try: c.execute("DELETE FROM worker_chain")
            except Exception: pass
        elif client_names:
            try: con.executemany("INSERT OR IGNORE INTO client_period(client,category,hours) VALUES(?,?,0)",[(nm,cat) for nm in client_names for cat in CATEGORIES])
            except Exception:
                for nm in client_names:
                    for cat in CATEGORIES:c.execute("INSERT OR IGNORE INTO client_period(client,category,hours) VALUES(?,?,0)",(nm,cat))
        for wk in WEEKS: c.execute("DELETE FROM meta WHERE k=?",("date_"+wk,))
        c.execute("DELETE FROM meta WHERE k=?",("period_name",))
        # Marks the moment THIS period began, so the Audit Log can tell current-period
        # rows apart from older periods' rows (the audit_log table itself is never wiped
        # or archived per period — it's one long history — and "Week 1".."Week 6" get
        # reused every cycle, so without this timestamp a Week filter would silently mix
        # this period's entries with every past period's entries of the same week label).
        c.execute("INSERT OR REPLACE INTO meta(k,v) VALUES('period_started_at',?)",(now,))
        c.execute("INSERT OR REPLACE INTO meta(k,v) VALUES('last_edited',?)",(now,))
        c.execute("INSERT OR REPLACE INTO meta(k,v) VALUES('last_editor_session',?)",(globals().get("TEAM_SESSION_ID","") or "",))
        con.commit()
    finally: con.close()
    switch_active_db(DEFAULT_DB_PATH)

def _hash(pw,salt): return hashlib.pbkdf2_hmac("sha256",pw.encode(),salt.encode(),100000).hex()
def user_count():
    n=_quick_local_user_count()
    if n is not None: return n
    try:
        con=read_connect(); n=con.execute("SELECT COUNT(*) FROM users").fetchone()[0]; con.close(); return int(n or 0)
    except Exception:
        return 0
# User accounts are GLOBAL — they belong to the live cloud database, never to whichever
# saved period happens to be open. These helpers therefore pin themselves to the live
# DB explicitly instead of following DB_PATH: before this, adding a user or resetting a
# password while a saved period was open wrote the account into that archive file.
def _users_read_connect():
    path=CLOUD_REPLICA_PATH if CLOUD_ENABLED else DEFAULT_DB_PATH
    con=sqlite3.connect(path,timeout=1.0)
    try: con.execute("PRAGMA query_only=ON")
    except Exception: pass
    return con
def _users_write_connect():
    return _master_connect()

class UserError(Exception): pass

def create_user(u,pw,role="manager"):
    """Create an account in the live database. Raises UserError with a readable reason
    instead of returning False, so callers can't accidentally treat failure as success."""
    u=(u or "").strip()
    if not u: raise UserError("Username can't be blank.")
    con=_users_write_connect();salt=secrets.token_hex(16)
    try:
        if con.execute("SELECT 1 FROM users WHERE username=?",(u,)).fetchone():
            raise UserError(f"'{u}' already exists — pick a different username.")
        con.execute("INSERT INTO users(username,salt,pwhash,role,created) VALUES(?,?,?,?,?)",
            (u,salt,_hash(pw,salt),role,datetime.now().isoformat()));con.commit()
        return True
    except UserError:
        raise
    except Exception as exc:
        raise UserError(f"Could not create the account: {exc}")
    finally:
        con.close()
def verify_user(u,pw):
    u=(u or "").strip()   # create_user stores names trimmed, so match that on login
    try:
        con=_users_read_connect(); row=con.execute("SELECT salt,pwhash,role FROM users WHERE username=?",(u,)).fetchone(); con.close()
    except Exception:
        return None
    if not row:return None
    return row[2] if secrets.compare_digest(_hash(pw,row[0]),str(row[1] or "")) else None
def list_users():
    """Usernames and roles only — live replica read; never exposes password hashes."""
    con=_users_read_connect()
    try: return con.execute("SELECT username,role,created FROM users ORDER BY username").fetchall()
    finally: con.close()
def reset_password(username, new_password):
    """Set a NEW password for an existing user (e.g. they forgot it) — replaces
    the salt+hash entirely, so the old (forgotten) password stops working."""
    con=_users_write_connect(); salt=secrets.token_hex(16)
    try:
        n=con.execute("UPDATE users SET salt=?,pwhash=? WHERE username=?",(salt,_hash(new_password,salt),username)).rowcount
        con.commit()
        return n>0
    finally: con.close()
def meta_get(k,default=""):
    con=read_connect();r=con.execute("SELECT v FROM meta WHERE k=?",(k,)).fetchone();con.close();return r[0] if r else default
def meta_set(k,v):
    con=connect();con.execute("INSERT OR REPLACE INTO meta(k,v) VALUES(?,?)",(k,str(v)));con.commit();con.close()

# ---------- ENGINE ----------
# ---- Per-worker rate exceptions ----
# By default every worker is paid GLOBAL_RATES. Set a row in worker_rate to give
# ONE worker a different rate for ONE category — everything that computes an
# allocation's $ value for that worker/category then uses their rate instead.
def get_worker_rate(worker,category):
    """This worker's rate override for a category, or None if they use the global rate.
    Periods archived before this feature existed don't have a worker_rate table at all —
    that's not an error, it just means no exceptions were ever possible there."""
    con=read_connect()
    try:
        r=con.execute("SELECT rate FROM worker_rate WHERE worker=? AND category=?",(worker,category)).fetchone()
        return float(r[0]) if r and r[0] is not None else None
    except sqlite3.OperationalError:
        return None
    finally:
        con.close()

def get_worker_rates(worker):
    """All of this worker's overrides as {category: rate} — only categories with an exception.
    See get_worker_rate() note on older periods missing the worker_rate table entirely."""
    con=read_connect()
    try:
        return {cat:float(r) for cat,r in con.execute("SELECT category,rate FROM worker_rate WHERE worker=?",(worker,)).fetchall()}
    except sqlite3.OperationalError:
        return {}
    finally:
        con.close()

def set_worker_rate(worker,category,rate,user="system"):
    """Set (or, if rate is None/blank, clear — reverting to the global rate) one
    worker's rate exception for one category."""
    now=datetime.now().isoformat(timespec="seconds"); con=background_write_connect()
    try:
        # Self-heals periods archived before this feature existed — their file has
        # no worker_rate table at all yet. IF NOT EXISTS makes this a no-op elsewhere.
        con.execute("CREATE TABLE IF NOT EXISTS worker_rate(worker TEXT,category TEXT,rate REAL,PRIMARY KEY(worker,category))")
        old=con.execute("SELECT rate FROM worker_rate WHERE worker=? AND category=?",(worker,category)).fetchone()
        old_txt=f"${float(old[0]):.2f}" if old and old[0] is not None else f"global (${GLOBAL_RATES[category]:.2f})"
        if rate is None or str(rate).strip()=="":
            con.execute("DELETE FROM worker_rate WHERE worker=? AND category=?",(worker,category))
            new_txt=f"global (${GLOBAL_RATES[category]:.2f})"
        else:
            rate=float(rate)
            con.execute("INSERT OR REPLACE INTO worker_rate(worker,category,rate) VALUES(?,?,?)",(worker,category,rate))
            new_txt=f"${rate:.2f}"
        audit_write("EDIT","worker rate",worker,"",f"{category}: {old_txt}",f"{category}: {new_txt}","Worker rate exception changed",user,con)
        con.execute("INSERT OR REPLACE INTO meta(k,v) VALUES('last_edited',?)",(now,))
        con.execute("INSERT OR REPLACE INTO meta(k,v) VALUES('last_editor_session',?)",(globals().get("TEAM_SESSION_ID","") or "",))
        con.commit()
    finally: con.close()

def _rate_day(x):
    try:
        if x is None or x=="": return None
        if isinstance(x,datetime): return x.date()
        if hasattr(x,"year") and hasattr(x,"isoformat"): return x
        return datetime.strptime(str(x)[:10],"%Y-%m-%d").date()
    except Exception: return None

def global_rates_on(on=None):
    """Global rates (no GST) on a date: the new rates from 28 Sep 2026, the old ones before.
    No date = today's rates."""
    d=_rate_day(on)
    if d is None or d.isoformat()>=GLOBAL_RATES_FROM: return GLOBAL_RATES
    return GLOBAL_RATES_OLD

def global_rates_for_week(week):
    """Global rates for 'Week N' of the open period (judged by its week-ending date)."""
    try: return global_rates_on(get_week_date(week)) if week else GLOBAL_RATES
    except Exception: return GLOBAL_RATES

def _rate_is_plain_global(r,cat):
    """True when a stored worker rate is just one of the global sets (old, new, GST)."""
    try: r=float(r)
    except Exception: return False
    return any(abs(r-x[cat])<0.005 for x in (GLOBAL_RATES_OLD,GLOBAL_RATES,GLOBAL_RATES_GST))

def effective_rate(worker,category,worker_rates=None,week=None,on=None):
    """The rate that actually applies for this worker+category: their exception if
    they have one, otherwise GLOBAL_RATES. Pass worker_rates — the snapshot's
    {(worker,category):rate} dict of exceptions — to avoid a DB call when already
    working from the in-RAM snapshot; leave it None (default) to look it up live."""
    g=global_rates_on(on) if on is not None else global_rates_for_week(week)
    if worker_rates is not None:
        r=worker_rates.get((worker,category))
        return float(r) if r is not None else g[category]
    r=get_worker_rate(worker,category)
    return r if r is not None else g[category]

def worker_estimated_hours(remaining_wage,worker=None,worker_rates=None,week=None):
    """Hours per category this much money still covers. Pass `week` so a week before the
    rate change is costed at the old rates, exactly as the save will cost it."""
    if worker is None:
        return {cat: remaining_wage/rate for cat,rate in global_rates_for_week(week).items()}
    return {cat: remaining_wage/effective_rate(worker,cat,worker_rates,week=week) for cat in CATEGORIES}
def allocation_cost(hours,category,worker=None,worker_rates=None,week=None):
    rate=global_rates_for_week(week)[category] if worker is None else effective_rate(worker,category,worker_rates,week=week)
    return hours*rate
def fmt(x): return f"{x:.2f}"

from datetime import date as _date
def fmt_date(iso):
    try:
        y,m,d=iso.split("-"); return _date(int(y),int(m),int(d)).strftime("%d %B %Y")
    except Exception: return ""
def fmt_datetime(iso):
    """Format a full ISO datetime (e.g. from last_edited) as 'dd Month yyyy, HH:MM'."""
    if not iso: return "never"
    try: return datetime.fromisoformat(iso).strftime("%d %B %Y, %H:%M")
    except Exception: return iso
_WEEK_DATE_CACHE={}
def _week_date_cache_clear():
    _WEEK_DATE_CACHE.clear()
def get_week_date(week):
    """Week-ending date (ISO) for 'Week N' in the active period.

    Cached per (period file, week): this is read from inside paint handlers and
    per-row loops (week pills, chart labels, report sort keys), and each uncached
    call opened a fresh SQLite connection. The cache is cleared whenever the dates
    can change — a date save, a payroll import, a period switch, a snapshot reload."""
    key=(DB_PATH,week)
    v=_WEEK_DATE_CACHE.get(key)
    if v is None:
        v=meta_get("date_"+week, DEFAULT_WEEK_DATES[WEEKS.index(week)])
        _WEEK_DATE_CACHE[key]=v
    return v
def set_week_dates_batch(mapping):
    """Save any subset of week-ending dates with ONE commit."""
    rows=[("date_"+wk,str(iso)) for wk,iso in mapping.items() if wk in WEEKS]
    if not rows:return 0
    now=datetime.now().isoformat(timespec="seconds"); con=background_write_connect()
    try:
        _multi_upsert(con,"meta",("k","v"),("k",),("v",),rows)
        con.execute("INSERT OR REPLACE INTO meta(k,v) VALUES('last_edited',?)",(now,))
        con.execute("INSERT OR REPLACE INTO meta(k,v) VALUES('last_editor_session',?)",(globals().get("TEAM_SESSION_ID","") or "",))
        con.commit(); _week_date_cache_clear(); return len(rows)
    finally: con.close()

def set_week_date(week, iso):
    return set_week_dates_batch({week:iso})
def week_label(week):
    fd=fmt_date(get_week_date(week))
    return f"{week} — Week Ending {fd}" if fd else week
def week_label_short(week):
    """Tight contexts: 'Week 1 · 04 Apr 2026' (never bare)."""
    try:
        iso=get_week_date(week); y,m,d=iso.split("-")
        short=_date(int(y),int(m),int(d)).strftime("%d %b %Y")
        return f"{week} · {short}"
    except Exception:
        return week

from datetime import timedelta as _timedelta
# Week ENDS on Sunday (the week-ending date). Days go backward to Monday (-6).
DAY_OFFSET = {"Sunday":0,"Saturday":-1,"Friday":-2,"Thursday":-3,"Wednesday":-4,"Tuesday":-5,"Monday":-6}
def allocation_date(week, day):
    """Real calendar date of an allocation, from its week's ending (Sunday) date and weekday.
    Returns '06 April 2026' style, or '' if no day set / bad date."""
    if not day or day not in DAY_OFFSET: return ""
    try:
        y,m,d=get_week_date(week).split("-")
        sunday=_date(int(y),int(m),int(d))
        real=sunday+_timedelta(days=DAY_OFFSET[day])
        return real.strftime("%d %B %Y")
    except Exception:
        return ""


def day_with_date(week, day, style="%d %b", blank="—"):
    """'Friday · 15 Nov' — the day name together with its real calendar date.

    Use this ANYWHERE an allocation's day is shown to the user (tables, dropdowns,
    previews). A bare weekday name is ambiguous across a 6-week period — "Friday"
    happens six times — so every list of allocations carries the date with it.
    Falls back to the bare day name if the week has no usable date, and to `blank`
    when the allocation has no day set at all."""
    day=(day or "").strip()
    if not day: return blank
    try:
        y,m,d=get_week_date(week).split("-")
        real=_date(int(y),int(m),int(d))+_timedelta(days=DAY_OFFSET[day])
        return f"{day} · {real.strftime(style)}"
    except Exception:
        return day


# ---------- FAST UI SNAPSHOTS ----------
# These functions intentionally use a handful of SQL queries instead of the
# previous N+1 pattern (one query per worker/client/category/widget).

def fast_week_header_stats(week):
    con=read_connect()
    allocs=con.execute("""SELECT id,week,worker,client,category,hours,rate,cost,day,note,
                                created_by,start_time,end_time
                         FROM allocations WHERE week=? ORDER BY id""",(week,)).fetchall()
    clients=[r[0] for r in con.execute("SELECT name FROM clients ORDER BY rowid").fetchall()]
    est_rows=con.execute("""SELECT client,category,COALESCE(hours,0)
                            FROM client_estimate WHERE week=?""",(week,)).fetchall()
    wage_total=con.execute("""SELECT COALESCE(SUM(wage),0)
                              FROM worker_week WHERE week=?""",(week,)).fetchone()[0] or 0
    con.close()

    est_by_client={c:0.0 for c in clients}
    total_est=0.0
    for client,cat,hours in est_rows:
        value=float(hours or 0)*GLOBAL_RATES.get(cat,0)
        est_by_client[client]=est_by_client.get(client,0.0)+value
        total_est+=value
    placed_total=sum(float(r[7] or 0) for r in allocs)
    return allocs,clients,est_by_client,total_est,float(wage_total),placed_total

def fast_wages_for_week(week):
    con=read_connect()
    rows=con.execute("""
        SELECT w.name,
               COALESCE(ww.wage,0) AS start_wage,
               COALESCE(SUM(a.cost),0) AS placed
        FROM workers w
        LEFT JOIN worker_week ww
          ON ww.worker=w.name AND ww.week=?
        LEFT JOIN allocations a
          ON a.worker=w.name AND a.week=?
        GROUP BY w.name,ww.wage,w.rowid
        ORDER BY w.rowid
    """,(week,week)).fetchall()
    con.close()
    return [(name,float(start or 0),float(placed or 0)) for name,start,placed in rows]

def fast_clients_for_week(week):
    con=read_connect()
    clients=[r[0] for r in con.execute("SELECT name FROM clients ORDER BY rowid").fetchall()]
    period_rows=con.execute("SELECT client,category,COALESCE(hours,0) FROM client_period").fetchall()
    week_rows=con.execute("""SELECT client,category,COALESCE(SUM(hours),0)
                             FROM allocations WHERE week=?
                             GROUP BY client,category""",(week,)).fetchall()
    period_alloc_rows=con.execute("""SELECT client,category,COALESCE(SUM(hours),0)
                                    FROM allocations
                                    GROUP BY client,category""").fetchall()
    con.close()

    period={(c,cat):float(h or 0) for c,cat,h in period_rows}
    placed_week={(c,cat):float(h or 0) for c,cat,h in week_rows}
    placed_period={(c,cat):float(h or 0) for c,cat,h in period_alloc_rows}
    return clients,period,placed_week,placed_period

def fast_reconcile_for_week(week):
    con=read_connect()
    clients=[r[0] for r in con.execute("SELECT name FROM clients ORDER BY rowid").fetchall()]
    estimates=con.execute("""SELECT client,category,COALESCE(hours,0)
                             FROM client_estimate WHERE week=?""",(week,)).fetchall()
    placed=con.execute("""SELECT client,category,COALESCE(SUM(hours),0)
                          FROM allocations WHERE week=?
                          GROUP BY client,category""",(week,)).fetchall()
    con.close()
    e={(c,cat):float(h or 0) for c,cat,h in estimates}
    p={(c,cat):float(h or 0) for c,cat,h in placed}
    return clients,e,p

def allocation_dialog_snapshot(week):
    """Load everything the Add Allocation dialog needs in a few local queries.

    The old recompute() performed O(workers + clients*categories) database calls
    on every dropdown change / keystroke. This snapshot turns recompute into pure
    dictionary arithmetic until a save occurs.
    """
    con=read_connect()
    workers=[r[0] for r in con.execute("SELECT name FROM workers ORDER BY rowid").fetchall()]
    clients=[r[0] for r in con.execute("SELECT name FROM clients ORDER BY rowid").fetchall()]
    wage_rows=con.execute("""
        SELECT w.name,COALESCE(ww.wage,0),COALESCE(SUM(a.cost),0)
        FROM workers w
        LEFT JOIN worker_week ww ON ww.worker=w.name AND ww.week=?
        LEFT JOIN allocations a ON a.worker=w.name AND a.week=?
        GROUP BY w.name,ww.wage,w.rowid ORDER BY w.rowid
    """,(week,week)).fetchall()
    est_rows=con.execute("SELECT client,category,COALESCE(hours,0) FROM client_estimate WHERE week=?",(week,)).fetchall()
    period_rows=con.execute("SELECT client,category,COALESCE(hours,0) FROM client_period").fetchall()
    week_alloc=con.execute("""SELECT id,worker,client,category,hours,cost,day,start_time,end_time
                              FROM allocations WHERE week=? ORDER BY id""",(week,)).fetchall()
    period_added=con.execute("""SELECT client,category,COALESCE(SUM(hours),0)
                                 FROM allocations GROUP BY client,category""").fetchall()
    con.close()

    return {
        "workers":workers,
        "clients":clients,
        "wage_left":{w:float(start or 0)-float(used or 0) for w,start,used in wage_rows},
        "estimate":{(c,cat):float(h or 0) for c,cat,h in est_rows},
        "period":{(c,cat):float(h or 0) for c,cat,h in period_rows},
        "period_added":{(c,cat):float(h or 0) for c,cat,h in period_added},
        "week_alloc":week_alloc,
    }


# ---------- SMART LOCAL SNAPSHOT / AUDIT / NOTES ----------
def load_period_snapshot():
    """Load the whole active 6-week period from the LOCAL replica into memory."""
    con=read_connect()
    workers=[r[0] for r in con.execute("SELECT name FROM workers ORDER BY rowid").fetchall()]
    clients=[r[0] for r in con.execute("SELECT name FROM clients ORDER BY rowid").fetchall()]
    wages={(w,wk):float(v or 0) for w,wk,v in con.execute("SELECT worker,week,wage FROM worker_week").fetchall()}
    # Periods archived before the per-worker rate exceptions feature existed have no
    # worker_rate table at all — NOT an error, just means no exceptions there. Without
    # this guard, opening any such saved period raised "no such table: worker_rate" here,
    # which the caller (App._reload_snapshot -> refresh()) silently swallows — leaving
    # the WHOLE snapshot frozen on whatever period was loaded before, so every page kept
    # showing the previous (often live) period's data no matter which saved period you opened.
    try:
        worker_rates={(w,cat):float(r or 0) for w,cat,r in con.execute("SELECT worker,category,rate FROM worker_rate").fetchall()}
    except sqlite3.OperationalError:
        worker_rates={}
    period={(c,cat):float(h or 0) for c,cat,h in con.execute("SELECT client,category,hours FROM client_period").fetchall()}
    estimates={(c,wk,cat):float(h or 0) for c,wk,cat,h in con.execute("SELECT client,week,category,hours FROM client_estimate").fetchall()}
    try:
        est_auto={(c,wk,cat) for c,wk,cat in con.execute("SELECT client,week,category FROM client_estimate WHERE COALESCE(auto,0)=1").fetchall()}
    except Exception:
        est_auto=set()
    allocs=con.execute("""SELECT id,week,worker,client,category,hours,rate,cost,day,note,created_by,created,start_time,end_time
                          FROM allocations ORDER BY id""").fetchall()
    try:
        cmv_info=con.execute("""SELECT id,week,worker,source_worker,work_date,day,client,service,hours,start_time,end_time,status,source_note,source_file,imported_at
                                FROM cmv_week_info ORDER BY work_date,id""").fetchall()
    except Exception:
        cmv_info=[]
    # Notes and audit are deliberately NOT loaded into every working snapshot.
    # They are auxiliary screens and can contain hundreds/thousands of rows; loading
    # them after every allocation/client save made core editing heavier for no benefit.
    con.close()
    return {"workers":workers,"clients":clients,"wages":wages,"worker_rates":worker_rates,"period":period,
            "estimates":estimates,"est_auto":est_auto,"allocations":allocs,"cmv_info":cmv_info,"notes":[],"audit":[]}

