def snapshot_derived(snap):
    by_week={wk:[] for wk in WEEKS}; worker_period_alloc={}; worker_week_alloc={}; client_period_alloc={}; client_week_alloc={}
    for r in snap["allocations"]:
        aid,wk,w,c,cat,hours,rate,cost,day,note,created_by,created,st,et=r
        by_week.setdefault(wk,[]).append(r)
        worker_period_alloc[w]=worker_period_alloc.get(w,0.0)+float(cost or 0)
        worker_week_alloc[(w,wk)]=worker_week_alloc.get((w,wk),0.0)+float(cost or 0)
        client_period_alloc[(c,cat)]=client_period_alloc.get((c,cat),0.0)+float(hours or 0)
        client_week_alloc[(c,wk,cat)]=client_week_alloc.get((c,wk,cat),0.0)+float(hours or 0)
    total_paid=sum(float(v or 0) for v in snap["wages"].values())
    total_reconciled=sum(float(r[7] or 0) for r in snap["allocations"])
    estimate_hours_total=sum(float(v or 0) for v in snap.get("estimates",{}).values())
    allocated_hours_total=sum(float(v or 0) for v in client_period_alloc.values())
    return {"by_week":by_week,"worker_period_alloc":worker_period_alloc,"worker_week_alloc":worker_week_alloc,
            "client_period_alloc":client_period_alloc,"client_week_alloc":client_week_alloc,
            "total_paid":total_paid,"total_reconciled":total_reconciled,"total_remaining":total_paid-total_reconciled,
            "client_hours_total":sum(float(v or 0) for v in snap["period"].values()),
            "client_hours_used":allocated_hours_total,
            "estimate_hours_total":estimate_hours_total,
            "estimate_hours_used":allocated_hours_total,
            "estimate_hours_remaining":estimate_hours_total-allocated_hours_total}

def audit_write(action,entity_type,entity_id="",week="",old_value="",new_value="",detail="",username="system",con=None):
    # The audit trail is a diagnostic side record, never the operation itself. A worker's
    # allocation (or a wage/client edit) must NEVER be lost or rolled back just because
    # writing ITS audit-log line failed — e.g. an archived/switched-to period database,
    # which doesn't carry an audit_log table. Flag, never block: swallow any failure here
    # instead of letting it abort the real save that called this.
    own=False
    if con is None: con=background_write_connect(); own=True
    try:
        con.execute("""INSERT INTO audit_log(created,username,action,entity_type,entity_id,week,old_value,new_value,detail)
                       VALUES(?,?,?,?,?,?,?,?,?)""",
                    (datetime.now().isoformat(timespec="seconds"),username,action,entity_type,str(entity_id or ""),
                     week or "",str(old_value or ""),str(new_value or ""),detail or ""))
        if own: con.commit()
    except Exception as exc:
        try: _perf_log("audit_write_failed",0.0,f"{action} {entity_type} {entity_id}: {exc}")
        except Exception: pass
    finally:
        if own: con.close()

