def estimate_period_hours(snap, client, category):
    """Sum the six weekly client estimates for one client/category.

    Allocate Pro users build the estimate period week-by-week, so the smart UI uses
    this total for estimate-left displays.  The separate client_period table remains
    untouched for legacy actual/reporting logic.
    """
    return sum(float(snap.get("estimates",{}).get((client,wk,category),0.0) or 0.0) for wk in WEEKS)

def reconciliation_health(snap,der):
    paid=der["total_paid"]; rem=der["total_remaining"]
    base=(100.0 if paid<=0 and abs(rem)<0.01 else (0.0 if paid<=0 else max(0.0,100.0-abs(rem)/paid*100.0)))
    over_workers=sum(1 for w in snap["workers"] for wk in WEEKS
                     if snap["wages"].get((w,wk),0.0)-der["worker_week_alloc"].get((w,wk),0.0)<-0.01)
    # Health follows the six weekly estimates shown throughout the smart workspace.
    over_clients=sum(1 for c in snap["clients"] for cat in CATEGORIES
                     if estimate_period_hours(snap,c,cat)-der["client_period_alloc"].get((c,cat),0.0)<-0.01)
    score=max(0,int(round(base-min(20,over_workers*2)-min(20,over_clients*2))))
    return score,over_workers,over_clients

# ---------- SPEED-FIRST SQL HELPERS ----------
def _multi_upsert(con, table, columns, conflict_columns, update_columns, rows, batch_rows=180):
    """Upsert many rows using a handful of SQL statements instead of executemany.

    Turso/libSQL can otherwise turn an executemany into many protocol operations.
    Keeping each statement below SQLite's parameter limit makes client/wage imports
    dramatically cheaper while preserving one transaction/commit.
    """
    rows=list(rows or [])
    if not rows:
        return 0
    cols=",".join(columns); conflict=",".join(conflict_columns)
    updates=",".join(f"{c}=excluded.{c}" for c in update_columns)
    total=0; width=len(columns)
    # Conservative parameter count for broad SQLite compatibility.
    max_rows=max(1,min(int(batch_rows),900//max(1,width)))
    for start in range(0,len(rows),max_rows):
        chunk=rows[start:start+max_rows]
        values_sql=",".join(["("+",".join(["?"]*width)+")"]*len(chunk))
        sql=f"INSERT INTO {table}({cols}) VALUES {values_sql} ON CONFLICT({conflict}) DO UPDATE SET {updates}"
        params=[]
        for row in chunk: params.extend(row)
        con.execute(sql,params); total+=len(chunk)
    return total

