def list_workers():
    con=read_connect();r=[x[0] for x in con.execute("SELECT name FROM workers ORDER BY rowid").fetchall()];con.close();return r

def worker_has_allocations(name):
    con=read_connect(); n=con.execute("SELECT COUNT(*) FROM allocations WHERE worker=?",(name,)).fetchone()[0]; con.close()
    return n>0

def delete_worker(name):
    """Delete an unused worker in one transaction."""
    if worker_has_allocations(name):
        raise ValueError(f"'{name}' has allocations on record — deleting them would break the audit trail. You can stop assigning new work to them instead; their history stays intact.")
    con=background_write_connect(); now=datetime.now().isoformat(timespec="seconds")
    try:
        c=con.cursor()
        c.execute("DELETE FROM workers WHERE name=?",(name,))
        c.execute("DELETE FROM worker_week WHERE worker=?",(name,))
        c.execute("DELETE FROM worker_chain WHERE worker=?",(name,))
        c.execute("DELETE FROM worker_rate WHERE worker=?",(name,))
        c.execute("DELETE FROM cmv_week_info WHERE worker=?",(name,))
        c.execute("INSERT OR REPLACE INTO meta(k,v) VALUES('last_edited',?)",(now,))
        c.execute("INSERT OR REPLACE INTO meta(k,v) VALUES('last_editor_session',?)",(globals().get("TEAM_SESSION_ID","") or "",))
        con.commit()
    finally: con.close()

def rename_worker(old_name,new_name):
    """Rename a worker everywhere with one transaction and one remote commit."""
    old_name=(old_name or "").strip(); new_name=(new_name or "").strip()
    if not new_name: raise ValueError("New name can't be blank.")
    if new_name==old_name:return
    rc=read_connect()
    try: clash=rc.execute("SELECT 1 FROM workers WHERE name=?",(new_name,)).fetchone()
    finally: rc.close()
    if clash: raise ValueError(f"'{new_name}' already exists as a worker — pick a different name.")
    con=background_write_connect(); now=datetime.now().isoformat(timespec="seconds")
    try:
        c=con.cursor()
        c.execute("UPDATE workers SET name=? WHERE name=?",(new_name,old_name))
        c.execute("UPDATE worker_week SET worker=? WHERE worker=?",(new_name,old_name))
        c.execute("UPDATE allocations SET worker=? WHERE worker=?",(new_name,old_name))
        c.execute("UPDATE worker_chain SET worker=? WHERE worker=?",(new_name,old_name))
        c.execute("UPDATE worker_rate SET worker=? WHERE worker=?",(new_name,old_name))
        c.execute("UPDATE cmv_week_info SET worker=? WHERE worker=?",(new_name,old_name))
        c.execute("UPDATE notes SET entity_id=? WHERE entity_type='worker' AND entity_id=?",(new_name,old_name))
        c.execute("INSERT OR REPLACE INTO meta(k,v) VALUES('last_edited',?)",(now,))
        c.execute("INSERT OR REPLACE INTO meta(k,v) VALUES('last_editor_session',?)",(globals().get("TEAM_SESSION_ID","") or "",))
        con.commit()
    finally: con.close()

def worker_wage_left(worker,week):
    con=read_connect()
    start=con.execute("SELECT COALESCE(wage,0) FROM worker_week WHERE worker=? AND week=?",(worker,week)).fetchone()
    start=start[0] if start else 0
    used=con.execute("SELECT COALESCE(SUM(cost),0) FROM allocations WHERE worker=? AND week=?",(worker,week)).fetchone()[0]
    con.close();return start-used

