def get_client_period_hours(client,category):
    con=read_connect();r=con.execute("SELECT hours FROM client_period WHERE client=? AND category=?",(client,category)).fetchone();con.close();return r[0] if r else 0
def client_period_added(client,category):
    """All hours allocated to this client/category across the WHOLE period (all 6 weeks)."""
    con=read_connect();v=con.execute("SELECT COALESCE(SUM(hours),0) FROM allocations WHERE client=? AND category=?",(client,category)).fetchone()[0];con.close();return v
def client_period_left(client,category):
    """Period total minus everything allocated this period."""
    return get_client_period_hours(client,category)-client_period_added(client,category)

