    def _toggle_sidebar(self):
        APP_FOLDS["sidebar"]=not bool(APP_FOLDS.get("sidebar",False))
        _save_appearance()
        self._build_sidebar()
        try:
            for name,b in self.nav_buttons.items():
                b.config(bg=SIDEBAR_ACTIVE if name==self._route else SIDEBAR,fg=SIDEBAR_ACTIVE_TEXT if name==self._route else SIDEBAR_TEXT)
        except Exception: pass
        if hasattr(self,"alloc_tree"): self.root.after(150,self._alloc_fit_page_size)

