        mkbtn(r1,"⤓  Excel",self._dir_export,CONTROL,fg=TEXT).pack(side="right",padx=(6,0))
        mkbtn(r1,"↻  Refresh",lambda:self._dir_load(force=True),CONTROL,fg=TEXT).pack(side="right",padx=(6,0))
