    def _refresh_cmv_info_workspace(self):
        if not hasattr(self,"cmv_info_tree"):return
        wk=self.cur_week.get(); fw=self.cmv_info_worker.get().strip()
        workers=sorted({r[2] for r in self._snapshot.get("cmv_info",[]) if r[1]==wk})
        self.cmv_info_worker_combo.configure(values=[""]+workers)
        rows=[]
        for r in self._snapshot.get("cmv_info",[]):
            rid,rwk,w,src,wd,day,client,service,hours,st,et,status,note,source_file,imported=r
            if rwk!=wk or (fw and w!=fw):continue
            rows.append((rid,(w,day,wd,"CareMile VIC",client,fmt(hours),service,status),("even",)))
        self._tree_replace(self.cmv_info_tree,rows)
        self.cmv_info_status.config(text=f"{len(rows)} CareMile source row{'s' if len(rows)!=1 else ''} • double-click for times/notes")

    def _cmv_info_selected_detail(self):
        if not hasattr(self,"cmv_info_tree"):return
        sel=self.cmv_info_tree.selection()
        if not sel:return
        rid=str(sel[0]); row=next((r for r in self._snapshot.get("cmv_info",[]) if str(r[0])==rid),None)
        if not row:return
        _id,wk,w,src,wd,day,client,service,hours,st,et,status,note,source_file,imported=row
        msg=(f"{w}  •  {day} {wd}\nCompany: CareMile VIC\nSource worker: {src}\nClient/source: {client}\nService: {service}\n"
             f"Hours: {fmt(hours)}\nScheduled: {st or '—'} – {et or '—'}\nStatus: {status or '—'}\n\n"
             f"Source note:\n{note or '—'}\n\nFile: {source_file or '—'}")
        messagebox.showinfo("CMV Week Info",msg,parent=self.root)

    @staticmethod
    def _tree_replace(tree,rows):
        children=tree.get_children()
        if children: tree.delete(*children)
        for iid,values,tags in rows:
            kw={"values":values,"tags":tags}
            if iid is not None: kw["iid"]=str(iid)
            tree.insert("","end",**kw)
        _ap_update_empty(tree)

    def _reload_snapshot(self):
        t0=time.perf_counter()
        # Allocations still syncing to the cloud (temporary negative id) haven't
        # reached the local replica yet, so a plain reload would make them vanish
        # from the screen until the sync catches up — even though nothing was lost.
        # Carry them across the reload; they drop out naturally once the real sync
        # completes and replaces their id (or rolls them back on failure).
        # CRITICAL: only carry forward within the SAME period. If DB_PATH changed
        # since the snapshot in memory was taken (the user opened a different/saved
        # period via Period Manager), those pending rows belong to the OLD period —
        # carrying them into the newly opened one would leak one period's data into
        # another's view. This was the exact cause of periods appearing to "share"
        # data after switching.
        same_period = hasattr(self,"_snapshot") and getattr(self,"_snapshot_db_path",None)==DB_PATH
        pending=[r for r in self._snapshot.get("allocations",[]) if str(r[0]).startswith("-")] if same_period else []
        old_ids={str(r[0]) for r in self._snapshot.get("allocations",[])} if same_period else set()
        _week_date_cache_clear()
        try:
            self._snapshot=load_period_snapshot()
        except sqlite3.OperationalError:
            # Almost always "database is locked" while the replica is mid-sync — one
            # short retry beats leaving the previous period's numbers on screen.
            time.sleep(0.25)
            self._snapshot=load_period_snapshot()
        self._snapshot_db_path=DB_PATH
        if pending:
            have={str(r[0]) for r in self._snapshot["allocations"]}
            resolved=getattr(self,"_resolved_ids",{}) or {}
            # rows that arrived with this reload (were not on screen before) = shifts whose
            # cloud save already finished; a temporary copy of the same shift is dropped
            def _k(r): return (r[1],r[2],r[3],r[4],round(float(r[5] or 0),4),r[8] or "",(r[12] if len(r)>12 else "") or "",(r[13] if len(r)>13 else "") or "")
            arrived={}
            for r in self._snapshot["allocations"]:
                if str(r[0]) not in old_ids: arrived[_k(r)]=arrived.get(_k(r),0)+1
            keep=[]
            for r in pending:
                if str(r[0]) in have or str(r[0]) in resolved: continue
                k=_k(r)
                if arrived.get(k,0)>0: arrived[k]-=1; continue
                keep.append(r)
            self._snapshot["allocations"].extend(keep)
        self._derived=snapshot_derived(self._snapshot)
        _perf_log("reload_snapshot",time.perf_counter()-t0)

    def _cache_redraw(self):
        """Recalculate everything from RAM only — no database/network access."""
        t0=time.perf_counter(); self._derived=snapshot_derived(self._snapshot); self._update_all_from_cache(); _perf_log("cache_redraw",time.perf_counter()-t0)

    def _cache_add_worker(self,name):
        if name not in self._snapshot["workers"]: self._snapshot["workers"].append(name)
        for wk in WEEKS:self._snapshot["wages"].setdefault((name,wk),0.0)
        self._cache_redraw()

    def _cache_rename_worker(self,old,new):
        self._snapshot["workers"]=[new if w==old else w for w in self._snapshot["workers"]]
        self._snapshot["wages"]={(new if w==old else w,wk):v for (w,wk),v in self._snapshot["wages"].items()}
        self._snapshot["worker_rates"]={(new if w==old else w,cat):v for (w,cat),v in self._snapshot.get("worker_rates",{}).items()}
        rows=[]
        for r in self._snapshot["allocations"]:
            rr=list(r)
            if rr[2]==old:rr[2]=new
            rows.append(tuple(rr))
        self._snapshot["allocations"]=rows; self._cache_redraw()

    def _cache_delete_worker(self,name):
        self._snapshot["workers"]=[w for w in self._snapshot["workers"] if w!=name]
        self._snapshot["wages"]={(w,wk):v for (w,wk),v in self._snapshot["wages"].items() if w!=name}
        self._snapshot["worker_rates"]={(w,cat):v for (w,cat),v in self._snapshot.get("worker_rates",{}).items() if w!=name}
        self._cache_redraw()

    def _cache_set_worker_rate(self,worker,category,rate):
        wr=self._snapshot.setdefault("worker_rates",{})
        if rate is None:
            wr.pop((worker,category),None)
        else:
            wr[(worker,category)]=float(rate)
        self._cache_redraw()

    def _cache_rename_client(self,old,new):
        self._snapshot["clients"]=[new if c==old else c for c in self._snapshot["clients"]]
        self._snapshot["period"]={(new if c==old else c,cat):v for (c,cat),v in self._snapshot["period"].items()}
        self._snapshot["estimates"]={(new if c==old else c,wk,cat):v for (c,wk,cat),v in self._snapshot["estimates"].items()}
        rows=[]
        for r in self._snapshot["allocations"]:
            rr=list(r)
            if rr[3]==old:rr[3]=new
            rows.append(tuple(rr))
        self._snapshot["allocations"]=rows; self._cache_redraw()

    def _cache_set_wages(self,changes):
        for w,wk,v in changes:self._snapshot["wages"][(w,wk)]=float(v or 0)
        self._cache_redraw()

    def _cache_add_client(self,name):
        if name not in self._snapshot["clients"]:self._snapshot["clients"].append(name)
        for cat in CATEGORIES:self._snapshot["period"].setdefault((name,cat),0.0)
        for wk in WEEKS:
            for cat in CATEGORIES:self._snapshot["estimates"].setdefault((name,wk,cat),0.0)
        self._cache_redraw()

    def _cache_set_client_data(self,client,period_values,estimate_values):
        for cat,v in period_values.items():self._snapshot["period"][(client,cat)]=float(v or 0)
        for key,v in estimate_values.items():
            wk,cat=key; k3=(client,wk,cat)
            if abs(float(self._snapshot["estimates"].get(k3,0.0) or 0)-float(v or 0))>1e-9:
                self._snapshot.setdefault("est_auto",set()).discard(k3)     # typed now = a plan
            self._snapshot["estimates"][k3]=float(v or 0)
        self._cache_redraw()

    def _cache_delete_allocation(self,aid):
        old=next((r for r in self._snapshot["allocations"] if str(r[0])==str(aid)),None)
        self._snapshot["allocations"]=[r for r in self._snapshot["allocations"] if str(r[0])!=str(aid)]
        if old is not None: self._cache_sync_estimate(old[3],old[1],old[4])
        self._cache_redraw()

    def _cache_replace_allocation_id(self,old_id,new_id):
        rows=[]; dup=any(str(r[0])==str(new_id) for r in self._snapshot["allocations"])
        for r in self._snapshot["allocations"]:
            if str(r[0])==str(old_id):
                if dup: continue            # the saved row is already here (a reload brought it) - drop the copy
                rr=list(r); rr[0]=new_id; r=tuple(rr)
            rows.append(r)
        self._snapshot["allocations"]=rows
        if dup:
            if not hasattr(self,"_resolved_ids"): self._resolved_ids={}
            self._resolved_ids[str(old_id)]=new_id
            self._cache_redraw()
            if getattr(self,"_route","")=="Allocations": self._refresh_current_route()
            self._resolve_pending_id(old_id,new_id)
            return
        # The per-week lists the tables draw from hold their own copies of each row, so
        # they must be patched too — otherwise the table keeps the temporary id and a
        # Delete/Edit on it acts on nothing. Still no full redraw: totals don't change.
        try:
            for _wk,_lst in (self._derived.get("by_week") or {}).items():
                for _i,_r in enumerate(_lst):
                    if str(_r[0])==str(old_id):
                        _rr=list(_r); _rr[0]=new_id; _lst[_i]=tuple(_rr)
        except Exception:
            pass
        if not hasattr(self,"_resolved_ids"): self._resolved_ids={}
        self._resolved_ids[str(old_id)]=new_id
        if getattr(self,"_route","")=="Allocations": self._refresh_current_route()
        self._resolve_pending_id(old_id,new_id)

    def _real_id(self,aid):
        """Map a temporary id that has since synced onto its real id (else unchanged)."""
        return getattr(self,"_resolved_ids",{}).get(str(aid),aid)

    def _cache_restore_allocation_row(self,row,replace_id=None):
        if replace_id is not None:
            self._snapshot["allocations"]=[r for r in self._snapshot["allocations"] if str(r[0])!=str(replace_id)]
        if row is not None:
            self._snapshot["allocations"]=[r for r in self._snapshot["allocations"] if str(r[0])!=str(row[0])]
            self._snapshot["allocations"].append(tuple(row))
            self._cache_sync_estimate(row[3],row[1],row[4])
        self._cache_redraw()
        if replace_id is not None: self._resolve_pending_id(replace_id,None)

    def _run_when_id_ready(self,aid,on_ready,on_failed=None):
        """Run on_ready(real_id) once this allocation has a real (non-temporary) id.
        If aid is already real, runs immediately. If it's still a provisional
        (negative, still-syncing) id, queues the callback instead of blocking the
        caller — it fires automatically the moment the pending cloud save for this
        allocation resolves. on_failed() runs instead if that save ends up failing
        (the allocation never actually made it to the cloud, so there's nothing to
        edit/delete)."""
        aid=self._real_id(aid)
        try: is_real=int(aid)>=0
        except Exception: is_real=True
        if is_real:
            on_ready(aid); return
        self._pending_id_watchers.setdefault(str(aid),[]).append((on_ready,on_failed))

    def _resolve_pending_id(self,provisional_id,real_id):
        watchers=self._pending_id_watchers.pop(str(provisional_id),None)
        if not watchers: return
        for on_ready,on_failed in watchers:
            try:
                if real_id is not None:
                    if on_ready: on_ready(real_id)
                else:
                    if on_failed: on_failed()
            except Exception: pass

    def _cache_upsert_allocation(self,aid,week,worker,client,category,hours,day,user,start_time="",end_time="",existing=False,note=""):
        rate=effective_rate(worker,category,self._snapshot.get("worker_rates"),week=week); cost=float(hours)*rate; now=datetime.now().isoformat(timespec="seconds")
        row=(aid,week,worker,client,category,float(hours),rate,cost,day or "",note or "",user,now,start_time or "",end_time or "")
        old=None
        if existing:
            old=next((r for r in self._snapshot["allocations"] if str(r[0])==str(aid)),None)
            self._snapshot["allocations"]=[row if str(r[0])==str(aid) else r for r in self._snapshot["allocations"]]
        else:self._snapshot["allocations"].append(row)
        self._cache_sync_estimate(client,week,category)
        if old is not None and (old[3],old[1],old[4])!=(client,week,category):
            self._cache_sync_estimate(old[3],old[1],old[4])
        self._cache_redraw()

    def _cache_sync_estimate(self,client,week,category):
        """In-RAM mirror of _sync_estimate_to_allocated: an estimate the app filled in itself
        (auto) follows the allocations UP and DOWN, so the Clients page changes the moment an
        allocation is edited, moved or deleted — not only after the next reload. A figure
        the user typed is a plan and is never touched."""
        try:
            key=(client,week,category)
            est=self._snapshot.setdefault("estimates",{}); auto=self._snapshot.setdefault("est_auto",set())
            current=float(est.get(key,0.0) or 0.0)
            if current>1e-9 and key not in auto: return
            allocated=round(sum(float(r[5] or 0) for r in self._snapshot["allocations"]
                                if r[1]==week and r[3]==client and r[4]==category),2)
            if abs(allocated-current)>1e-9 and (allocated>0 or key in auto):
                est[key]=allocated; auto.add(key)
        except Exception:
            pass

    def _cache_local_estimate_topup(self,client,week,category):
        self._cache_sync_estimate(client,week,category)

    def _offer_last_period(self):
        """The app always starts on the LIVE period. If the user was last working inside
        a SAVED period, everything they entered there is invisible on this screen — the
        workers may not even exist here — and it reads as lost data. Offer to go back."""
        try:
            path=globals().get("APP_LAST_PERIOD","") or ""
            if not path or path==DEFAULT_DB_PATH or DB_PATH!=DEFAULT_DB_PATH: return
            if not os.path.exists(path): return
            name=suggest_name_from_filename(path)
            try:
                for nm,p in list_periods():
                    if p==path: name=nm; break
            except Exception: pass
            if not messagebox.askyesno("Reopen the period you were working in?",
                f"Last time, you were working inside the saved period:\n\n        🗂  {name}\n\n"
                f"Allocate Pro always starts on your CURRENT (live) period, so anything you entered "
                f"in that saved period isn't shown on this screen — it is safely stored in that period, "
                f"not lost.\n\nOpen '{name}' again now?",parent=self.root):
                return
            switch_active_db(path)
            self.refresh()
            self._refresh_period_indicator()
            try: self.period_dates_btn.config(text=self._period_dates_text())
            except Exception: pass
        except Exception:
            pass

    # ----- estimates backfill: bring OLD allocations' estimates up to date -----
    def _estimate_backfill_plan(self,blanks_only=False):
        """Every (client, week, category) whose weekly estimate doesn't cover the hours
        allocated against it, as (client, week, category, old, new). Pure in-RAM — the
        snapshot already holds both sides — so this costs nothing to check.

        blanks_only=True lists only cells with NO estimate at all: that's what the
        automatic one-time catch-up uses, so it can never quietly rewrite a plan the
        user typed. The manual action passes False to re-sync everything on purpose."""
        plan=[]
        for key,alloc in (self._derived.get("client_week_alloc") or {}).items():
            try: client,week,category=key
            except Exception: continue
            a=round(float(alloc or 0),2)
            if a<=0: continue
            cur=float(self._snapshot.get("estimates",{}).get(key,0.0) or 0.0)
            if blanks_only and cur>1e-9: continue
            if a>cur+1e-9: plan.append((client,week,category,cur,a))
        plan.sort(key=lambda r:(r[0],WEEKS.index(r[1]) if r[1] in WEEKS else 99,r[2]))
        return plan

    def _apply_estimate_backfill(self,plan,mark_backfilled=False,on_done=None,parent=None):
        """Apply a backfill plan: local view first, then one cloud commit."""
        parent=parent or self.root
        for c,wk,cat,_old,new in plan:
            self._snapshot.setdefault("estimates",{})[(c,wk,cat)]=new
        if plan: self._cache_redraw()
        rows=[(c,wk,cat,new) for c,wk,cat,_old,new in plan]
        def done(_):
            if on_done:
                try: on_done()
                except Exception: pass
        def fail(exc):
            messagebox.showerror("Could not save estimates",
                f"The estimates were filled in on screen but the cloud save failed:\n\n{exc}\n\n"
                "They will be re-filled next time an allocation is saved.",parent=parent)
        self._background_job(lambda:save_estimates_batch(rows,self.user,mark_backfilled=mark_backfilled),
                             done,fail,label="backfill_estimates")

    def _auto_backfill_estimates_once(self):
        """One-time catch-up for data entered before estimates were auto-filled.

        Only ever runs against the LIVE period (a saved period is history — it is not
        rewritten behind the user's back), only once (a meta flag records it), and only
        raises estimates, never lowers them."""
        try:
            if DB_PATH!=DEFAULT_DB_PATH: return
            if meta_get(ESTIMATE_BACKFILL_FLAG,""): return
        except Exception:
            return
        plan=self._estimate_backfill_plan(blanks_only=True)
        if not plan:
            self._background_job(lambda:save_estimates_batch([],self.user,mark_backfilled=True),
                                 label="backfill_estimates_flag")
            return
        clients=sorted({p[0] for p in plan})
        total=sum(p[4] for p in plan)
        def told():
            messagebox.showinfo("Client estimates filled in from your allocations",
                f"{len(plan)} empty weekly estimate(s) across {len(clients)} client(s) were filled in "
                f"from hours you had already allocated ({fmt(total)}h in total).\n\n"
                "From now on this happens automatically as you save allocations, so you can keep "
                "allocating first and the client estimates keep up on their own.\n\n"
                "Only blank estimates were filled — anything you typed yourself was left exactly as it was. "
                "To re-sync a week you planned by hand, use \"Fill estimates from allocations\" in Manage Clients.",
                parent=self.root)
        self._apply_estimate_backfill(plan,mark_backfilled=True,on_done=told)

    def _fill_estimates_prompt(self,parent=None,on_done=None):
        """Manual 'fill estimates from allocations' — works on whichever period is open."""
        parent=parent or self.root
        plan=self._estimate_backfill_plan()
        if not plan:
            messagebox.showinfo("Nothing to fill",
                "Every client's weekly estimate already covers the hours allocated against it.",parent=parent)
            return
        preview="\n".join(f"  • {c} · {wk} · {CAT_ABBR.get(cat,cat)}:  {fmt(old)}h → {fmt(new)}h"+("   (was blank)" if old<=1e-9 else "   (typed by hand)")
                          for c,wk,cat,old,new in plan[:14])
        more=f"\n  … and {len(plan)-14} more" if len(plan)>14 else ""
        typed=sum(1 for p in plan if p[3]>1e-9)
        warn=(f"\n\n{typed} of these is an estimate you typed yourself — re-syncing it means you will no "
              "longer see that those hours went over the plan." if typed else "")
        if not messagebox.askyesno("Fill estimates from allocations",
            f"Raise {len(plan)} weekly estimate(s) so they match the hours already allocated?\n\n"
            f"{preview}{more}{warn}\n\nEstimates are only ever raised — nothing is lowered or removed.",
            parent=parent):
            return
        self._apply_estimate_backfill(plan,on_done=on_done,parent=parent)

    def _update_all_from_cache(self):
        # Refresh only what is visible. Older builds refreshed Dashboard, current page,
        # notifications and week controls redundantly after every small edit.
        if getattr(self,"_route","Dashboard")=="Dashboard":
            self._refresh_dashboard()
        else:
            self._update_kpis()
            self._refresh_current_route()
            self._refresh_notifications()
            self._update_week_buttons()

    def _week_rows(self,wk=None):
        return self._derived["by_week"].get(wk or self.cur_week.get(),[])

    def _update_week_buttons(self):
        wk=self.cur_week.get()
        for idx,name in enumerate(WEEKS,1):
            planned=sum(self._snapshot.get("estimates",{}).get((c,name,cat),0.0)*GLOBAL_RATES[cat]
                        for c in self._snapshot.get("clients",[]) for cat in CATEGORIES)
            rec=sum(self._derived.get("client_week_alloc",{}).get((c,name,cat),0.0)*GLOBAL_RATES[cat]
                    for c in self._snapshot.get("clients",[]) for cat in CATEGORIES)
            marker=" ✓" if planned>0.01 and abs(planned-rec)<0.01 else (" •" if planned>0.01 else "")
            active=name==wk
            try: dlabel=parse_week_date(get_week_date(name)).strftime("%d %b")
            except Exception: dlabel=""
            for btnset in getattr(self,"week_button_sets",[]):
                b=btnset.get(name)
                if b:
                    b.config(text=f"{idx}{marker}\n{dlabel}",bg=PRIMARY if active else CONTROL,
                             fg="#fff" if active else (SUCCESS if "✓" in marker else TEXT2))
        try:
            label=f"{wk}  •  {fmt_date(get_week_date(wk))}"
            for v in getattr(self,"week_filter_date_vars",[]): v.set(label)
        except Exception:
            pass

    def _guide_status_cached(self,max_age=60):
        """Client-guide status for the selected week; the guide itself is re-read from the
        database at most once a minute (it changes rarely), the numbers every refresh."""
        now=time.monotonic(); c=getattr(self,"_guide_cache",None)
        if c is None or now-c[0]>max_age:
            try: c=(now,load_client_guides())
            except Exception: c=(now,{})
            self._guide_cache=c
        if not c[1]: return []
        try: return guide_status(self._snapshot,self._derived,self.cur_week.get(),c[1])
        except Exception: return []

    def _update_kpis(self):
        # Dashboard headline numbers are always the full 6-week period — no "this week"
        # framing here at all, since that requires knowing which week is currently
        # selected elsewhere in the app, which isn't obvious from this page. Per-week
        # figures live on the Allocations/Wages/Reconcile pages, which are always
        # scoped to whatever week you've clicked in the Week 1-6 strip.
        paid=self._derived["total_paid"]; rec=self._derived["total_reconciled"]; rem=self._derived["total_remaining"]
        client_left=self._derived.get("estimate_hours_remaining",0.0)
        vals={"Paid to Workers":"$"+fmt(paid),"Reconciled":"$"+fmt(rec),
              "Remaining to Reconcile":("-$"+fmt(-rem) if rem<0 else "$"+fmt(rem)),
              "Client Hours Remaining":fmt(client_left)+"h"}
        if hasattr(self,"kpi_vars"):
            for k,v in vals.items(): self.kpi_vars[k][0].set(v)
            self.kpi_vars["Remaining to Reconcile"][1].config(fg=DANGER if rem<0 else (SUCCESS if abs(rem)<0.01 else WARNING))
            self.kpi_vars["Client Hours Remaining"][1].config(fg=DANGER if client_left<-.01 else CYAN)
            estimate_total=self._derived.get("estimate_hours_total",0.0)
            self.kpi_subvars["Paid to Workers"].set("Across all 6 weeks")
            self.kpi_subvars["Reconciled"].set("Across all 6 weeks")
            self.kpi_subvars["Remaining to Reconcile"].set("Across all 6 weeks")
            self.kpi_subvars["Client Hours Remaining"].set(f"6-week estimate: {fmt(estimate_total)}h")
            # Profit (client guide): what this month's allocations invoice minus what they cost.
            st=self._guide_status_cached()
            cards=getattr(self,"kpi_cards",{})
            if "Profit This Month" in cards and "Client Hours Remaining" in cards:
                show,hide=(("Profit This Month","Client Hours Remaining") if st else ("Client Hours Remaining","Profit This Month"))
                if not cards[show].winfo_ismapped():
                    cards[hide].pack_forget(); cards[show].pack(side="left",fill="x",expand=True,padx=(0,0))
            if "Profit This Month" in self.kpi_vars:
                if st:
                    ac=sum(r["act_cost"] for r in st); ai=sum(r["act_invoice"] for r in st); ap_=ai-ac
                    gp=sum(r["money"]["margin"] for r in st); gc=sum(r["money"]["cost"] for r in st)
                    self.kpi_vars["Profit This Month"][0].set(("-$" if ap_<0 else "$")+fmt(abs(ap_)))
                    self.kpi_vars["Profit This Month"][1].config(fg=(DANGER if ap_<0 else SUCCESS))
                    self.kpi_subvars["Profit This Month"].set(f"{st[0]['month_label']} so far · {(ap_/ac*100 if ac else 0):.0f}% on cost · guide ${fmt(gp)}/mo ({(gp/gc*100 if gc else 0):.0f}%)")
                else:
                    self.kpi_vars["Profit This Month"][0].set("—")
                    self.kpi_subvars["Profit This Month"].set("Click to set up the Client guide")

    def _navigate(self,route,publish=True):
        if route not in self.pages: return
        self._route=route; self._active_subtab=route
        for _n,_p in self.pages.items():
            if _n==route: _p.grid(row=0,column=0,sticky="nsew"); _p.tkraise()
            else: _p.grid_remove()
        titles={"Dashboard":("Dashboard","Period intelligence and what needs attention"),
                "Allocations":("Allocations",f"{week_label_short(self.cur_week.get())} • persistent live table"),
                "Wages":("Workers / Paid",f"{week_label_short(self.cur_week.get())} • paid → reconciled → remaining"),
                "Clients":("Clients",f"{week_label_short(self.cur_week.get())} • invoicing hours intelligence"),
                "Reconcile":("Reconcile",f"{week_label_short(self.cur_week.get())} • weekly reconciliation"),
                "CMV Week Info":("CMV Week Info",f"{week_label_short(self.cur_week.get())} • CareMile source reference"),
                "Audit":("Audit","invoiced hours vs allocations • find it, fix it"),
                "Directory":("Directory","every worker and client • before 2026 and 2026 onwards")}
        t,s=titles[route]; self.page_title.config(text=t); self.page_subtitle.config(text=s)
        for name,b in self.nav_buttons.items(): b.config(bg=SIDEBAR_ACTIVE if name==route else SIDEBAR,fg=SIDEBAR_ACTIVE_TEXT if name==route else SIDEBAR_TEXT)
        self._refresh_current_route()
        if publish: self._publish_presence(force_log=True)

    def _select_week(self,wk,publish=True):
        if wk not in WEEKS: return
        self.cur_week.set(wk); self._alloc_page=0; self._update_week_buttons()
        if self._route!="Dashboard":
            self.page_subtitle.config(text=f"{week_label_short(wk)} • "+({"Allocations":"persistent live table","Wages":"paid → reconciled → remaining","Clients":"invoicing hours intelligence","Reconcile":"weekly reconciliation","CMV Week Info":"CareMile source reference","Audit":"invoiced hours vs allocations","Directory":"workers and clients across periods"}.get(self._route,"")))
        self._refresh_current_route()
        if publish: self._publish_presence(force_log=True)

    def _refresh_current_route(self):
        if not hasattr(self,"pages"): return
        if self._route=="Dashboard": self._refresh_dashboard()
        elif self._route=="Allocations": self._refresh_allocations_workspace()
        elif self._route=="Wages": self._refresh_wages_workspace()
        elif self._route=="Clients": self._refresh_clients_workspace()
        elif self._route=="Reconcile": self._refresh_reconcile_workspace()
        elif self._route=="CMV Week Info": self._refresh_cmv_info_workspace()
        elif self._route=="Audit": self._refresh_audit_workspace()
        elif self._route=="Directory": self._refresh_directory_workspace()

    def _refresh_allocations_workspace(self):
        if not hasattr(self,"alloc_tree"): return
        workers=self._snapshot["workers"]; clients=self._snapshot["clients"]
        self.alloc_worker_combo.configure(values=[""]+workers); self.alloc_client_combo.configure(values=[""]+clients)
        rows=self._week_rows(); fw=self.alloc_filter_worker.get(); fc=self.alloc_filter_client.get(); fcat=self.alloc_filter_category.get(); q=self.alloc_quick_search.get().strip().lower()
        shown=[]
        for r in rows:
            aid,wk,w,c,cat,h,rate,cost,day,note,by,created,st,et=r
            if fw and w!=fw: continue
            if fc and c!=fc: continue
            if fcat and cat!=fcat: continue
            blob=f"{w} {c} {cat} {day} {note} {by}".lower()
            if q and q not in blob: continue
            shown.append(r)
        self._alloc_shown_all=shown
        if APP_FOLDS.get("roster",False): self._schedule_roster()
        pages=max(1,(len(shown)+self._alloc_page_size-1)//self._alloc_page_size); self._alloc_page=min(self._alloc_page,pages-1)
        self._alloc_pages=pages
        a=self._alloc_page*self._alloc_page_size; b=a+self._alloc_page_size; page=shown[a:b]
        wk_cur=self.cur_week.get()
        # Small per-refresh memo so a worker/client repeated across several rows on this page is
        # only looked up once - still just dict lookups on the already-cached snapshot/derived
        # aggregates, no new DB calls and no rescanning the full allocation list.
        _wr_cache={}; _cr_cache={}
        def worker_room(w):
            if w not in _wr_cache:
                paid=self._snapshot["wages"].get((w,wk_cur),0.0); rec=self._derived["worker_week_alloc"].get((w,wk_cur),0.0)
                _wr_cache[w]=(paid-rec,paid)
            return _wr_cache[w]
        def client_room(c,cat):
            key=(c,cat)
            if key not in _cr_cache:
                plan=estimate_period_hours(self._snapshot,c,cat); placed=self._derived["client_period_alloc"].get(key,0.0)
                _cr_cache[key]=(plan-placed,plan)
            return _cr_cache[key]
        render=[]
        for i,r in enumerate(page):
            aid,wk,w,c,cat,h,rate,cost,day,note,by,created,st,et=r; times=f"{st or ''}–{et or ''}" if (st or et) else "—"
            wleft,wpaid=worker_room(w); cleft,cplan=client_room(c,cat)
            if wleft<-0.01 or cleft<-0.01: tag="danger"
            elif (wpaid>0 and 0<=wleft<0.1*wpaid) or (cplan>0 and 0<=cleft<0.1*cplan): tag="warning"
            else: tag="odd" if i%2 else "even"
            render.append((aid,(w,c,CAT_ABBR.get(cat,cat),fmt(float(h or 0)),"$"+fmt(float(cost or 0)),day_with_date(wk,day),times,by or "—"),(tag,)))
        self._tree_replace(self.alloc_tree,render); self.alloc_status.config(text=f"{len(shown)} allocations")
        # Say plainly when rows exist beyond this page — the old label read "1-5 of 5" even
        # when only three of those five fitted on screen, which is what made allocations
        # look lost. Now more-than-one-page is called out in the accent colour.
        shown_to=min(b,len(shown))
        if pages>1:
            self.alloc_page_lbl.config(text=f"{a+1 if shown else 0}–{shown_to} of {len(shown)}  ·  page {self._alloc_page+1}/{pages}  ·  scroll ⇣ for more",fg=WARNING)
        else:
            self.alloc_page_lbl.config(text=f"{a+1 if shown else 0}–{shown_to} of {len(shown)}  ·  all shown",fg=TEXT2)
        for btn,ok in ((getattr(self,"alloc_prev_btn",None),self._alloc_page>0),
                       (getattr(self,"alloc_next_btn",None),self._alloc_page<pages-1)):
            if btn is not None:
                try: btn.config(state="normal" if ok else "disabled",fg=TEXT if ok else TEXT2)
                except Exception: pass

        # ---------------- live context bar ----------------
        if fw:
            paid=self._snapshot["wages"].get((fw,wk_cur),0.0); rec=self._derived["worker_week_alloc"].get((fw,wk_cur),0.0); left=paid-rec
            col=DANGER if left<-0.01 else (WARNING if paid>0 and left<0.1*paid else SUCCESS)
            self.ctx_worker_val.config(text=("-$"+fmt(-left) if left<0 else "$"+fmt(left)),fg=col)
            cover=worker_estimated_hours(max(0.0,left),fw,self._snapshot.get("worker_rates",{}),week=wk_cur)
            cover_txt=" · ".join(f"{CAT_ABBR[cc]} {fmt(cover[cc])}h" for cc in CATEGORIES)
            self.ctx_worker_sub.config(text=f"{fw} • paid ${fmt(paid)} this week • could still cover: {cover_txt}")
            self.ctx_worker_badge.config(text=("OVER" if left<-0.01 else ("NEAR LIMIT" if paid>0 and left<0.1*paid else "ON TRACK")),fg=col)
        else:
            # Nothing filtered — this is the page you land on before choosing anything, so
            # show something useful straight away instead of a blank placeholder: a
            # team-wide triage line, still just dict lookups over the already-cached
            # snapshot (same cost as the per-worker case above, just looped).
            over=near=0; team_left=0.0
            for w in workers:
                paid=self._snapshot["wages"].get((w,wk_cur),0.0); rec=self._derived["worker_week_alloc"].get((w,wk_cur),0.0); left=paid-rec
                team_left+=left
                if left<-0.01: over+=1
                elif paid>0 and left<0.1*paid: near+=1
            if over: self.ctx_worker_val.config(text=f"{over} over",fg=DANGER); badge_txt="NEEDS ATTENTION"
            elif near: self.ctx_worker_val.config(text=f"{near} near limit",fg=WARNING); badge_txt="WATCH"
            else: self.ctx_worker_val.config(text="All on track",fg=SUCCESS); badge_txt="ON TRACK"
            self.ctx_worker_sub.config(text=f"{len(workers)} workers this week • ${fmt(team_left)} remaining across the team • filter a worker for their own room")
            self.ctx_worker_badge.config(text=badge_txt,fg=(DANGER if over else (WARNING if near else SUCCESS)))

        if fc:
            cats=[fcat] if fcat else CATEGORIES
            plan_week=sum(self._snapshot["estimates"].get((fc,wk_cur,cc),0.0) for cc in cats)
            placed_week=sum(self._derived["client_week_alloc"].get((fc,wk_cur,cc),0.0) for cc in cats)
            left_week=plan_week-placed_week
            colw=DANGER if left_week<-0.01 else (WARNING if plan_week>0 and left_week<0.1*plan_week else SUCCESS)
            self.ctx_week_val.config(text=f"{fmt(left_week)}h left",fg=colw)
            self.ctx_week_sub.config(text=f"{fc} • {fcat or 'all categories'} • estimate {fmt(plan_week)}h → allocated {fmt(placed_week)}h")
            self.ctx_week_badge.config(text=("OVER" if left_week<-0.01 else ("NEAR LIMIT" if plan_week>0 and left_week<0.1*plan_week else "ON TRACK")),fg=colw)

            plan_period=sum(estimate_period_hours(self._snapshot,fc,cc) for cc in cats)
            placed_period=sum(self._derived["client_period_alloc"].get((fc,cc),0.0) for cc in cats)
            left_period=plan_period-placed_period
            colp=DANGER if left_period<-0.01 else (WARNING if plan_period>0 and left_period<0.1*plan_period else SUCCESS)
            self.ctx_period_val.config(text=f"{fmt(left_period)}h left",fg=colp)
            self.ctx_period_sub.config(text=f"6 weeks • estimate {fmt(plan_period)}h → allocated {fmt(placed_period)}h")
            self.ctx_period_badge.config(text=("OVER" if left_period<-0.01 else ("NEAR LIMIT" if plan_period>0 and left_period<0.1*plan_period else "ON TRACK")),fg=colp)
        else:
            # Same idea for clients: a period-wide triage line instead of a blank card.
            over_w=near_w=0; left_w_total=0.0
            over_p=near_p=0; left_p_total=0.0
            for c in clients:
                plan_w=sum(self._snapshot["estimates"].get((c,wk_cur,cc),0.0) for cc in CATEGORIES)
                placed_w=sum(self._derived["client_week_alloc"].get((c,wk_cur,cc),0.0) for cc in CATEGORIES)
                lw=plan_w-placed_w; left_w_total+=lw
                if lw<-0.01: over_w+=1
                elif plan_w>0 and lw<0.1*plan_w: near_w+=1
                plan_p=sum(estimate_period_hours(self._snapshot,c,cc) for cc in CATEGORIES)
                placed_p=sum(self._derived["client_period_alloc"].get((c,cc),0.0) for cc in CATEGORIES)
                lp=plan_p-placed_p; left_p_total+=lp
                if lp<-0.01: over_p+=1
                elif plan_p>0 and lp<0.1*plan_p: near_p+=1
            if over_w: self.ctx_week_val.config(text=f"{over_w} over",fg=DANGER); wb="NEEDS ATTENTION"
            elif near_w: self.ctx_week_val.config(text=f"{near_w} near limit",fg=WARNING); wb="WATCH"
            else: self.ctx_week_val.config(text="All on track",fg=SUCCESS); wb="ON TRACK"
            self.ctx_week_sub.config(text=f"{len(clients)} clients • {fmt(left_w_total)}h left this week overall • filter a client for their own room")
            self.ctx_week_badge.config(text=wb,fg=(DANGER if over_w else (WARNING if near_w else SUCCESS)))
            if over_p: self.ctx_period_val.config(text=f"{over_p} over",fg=DANGER); pb="NEEDS ATTENTION"
            elif near_p: self.ctx_period_val.config(text=f"{near_p} near limit",fg=WARNING); pb="WATCH"
            else: self.ctx_period_val.config(text="All on track",fg=SUCCESS); pb="ON TRACK"
            self.ctx_period_sub.config(text=f"6 weeks • {fmt(left_p_total)}h left overall • filter a client for their own room")
            self.ctx_period_badge.config(text=pb,fg=(DANGER if over_p else (WARNING if near_p else SUCCESS)))

    def _alloc_filter_changed(self): self._alloc_page=0; self._refresh_allocations_workspace()
    def _alloc_page_move(self,d,focus=None):
        pages=getattr(self,"_alloc_pages",1)
        new=max(0,min(pages-1,self._alloc_page+d))
        moved=new!=self._alloc_page
        self._alloc_page=new; self._refresh_allocations_workspace()
        if moved: self._flash_pager()
        if focus is not None: self._alloc_focus_row(focus)
        return moved

    def _alloc_focus_row(self,index):
        if not hasattr(self,"alloc_tree"): return
        kids=self.alloc_tree.get_children()
        if not kids: return
        iid=kids[index] if -len(kids)<=index<len(kids) else kids[0]
        try:
            self.alloc_tree.focus_set(); self.alloc_tree.selection_set(iid)
            self.alloc_tree.focus(iid); self.alloc_tree.see(iid)
        except Exception: pass

    def _alloc_key_down(self,_e=None):
        kids=self.alloc_tree.get_children(); cur=self.alloc_tree.focus()
        if kids and cur==kids[-1] and self._alloc_page<getattr(self,"_alloc_pages",1)-1:
            self._alloc_page_move(1,focus=0); return "break"
        if kids and not cur:
            self._alloc_focus_row(0); return "break"
        return None

    def _alloc_key_up(self,_e=None):
        kids=self.alloc_tree.get_children(); cur=self.alloc_tree.focus()
        if kids and cur==kids[0] and self._alloc_page>0:
            self._alloc_page_move(-1,focus=-1); return "break"
        return None

    def _alloc_jump(self,first=True):
        self._alloc_page=0 if first else max(0,getattr(self,"_alloc_pages",1)-1)
        self._refresh_allocations_workspace(); self._alloc_focus_row(0 if first else -1)

    def _alloc_wheel_flip(self,units):
        # One page per wheel "push": a fast flick shouldn't fly past five pages at once.
        now=time.time()
        if now-getattr(self,"_alloc_flip_at",0.0)<0.30: return
        if self._alloc_page_move(1 if units>0 else -1): self._alloc_flip_at=now

    def _flash_pager(self):
        lbl=getattr(self,"alloc_page_lbl",None)
        if lbl is None: return
        try:
            keep=lbl.cget("fg"); lbl.config(fg=PRIMARY)
            self.root.after(260,lambda:lbl.winfo_exists() and lbl.config(fg=keep))
        except Exception: pass

    def _alloc_empty_text(self):
        filt=any(v.get().strip() for v in (self.alloc_filter_worker,self.alloc_filter_client,
                                            self.alloc_filter_category,self.alloc_quick_search))
        if filt: return "No allocations match these filters\nclear a filter to see the rest of the week"
        return f"No allocations in {self.cur_week.get()} yet\npress  + Add Allocation  or  Ctrl + N"
    def _selected_allocation_id(self):
        sel=self.alloc_tree.selection() if hasattr(self,"alloc_tree") else (); return int(sel[0]) if sel else None
    def _edit_selected_allocation(self):
        aid=self._selected_allocation_id()
        # No "still syncing" block — edit_alloc opens instantly from the local
        # snapshot and queues its cloud save behind the pending add if needed.
        if aid: self.edit_alloc(aid,extra_refresh=lambda:self._refresh_current_route())
    def _delete_selected_allocation(self):
        aid=self._selected_allocation_id()
        if aid: self.del_alloc(aid)
    def _allocation_notes_selected(self):
        aid=self._selected_allocation_id()
        if not aid: messagebox.showinfo("Notes","Select an allocation first."); return
        self.entity_notes_dialog("allocation",str(aid),f"Allocation #{aid}",self.cur_week.get())

    def _refresh_wages_workspace(self):
        wk=self.cur_week.get(); render=[]; total_paid=total_rec=0.0
        for i,w in enumerate(self._snapshot["workers"]):
            paid=self._snapshot["wages"].get((w,wk),0.0); rec=self._derived["worker_week_alloc"].get((w,wk),0.0); rem=paid-rec
            total_paid+=paid; total_rec+=rec; tag="danger" if rem<-0.01 else ("success" if abs(rem)<0.01 and paid>0 else ("odd" if i%2 else "even"))
            render.append((None,(w,"$"+fmt(paid),"$"+fmt(rec),("-$"+fmt(-rem) if rem<0 else "$"+fmt(rem))),(tag,)))
        rem=total_paid-total_rec; render.append((None,("TOTAL","$"+fmt(total_paid),"$"+fmt(total_rec),("-$"+fmt(-rem) if rem<0 else "$"+fmt(rem))),("total","success" if abs(rem)<0.01 else ("danger" if rem<-0.01 else "warning"))))
        self._tree_replace(self.wages_tree,render)

    def _refresh_clients_workspace(self):
        wk=self.cur_week.get(); render=[]
        for i,c in enumerate(self._snapshot["clients"]):
            vals=[]; danger=False
            for cat in CATEGORIES:
                used_week=self._derived["client_week_alloc"].get((c,wk,cat),0.0); remain=estimate_period_hours(self._snapshot,c,cat)-self._derived["client_period_alloc"].get((c,cat),0.0)
                danger= danger or remain<-0.01; vals.append(f"{fmt(used_week)} / {fmt(remain)}")
            render.append((None,(c,*vals),("danger" if danger else ("odd" if i%2 else "even"),)))
        self._tree_replace(self.clients_tree,render)

    def _refresh_reconcile_workspace(self):
        wk=self.cur_week.get(); render=[]; te=tr=0.0; idx=0
        for c in self._snapshot["clients"]:
            for cat in CATEGORIES:
                planned=self._snapshot["estimates"].get((c,wk,cat),0.0)*GLOBAL_RATES[cat]
                rec=self._derived["client_week_alloc"].get((c,wk,cat),0.0)*GLOBAL_RATES[cat]
                if abs(planned)<0.01 and abs(rec)<0.01: continue
                rem=planned-rec; te+=planned; tr+=rec; tag="success" if abs(rem)<0.01 else ("danger" if rem<0 else ("odd" if idx%2 else "even"))
                render.append((None,(c,CAT_ABBR[cat],"$"+fmt(planned),"$"+fmt(rec),("-$"+fmt(-rem) if rem<0 else "$"+fmt(rem))),(tag,))); idx+=1
        if idx: render.append((None,("TOTAL","","$"+fmt(te),"$"+fmt(tr),"$"+fmt(te-tr)),("total","success" if abs(te-tr)<0.01 else ("danger" if te-tr<-0.01 else "warning"))))
        self._tree_replace(self.reconcile_tree,render)

    def _draw_health(self):
        if not hasattr(self,"health_canvas"): return
        cv=self.health_canvas; cv.delete("all"); w=max(260,cv.winfo_width()); h=max(130,cv.winfo_height())
        score,ow,oc=reconciliation_health(self._snapshot,self._derived)
        cx=min(92,w*0.28); cy=h*0.53; r=50
        cv.create_oval(cx-r,cy-r,cx+r,cy+r,outline=BORDER,width=11)
        col=SUCCESS if score>=90 else (ACCENT if score>=70 else DANGER)
        cv.create_arc(cx-r,cy-r,cx+r,cy+r,start=90,extent=-360*score/100,style="arc",outline=col,width=11)
        cv.create_text(cx,cy-3,text=str(score),fill=TEXT,font=("Segoe UI Semibold",24,"bold"))
        cv.create_text(cx,cy+25,text="/ 100",fill=TEXT2,font=("Segoe UI",8))
        paid=self._derived["total_paid"]; rem=self._derived["total_remaining"]
        items=[("Reconciled vs paid", max(0,min(100,(self._derived['total_reconciled']/paid*100 if paid else 0))), SUCCESS),
               ("Worker differences", max(0,100-ow*15), CYAN),
               ("Client differences", max(0,100-oc*15), ACCENT)]
        x=max(175,w*0.48); y=27
        for label,pct,c in items:
            cv.create_text(x,y,text=label,fill=TEXT2,font=("Segoe UI",8),anchor="w")
            cv.create_rectangle(x,y+12,w-18,y+17,fill=CONTROL,outline="")
            cv.create_rectangle(x,y+12,x+(w-18-x)*pct/100,y+17,fill=c,outline="")
            y+=42
        self.health_detail_var.set(f"{ow+oc} issue{'s' if ow+oc!=1 else ''}")

    def _draw_estimates(self):
        if not hasattr(self,"estimate_canvas"): return
        cv=self.estimate_canvas; cv.delete("all"); w=max(280,cv.winfo_width()); h=max(70,cv.winfo_height())
        vals=[]
        for wk in WEEKS:
            vals.append(sum(self._snapshot["estimates"].get((c,wk,cat),0.0) for c in self._snapshot["clients"] for cat in CATEGORIES))
        mx=max(vals+[1]); gap=8; bw=max(22,(w-28-gap*5)/6); x=14
        for i,(wk,v) in enumerate(zip(WEEKS,vals),1):
            bh=(h-24)*(v/mx); col=PRIMARY if wk==self.cur_week.get() else (SECONDARY if v>0 else CONTROL)
            cv.create_rectangle(x,h-18-bh,x+bw,h-18,fill=col,outline="")
            cv.create_text(x+bw/2,h-8,text=f"W{i}",fill=TEXT2,font=("Segoe UI",7))
            if v>0: cv.create_text(x+bw/2,max(8,h-22-bh),text=fmt(v),fill=TEXT,font=("Segoe UI",7))
            x+=bw+gap
        actual_hours=self._derived.get("client_hours_total",0.0); total=sum(vals)
        self.estimate_summary_var.set(f"{fmt(total)}h across all 6 weekly estimates" + (f"  •  actual period: {fmt(actual_hours)}h" if actual_hours>0.01 else ""))
        wk=self.cur_week.get(); i=WEEKS.index(wk)
        completed=sum(1 for v in vals if v>0.01)
        self.estimate_focus_var.set(f"{wk}: {fmt(vals[i])}h estimated  •  {completed}/6 weeks currently contain estimates")

    def _draw_recon_chart(self):
        if not hasattr(self,"recon_canvas"): return
        cv=self.recon_canvas; cv.delete("all"); w=max(500,cv.winfo_width()); h=max(170,cv.winfo_height())
        series=[]
        for wk in WEEKS:
            paid=sum(self._snapshot["wages"].get((ww,wk),0.0) for ww in self._snapshot["workers"])
            rec=sum(float(r[7] or 0) for r in self._derived["by_week"].get(wk,[])); rem=max(0,paid-rec)
            series.append((paid,rec,rem))
        # Dashboard-style bars: three bars per week (paid / reconciled / still remaining),
        # faint gridlines behind, value of the reconciled bar printed above it, and the
        # currently selected week lifted with a soft band so the eye lands on it.
        mx=max([v for row in series for v in row]+[1]); left=ui_px(58); bottom=h-ui_px(34); top=ui_px(22); group=(w-left-16)/6
        cur=WEEKS.index(self.cur_week.get()) if self.cur_week.get() in WEEKS else -1
        for frac in (.25,.5,.75,1):
            y=bottom-(bottom-top)*frac; val=mx*frac
            cv.create_line(left,y,w-10,y,fill=_mix_hex(CARD,BORDER,.7),dash=(1,3))
            cv.create_text(left-8,y,text=("$"+fmt(val)),fill=TEXT2,font=("Segoe UI",ui_pt(7)),anchor="e")
        cv.create_line(left,bottom,w-10,bottom,fill=BORDER)
        cols=(_mix_hex(CARD,TEXT2,.55),SUCCESS,WARNING)
        for i,row in enumerate(series):
            if i==cur:
                cv.create_rectangle(left+i*group+2,top-ui_px(10),left+(i+1)*group-2,bottom,fill=_mix_hex(CARD,PRIMARY,.10),outline="")
            bw=max(8,group*.2); gx=left+i*group+(group-(3*bw+8))/2
            for j,v in enumerate(row):
                bh=(bottom-top)*(v/mx); x=gx+j*(bw+4)
                if bh>0: cv.create_rectangle(x,bottom-bh,x+bw,bottom,fill=cols[j],outline="")
            paid,rec,rem=row
            if rec>0: cv.create_text(gx+bw+bw/2+4,max(top-2,bottom-(bottom-top)*(rec/mx)-ui_px(9)),text="$"+fmt(rec),fill=TEXT,font=("Segoe UI Semibold",ui_pt(7),"bold"))
            try: dlabel=parse_week_date(get_week_date(WEEKS[i])).strftime("%d %b")
            except Exception: dlabel=""
            cv.create_text(left+i*group+group*.5,bottom+ui_px(10),text=f"Week {i+1}",fill=(PRIMARY if i==cur else TEXT),font=("Segoe UI Semibold",ui_pt(8),"bold"))
            if dlabel: cv.create_text(left+i*group+group*.5,bottom+ui_px(22),text=dlabel,fill=TEXT2,font=("Segoe UI",ui_pt(7)))

    def _compute_notifications(self):
        out=[]; paid=self._derived["total_paid"]; rec=self._derived["total_reconciled"]; rem=paid-rec
        if rem>0.01: out.append(("!","Period remaining",f"${fmt(rem)} of paid wages is still waiting to be reconciled."))
        elif rem<-0.01: out.append(("!","Period over-reconciled",f"Reconciled value is ${fmt(-rem)} above paid wages."))
        for w in self._snapshot["workers"]:
            for wk in WEEKS:
                left=self._snapshot["wages"].get((w,wk),0.0)-self._derived["worker_week_alloc"].get((w,wk),0.0)
                if left<-0.01: out.append(("!",f"{w} • {wk}",f"Over-reconciled by ${fmt(-left)}."))
        for c in self._snapshot["clients"]:
            for cat in CATEGORIES:
                total=estimate_period_hours(self._snapshot,c,cat)
                used=self._derived["client_period_alloc"].get((c,cat),0.0); left=total-used
                if left<-0.01: out.append(("!",f"{c} • {CAT_ABBR.get(cat,cat)}",f"6-week estimate exceeded by {fmt(-left)}h."))
                elif total>0 and 0<=left<=max(1.0,total*0.1): out.append(("·",f"{c} • {CAT_ABBR.get(cat,cat)}",f"Only {fmt(left)}h remains in the 6-week estimate."))
        for r in self._guide_status_cached():
            wk=self.cur_week.get()
            for cat in CATEGORIES:
                g_=r["week_guide"][cat]; a_=r["week_alloc"][cat]
                if g_>0.009 and a_<g_-0.01: out.append(("·",f"{r['client']} • {CAT_ABBR.get(cat,cat)} • guide",f"{fmt(g_-a_)}h under the client guide in {wk} ({fmt(a_)} of {fmt(g_)}h)."))
                elif a_>g_+0.01 and (g_>0.009 or cat!="Public Holiday"): out.append(("!",f"{r['client']} • {CAT_ABBR.get(cat,cat)} • guide",f"{fmt(a_-g_)}h over the client guide in {wk} ({fmt(a_)} of {fmt(g_)}h)."))
            m=r["money"]
            if m["budget"]>0 and m["invoice"]>m["budget"]+0.5:
                out.append(("!",f"{r['client']} • budget",f"Guide invoices ${fmt(m['invoice'])}/month, above the ${fmt(m['budget'])} monthly budget."))
        if not out: out=[("✓","All clear","No reconciliation issues need attention right now.")]
        return out

    def _refresh_notifications(self):
        self._notifications=self._compute_notifications(); n=sum(1 for x in self._notifications if x[0]=="!")
        if hasattr(self,"notification_btn"): self.notification_btn.config(text=f"🔔 {n}",fg=DANGER if n else TEXT)

    def _refresh_dashboard(self):
        if not hasattr(self,"attention_rows"): return
        self._update_kpis(); self._refresh_notifications(); self._update_week_buttons()
        for i,(rr,sevlbl,titlev,detailv) in enumerate(self.attention_rows):
            if i < len(self._notifications):
                sev,title,detail=self._notifications[i]; rr.pack(fill="x",pady=2)
                sevlbl.config(text=sev,fg=DANGER if sev=="!" else (SUCCESS if sev=="✓" else ACCENT))
                titlev.set(title); detailv.set(detail)
            else:
                rr.pack_forget()
        # Detailed audit is loaded only when Audit Log is opened. Keeping it out of
        # every dashboard refresh is a deliberate Speed Mode trade-off.
        self._tree_replace(self.dashboard_activity,[])
        self._draw_health(); self._draw_estimates(); self._draw_recon_chart(); self._refresh_client_worker_analysis()
        if hasattr(self,"dashboard_footer_vars"):
            self.dashboard_footer_vars["Workers"].set(str(len(self._snapshot["workers"])))
            self.dashboard_footer_vars["Clients"].set(str(len(self._snapshot["clients"])))
            self.dashboard_footer_vars["Allocations"].set(str(len(self._snapshot["allocations"])))
            self.dashboard_footer_vars["Open Notes"].set("Open")
            self.dashboard_footer_vars["Unresolved"].set(str(sum(1 for x in self._notifications if x[0]=="!")))
            self.dashboard_footer_vars["Last Sync"].set("Live" if CLOUD_ENABLED else "Local")
        self._update_fold_summaries()

    def _refresh_client_worker_analysis(self):
        if not hasattr(self,"client_analysis_tree"): return
        # One pass over the in-RAM allocations list — builds per-client and per-worker
        # aggregates together, so this is O(len(allocations)) once per dashboard
        # refresh (never per keystroke) and touches no database.
        client_workers={}; worker_clients={}; worker_hours={}
        for r in self._snapshot["allocations"]:
            aid,wk,w,c,cat,h,rate,cost,day,note,by,created,st,et=r
            h=float(h or 0)
            client_workers.setdefault(c,{}); client_workers[c][w]=client_workers[c].get(w,0.0)+h
            worker_clients.setdefault(w,{}); worker_clients[w][c]=worker_clients[w].get(c,0.0)+h
            worker_hours[w]=worker_hours.get(w,0.0)+h

        rows=[]
        for i,c in enumerate(self._snapshot["clients"]):
            est=sum(estimate_period_hours(self._snapshot,c,cat) for cat in CATEGORIES)
            rec=sum(self._derived["client_period_alloc"].get((c,cat),0.0) for cat in CATEGORIES)
            left=est-rec; cw=client_workers.get(c,{}); nworkers=len(cw)
            top=max(cw.items(),key=lambda kv:kv[1])[0] if cw else "—"
            tag="danger" if left<-0.01 else ("success" if abs(left)<0.01 and est>0 else ("odd" if i%2 else "even"))
            rows.append((None,(c,fmt(est),fmt(rec),fmt(left),str(nworkers),top),(tag,)))
        self._tree_replace(self.client_analysis_tree,rows)

        leaders=sorted(worker_hours.items(),key=lambda kv:-kv[1])[:8]
        self._top_worker=leaders[0] if leaders else None
        rows2=[]
        for i,(w,hrs) in enumerate(leaders):
            wc=worker_clients.get(w,{}); topc=max(wc.items(),key=lambda kv:kv[1])[0] if wc else "—"
            rows2.append((None,(w,fmt(hrs),str(len(wc)),topc),("odd" if i%2 else "even",)))
        self._tree_replace(self.worker_leaderboard_tree,rows2)

    def _open_client_from_analysis(self,event=None):
        sel=self.client_analysis_tree.selection()
        if sel: self.client_intelligence_dialog(self.client_analysis_tree.item(sel[0],"values")[0])

    def _open_worker_from_leaderboard(self,event=None):
        sel=self.worker_leaderboard_tree.selection()
        if sel: self.worker_intelligence_dialog(self.worker_leaderboard_tree.item(sel[0],"values")[0])

    def notifications_dialog(self):
        d,body=branded_dialog(self.root,"Notifications","Smart attention list for the current period",760,560)
        tree=make_fast_tree(body,("sev","item","detail"),("","Item","Detail"),(45,240,430),("c","w","w"),height=15)
        data=[]
        for sev,title,detail in self._compute_notifications():
            tag="danger" if sev=="!" else ("success" if sev=="✓" else "muted")
            data.append((None,(sev,title,detail),(tag,)))
        self._tree_replace(tree,data)

    def global_search(self):
        q=self.search_var.get().strip().lower()
        if not q: return
        d,body=branded_dialog(self.root,"Global Search",f"Results for “{self.search_var.get().strip()}”",900,640)

        # ---------------- narrow the results: Week / Client / Category ----------------
        filt=tk.Frame(body,bg=BG_DARK); filt.pack(fill="x",padx=14,pady=(0,8))
        weekf=tk.StringVar(); clientf=tk.StringVar(); catf=tk.StringVar()
        def filterbox(label,var,width,values):
            box=tk.Frame(filt,bg=BG_DARK); box.pack(side="left",padx=(0,8))
            tk.Label(box,text=label.upper(),fg=TEXT2,bg=BG_DARK,font=("Segoe UI Semibold",7,"bold")).pack(anchor="w",pady=(0,2))
            cb=ttk.Combobox(box,textvariable=var,values=[""]+list(values),state="readonly",width=width,style="Modern.TCombobox")
            cb.pack(); return cb
        filterbox("Week",weekf,12,WEEKS)
        filterbox("Client",clientf,18,self._snapshot["clients"])
        filterbox("Category",catf,15,CATEGORIES)

        tree=make_fast_tree(body,("type","name","week","detail"),("Type","Name","Week","Detail"),(120,220,100,420),("w","w","w","w"),height=16)
        # Each entry carries the client/category it's really about (blank for Worker/Note rows,
        # which the Client/Category filters simply exclude — same as an allocation table would).
        all_results=[]
        for w in self._snapshot["workers"]:
            if q in w.lower(): all_results.append(("Worker",w,"","Open worker intelligence","",""))
        for c in self._snapshot["clients"]:
            if q in c.lower(): all_results.append(("Client",c,"","Open client intelligence",c,""))
        for r in self._snapshot["allocations"]:
            aid,wk,w,c,cat,h,rate,cost,day,note,by,created,st,et=r; blob=f"{aid} {wk} {w} {c} {cat} {day} {note} {by}".lower()
            if q in blob: all_results.append(("Allocation",str(aid),wk,f"{w} → {c} • {CAT_ABBR.get(cat,cat)} • {fmt(float(h or 0))}h",c,cat))
        # Notes are auxiliary data; load them only when a search is actually run.
        for r in load_notes_rows():
            nid,etype,eid,wk,note,author,created=r
            if q in f"{etype} {eid} {wk} {note} {author}".lower(): all_results.append(("Note",f"{etype}: {eid}",wk,note[:90],"",""))

        def render_results(*_):
            fw=weekf.get(); fc=clientf.get(); fcat=catf.get()
            shown=[]
            for typ,name,wk,detail,rc,rcat in all_results:
                if fw and wk!=fw: continue
                if fc and rc!=fc: continue
                if fcat and rcat!=fcat: continue
                shown.append((typ,name,wk,detail))
            self._tree_replace(tree,[(None,r,("odd" if i%2 else "even",)) for i,r in enumerate(shown[:1000])])
        for v in (weekf,clientf,catf): v.trace_add("write",render_results)
        render_results()

        def open_result(_=None):
            sel=tree.selection()
            if not sel:return
            vals=tree.item(sel[0],"values"); typ,name,wk,detail=vals
            if typ=="Worker": d.destroy(); self.worker_intelligence_dialog(name)
            elif typ=="Client": d.destroy(); self.client_intelligence_dialog(name)
            elif typ=="Allocation":
                d.destroy(); self._select_week(wk,publish=False); self._navigate("Allocations",publish=False)
                try:self.alloc_tree.selection_set(name); self.alloc_tree.see(name)
                except Exception:pass
        tree.bind("<Double-1>",open_result)

