        d,body=branded_dialog(self.root,"Edit Week Ending Dates","Enter Week 1 once — Weeks 2–6 are calculated automatically at +7 days. You can still override any week afterwards.",620,570)
        rows=tk.Frame(body,bg=BG_DARK); rows.pack(fill="x",padx=20,pady=(12,6))
        vars_={}; entries={}; syncing={"busy":False}
        for i,w in enumerate(WEEKS,1):
            row=tk.Frame(rows,bg=(CARD if i%2 else CARD2),highlightbackground=BORDER,highlightthickness=1); row.pack(fill="x",pady=3)
            tk.Label(row,text=f"Week {i} ending",fg=TEXT,bg=row["bg"],font=("Segoe UI Semibold",9,"bold"),width=15,anchor="w").pack(side="left",padx=(12,6),pady=8)
            v=tk.StringVar(value=get_week_date(w)); vars_[w]=v
            e=tk.Entry(row,textvariable=v,font=("Segoe UI",10),bg=BG_LIGHT,fg=TEXT,insertbackground=TEXT,relief="flat",width=16); e.pack(side="left",ipady=5,padx=6); entries[w]=e
            tk.Label(row,text="YYYY-MM-DD",fg=TEXT2,bg=row["bg"],font=("Segoe UI",8)).pack(side="left",padx=8)
        status=tk.StringVar(value="Change Week 1 and the following five dates will fill themselves.")
        tk.Label(body,textvariable=status,fg=CYAN,bg=BG_DARK,font=("Segoe UI",9)).pack(anchor="w",padx=22,pady=(4,6))
        def autofill(*_):
            if syncing["busy"]: return
            base=parse_week_date(vars_["Week 1"].get())
            if not base: status.set("Enter a valid Week 1 date, e.g. 2026-09-06"); return
            syncing["busy"]=True
            try:
                for i,w in enumerate(WEEKS[1:],1): vars_[w].set((base+timedelta(days=7*i)).isoformat())
            finally: syncing["busy"]=False
            status.set("✓ Weeks 2–6 calculated automatically. Edit any one manually if needed.")
        # Auto-fill as soon as Week 1 becomes a complete valid date.
        def w1_changed(*_):
            if parse_week_date(vars_["Week 1"].get()): autofill()
        vars_["Week 1"].trace_add("write",w1_changed)
        tools=tk.Frame(body,bg=BG_DARK); tools.pack(fill="x",padx=20,pady=6)
        mkbtn(tools,"↻ Recalculate Weeks 2–6",autofill,SECONDARY).pack(side="left")
