    def refresh_week(self,wk=None):
        target=wk if wk in WEEKS else self.cur_week.get()
        if target!=self.cur_week.get(): self.cur_week.set(target)
        self._update_week_buttons(); self._refresh_current_route()

    def refresh(self):
        # One local SQLite snapshot reload; zero network waiting on the UI thread.
        try:
            self._reload_snapshot()
        except Exception as exc:
            # A failed reload used to be swallowed completely, leaving every page
            # silently showing whatever period was loaded before this one (e.g. a
            # saved period missing a table this build expects would just keep
            # displaying the previous/live data with no error at all). Now at least
            # logged, so a future schema mismatch shows up in the performance log
            # instead of looking like "this saved period has the wrong data."
            try:_perf_log("reload_snapshot_failed",0.0,f"{type(exc).__name__}: {exc}")
            except Exception:pass
        self._update_all_from_cache()
        try:self._refresh_period_indicator()
        except Exception:pass
        try:self.period_dates_btn.config(text=self._period_dates_text())
        except Exception:pass
        try:self._last_known_change_token=database_change_token()
        except Exception:pass

    # Background jobs that don't edit the currently-open period's data, so finishing one
    # while a saved period is open must NOT trigger a re-upload of that period's file.
    _NON_PERIOD_JOB_LABELS=frozenset(("download_saved_period","delete_saved_period","rename_saved_period",
                                      "register_archives","create_user","reset_password","archive_and_start_new",
                                      "full_report"))

    def _mutation_worker_loop(self):
        """Single worker for ALL database mutations.

        Tk never waits on Turso. The worker also pins each job to the period that was
        active when the user clicked Save, so switching periods cannot redirect a
        queued write to the wrong database.
        """
        while True:
            job=self._mutation_jobs.get()
            if job is None:
                self._mutation_jobs.task_done(); return
            work,on_success,on_error,sync_after,target,label=job
            started=time.perf_counter(); result=None; exc=None
            try:
                _DB_CONTEXT.db_path=target
                result=work()
                if sync_after and CLOUD_ENABLED and target==DEFAULT_DB_PATH:
                    s0=time.perf_counter(); sync_cloud_now(); _perf_log("replica_sync_after_save",time.perf_counter()-s0,label)
                if CLOUD_ENABLED and target!=DEFAULT_DB_PATH and label not in self._NON_PERIOD_JOB_LABELS:
                    # An edit made inside a SAVED period only touched its local file.
                    # Push the whole file back up so every other computer sees it —
                    # previously nothing did, so archive edits never left this machine.
                    s0=time.perf_counter(); _sync_archive_blob(target); _perf_log("archive_blob_sync_after_save",time.perf_counter()-s0,label)
            except Exception as e:
                exc=e
                # A primary connection that has started failing (network change, token
                # problem) is thrown away so the NEXT job reconnects instead of failing forever.
                try: _PRIMARY_TLS.conn=None
                except Exception: pass
            finally:
                try: delattr(_DB_CONTEXT,"db_path")
                except Exception: pass
                _perf_log("mutation",time.perf_counter()-started,label)
                self._mutation_jobs.task_done()
            # Never call Tk from this worker thread. Publish completion to the UI
            # queue; _drain_ui_results runs only on Tk's main thread.
            if exc is not None:
                if on_error: self._ui_results.put((on_error,exc))
            elif on_success:
                self._ui_results.put((on_success,result))

    def _drain_ui_results(self):
        try:
            for _ in range(80):
                try: cb,value=self._ui_results.get_nowait()
                except queue.Empty: break
                try: cb(value)
                except Exception as exc: _perf_log("ui_callback_error",0.051,str(exc))
                finally: self._ui_results.task_done()
        finally:
            try:
                if self.root.winfo_exists(): self.root.after(35,self._drain_ui_results)
            except Exception: pass

    def _background_job(self, work, on_success=None, on_error=None, sync_after=False, label="save"):
        """Queue database/network work; returns to Tk immediately.

        5.6 spawned many worker threads and usually forced a replica sync after each
        save. 5.7 uses one writer queue and does NOT perform a second network roundtrip
        unless a caller explicitly requests it.
        """
        target=DB_PATH
        self._mutation_jobs.put((work,on_success,on_error,bool(sync_after),target,label))

    def _visible_dialog(self):
        try:
            visible=[]
            for w in self.root.winfo_children():
                if isinstance(w,tk.Toplevel) and w.winfo_exists():
                    try:
                        if w.state()!="withdrawn" and w.winfo_viewable():
                            visible.append(w)
                    except Exception:
                        pass
            if not visible:
                return None
            focused=self.root.focus_get()
            for w in visible:
                try:
                    if focused and str(focused).startswith(str(w)):
                        return w
                except Exception:
                    pass
            return visible[-1]
        except Exception:
            return None

    def _current_week_key(self):
        return self.cur_week.get() if self.cur_week.get() in WEEKS else WEEKS[0]

    def _infer_activity(self):
        dlg=self._visible_dialog()
        if dlg is not None:
            try: title=dlg.title() or "Working"
            except Exception: title="Working"
            title=title.replace("ALLOCATE PRO — ","").replace("ALLOCATE PRO | ","").strip()
            return title[:90]
        return f"{self._current_week_key()} • {self._active_subtab}"

    def _period_for_presence(self):
        try: return self.period_lbl.cget("text")
        except Exception: return "Current"

    def _publish_presence(self,force_log=False,force_heartbeat=False):
        """Queue presence; never perform network I/O on Tk's UI thread."""
        if not CLOUD_ENABLED:
            return
        activity=self._infer_activity()
        now=time.monotonic()
        heartbeat_due=(now-self._last_presence_sent_at)>=120.0
        # Changing tabs/weeks only updates the latest in-memory state. We publish it
        # on the next heartbeat instead of creating a cloud write per click.
        self._last_presence_activity=activity
        if not (force_heartbeat or heartbeat_due):
            return

        payload=(self.user,self.role,self._period_for_presence(),
                 self._current_week_key(),activity,False)
        self._last_presence_activity=activity
        self._last_presence_sent_at=now

        with self._presence_lock:
            # Keep only the newest state if the user clicks several tabs quickly.
            self._presence_pending=payload
            if self._presence_worker_busy:
                return
            self._presence_worker_busy=True

        threading.Thread(target=self._presence_worker,daemon=True).start()

    def _presence_worker(self):
        while True:
            with self._presence_lock:
                payload=self._presence_pending
                self._presence_pending=None
            if payload is None:
                with self._presence_lock:
                    self._presence_worker_busy=False
                    # Race-safe: if something arrived while changing the flag, loop.
                    if self._presence_pending is not None:
                        self._presence_worker_busy=True
                        continue
                return
            _team_heartbeat_remote(payload)

    def _update_team_badge(self,rows=None):
        if not CLOUD_ENABLED or not hasattr(self,"team_live_btn"):
            return
        rows=self._last_team_rows if rows is None else rows
        others=[r for r in rows if r[0]!=TEAM_SESSION_ID]
        if not others:
            txt="👥 1 ONLINE"
        else:
            first=others[0]
            suffix=f" | {first[1]}: {first[6] or 'Working'}"
            if len(suffix)>58: suffix=suffix[:55]+"…"
            txt=f"👥 {len(rows)} ONLINE{suffix}"
        try: self.team_live_btn.config(text=txt)
        except Exception: pass

    def _update_change_indicator(self):
        if not hasattr(self,"change_lbl"):
            return
        try:
            cur=database_change_token()
            changed=(self._last_known_change_token is not None and cur!=self._last_known_change_token)
            if changed and self._visible_dialog() is not None:
                self.change_lbl.config(
                    text="● New team changes are waiting — they will appear automatically when this window closes.",
                    fg=ACCENT)
            else:
                self.change_lbl.config(text="● SPEED LIVE  •  background sync  •  teammate edits appear automatically",fg=SUCCESS)
        except Exception:
            pass


    def _queue_replica_sync(self):
        """Pull teammate changes in the background.

        libSQL already has periodic sync enabled; this explicit lightweight request makes
        simultaneous multi-computer work more deterministic without ever waiting on Tk.
        Multiple requests collapse into one worker.
        """
        if not CLOUD_ENABLED or DB_PATH != DEFAULT_DB_PATH:
            return
        with self._replica_sync_lock:
            if self._replica_sync_busy:
                return
            self._replica_sync_busy=True
        def worker():
            try:
                sync_cloud_now(wait=True)
            except Exception:
                pass
            finally:
                with self._replica_sync_lock:
                    self._replica_sync_busy=False
        threading.Thread(target=worker,daemon=True).start()

    def _team_tick(self):
        """Very-light UI poll. Network sync is handled by libSQL's periodic replica sync."""
        try:
            if not self.root.winfo_exists():
                return

            # Network heartbeat and cloud pull are queued to daemon threads.
            self._publish_presence()
            # One coalesced replica pull. Never sync while mutation jobs are queued;
            # this avoids a reader/sync race exactly when the user is saving.
            if self._mutation_jobs.empty():
                self._queue_replica_sync()

            # These reads hit the local embedded replica only. The embedded replica
            # already syncs itself periodically; no extra sync is launched on every UI tick.
            self._last_team_rows=team_online_users(sync_first=False)
            self._update_team_badge(self._last_team_rows)

            token=database_change_token()
            changed=(self._last_known_change_token is not None and token!=self._last_known_change_token)

            if changed:
                own_edit=(len(token)>=3 and token[0]=="cloud" and token[2]==TEAM_SESSION_ID)
                if own_edit:
                    self._last_known_change_token=token
                    self._update_change_indicator()
                elif (self._visible_dialog() is None or getattr(self._visible_dialog(),"_ap_live",False)) and not self._auto_refreshing:
                    self._auto_refreshing=True
                    try:
                        self.refresh()
                        for fn in list(getattr(self,"_team_listeners",[])):
                            try: fn()
                            except Exception: pass
                    finally:
                        self._auto_refreshing=False
                else:
                    self._update_change_indicator()
            else:
                self._update_change_indicator()
        except Exception:
            pass

        # Local reads are cheap; this does not contact Turso directly.
        try:
            others=sum(1 for r in (self._last_team_rows or []) if r and r[0]!=TEAM_SESSION_ID)
            fast=others>0 and CLOUD_PROC_ENABLED and _CLOUD_CHILD is not None and _CLOUD_CHILD.alive
            self.root.after(4000 if fast else 12000,self._team_tick)
        except Exception:
            try: self.root.after(12000,self._team_tick)
            except Exception: pass

    # build() still calls the old hook once; the new _team_tick owns polling.
    def _poll_for_changes(self):
        return

    def team_live_dialog(self):
        d,body=branded_dialog(
            self.root,"Team Live",
            "See who is online and what screen they are working on. Updates automatically.",
            820,650)
        online=tk.Frame(body,bg=BG_DARK); online.pack(fill="x",padx=16,pady=(12,6))
        feed=tk.Frame(body,bg=BG_DARK); feed.pack(fill="both",expand=True,padx=16,pady=(4,12))

        def draw():
            if not d.winfo_exists():
                return
            for ch in online.winfo_children(): ch.destroy()
            for ch in feed.winfo_children(): ch.destroy()

            rows=team_online_users(sync_first=False)
            tk.Label(online,text=f"ONLINE NOW — {len(rows)}",fg=SUCCESS,bg=BG_DARK,
                     font=("Segoe UI",11,"bold")).pack(anchor="w",pady=(0,6))
            for row in rows:
                sid,user,role,machine,period,week,activity,last_seen=row
                card=tk.Frame(online,bg=BG_PANEL); card.pack(fill="x",pady=3)
                tk.Label(card,text="●",fg=SUCCESS,bg=BG_PANEL,font=("Segoe UI",11,"bold")).pack(side="left",padx=(10,6),pady=8)
                info=tk.Frame(card,bg=BG_PANEL); info.pack(side="left",fill="x",expand=True,pady=6)
                label=user+("  (you)" if sid==TEAM_SESSION_ID else "")
                tk.Label(info,text=label,fg=TEXT,bg=BG_PANEL,font=FONTB,anchor="w").pack(anchor="w")
                tk.Label(info,text=f"{activity or 'Working'}  •  {period}  •  {machine}",
                         fg=TEXT2,bg=BG_PANEL,font=("Segoe UI",9),anchor="w").pack(anchor="w")

            tk.Label(feed,text="RECENT TEAM ACTIVITY",fg=ACCENT,bg=BG_DARK,
                     font=("Segoe UI",11,"bold")).pack(anchor="w",pady=(8,6))
            cv=tk.Canvas(feed,bg=BG_DARK,highlightthickness=0,height=300)
            sb=tk.Scrollbar(feed,orient="vertical",command=cv.yview)
            inner=tk.Frame(cv,bg=BG_DARK)
            inner.bind("<Configure>",lambda e:cv.configure(scrollregion=cv.bbox("all")))
            cv.create_window((0,0),window=inner,anchor="nw")
            cv.configure(yscrollcommand=sb.set)
            cv.pack(side="left",fill="both",expand=True); sb.pack(side="right",fill="y")

            acts=team_recent_activity(35,sync_first=False)
            if not acts:
                tk.Label(inner,text="Team activity will appear here.",
                         fg=TEXT2,bg=BG_DARK,font=FONT).pack(anchor="w",pady=4)
            for user,machine,period,week,activity,created in acts:
                try: when=datetime.fromisoformat(created).strftime("%H:%M:%S")
                except Exception: when=created
                rf=tk.Frame(inner,bg=BG_PANEL); rf.pack(fill="x",pady=2)
                tk.Label(rf,text=when,fg=TEXT2,bg=BG_PANEL,font=("Segoe UI",8),width=9,anchor="w").pack(side="left",padx=(8,2),pady=5)
                tk.Label(rf,text=user,fg=color_for_user(user),bg=BG_PANEL,font=("Segoe UI",9,"bold"),width=15,anchor="w").pack(side="left",padx=3)
                tk.Label(rf,text=f"{activity}  •  {period}",fg=TEXT,bg=BG_PANEL,font=("Segoe UI",9),anchor="w").pack(side="left",fill="x",expand=True,padx=3)
            try: d.after(10000,draw)
            except Exception: pass

        draw()

    def _on_app_close(self):
        # Presence naturally expires shortly, so we still never wait on THAT. But if a
        # save was queued moments ago (e.g. you hit Save then immediately closed the
        # app), give the background worker a short bounded window to actually push it
        # to the cloud before the process dies — otherwise a just-made change can be
        # silently lost. Capped so a dead network can never hang the close.
        try:
            pending=getattr(self,"_mutation_jobs",None)
            if pending is not None and pending.unfinished_tasks>0:
                deadline=time.time()+4.0
                while pending.unfinished_tasks>0 and time.time()<deadline:
                    time.sleep(0.05)
        except Exception:
            pass
        try: self.root.destroy()
        except Exception: pass

    def _scrollable(self, parent):
        """Return an inner frame inside a vertical-scroll canvas."""
        cv=tk.Canvas(parent,bg=BG_DARK,highlightthickness=0)
        sb=tk.Scrollbar(parent,orient="vertical",command=cv.yview)
        inner=tk.Frame(cv,bg=BG_DARK)
        inner.bind("<Configure>",lambda e:cv.configure(scrollregion=cv.bbox("all")))
        cv.create_window((0,0),window=inner,anchor="nw")
        cv.configure(yscrollcommand=sb.set)
        cv.pack(side="left",fill="both",expand=True); sb.pack(side="right",fill="y")
        # The app-wide wheel router scrolls this canvas whenever the pointer is over it.
        mark_scrollable(cv)
        return inner

