        tk.Label(tbl,text=fmt(gh),fg=SUCCESS,bg=BG_DARK,font=FONTB,anchor="w").grid(row=r,column=5,sticky="w",padx=8,pady=(6,2))
        tk.Label(tbl,text="$"+fmt(gc),fg=SUCCESS,bg=BG_DARK,font=FONTB,anchor="w").grid(row=r,column=6,sticky="w",padx=8,pady=(6,2))
