    def _worker_rates_prompt(self, worker, on_done):
        d,body=branded_dialog(self.root,f"Rate Exceptions — {worker}",
            "Leave a category blank to keep the global rate. Fill one in to override it just for this worker — every allocation made for them in that category (new or edited) uses it from now on.",480,360)
        current=get_worker_rates(worker)
        entries={}
        for cat in CATEGORIES:
            row=tk.Frame(body,bg=BG_PANEL); row.pack(fill="x",padx=16,pady=5)
            tk.Label(row,text=cat,fg=TEXT,bg=BG_PANEL,font=FONTB,width=15,anchor="w").pack(side="left",padx=(10,0),pady=8)
            tk.Label(row,text=f"global ${GLOBAL_RATES[cat]:.2f}  ·  GST ${GLOBAL_RATES_GST[cat]:.2f}",fg=TEXT2,bg=BG_PANEL,font=("Segoe UI",8)).pack(side="left",padx=(0,10))
            e=tk.Entry(row,font=FONT,bg=BG_LIGHT,fg=TEXT,insertbackground=TEXT,relief="flat",width=10,justify="center")
            if cat in current: e.insert(0,fmt(current[cat]))
            e.pack(side="left",ipady=3,padx=(0,10))
            entries[cat]=e
        gstrow=tk.Frame(body,bg=BG_DARK); gstrow.pack(fill="x",padx=16,pady=(6,0))
        def _fill(vals):
            for cat,e in entries.items():
                e.delete(0,"end")
                if vals: e.insert(0,fmt(vals[cat]))
        mkbtn(gstrow,"Global — no GST",lambda:_fill(None),CONTROL,fg=TEXT).pack(side="left")
        mkbtn(gstrow,"Global — with GST",lambda:_fill(GLOBAL_RATES_GST),CONTROL,fg=TEXT).pack(side="left",padx=6)
        status=tk.StringVar(value="")
        tk.Label(body,textvariable=status,fg=SUCCESS,bg=BG_DARK,font=("Segoe UI Semibold",8,"bold")).pack(pady=(10,0))
        def do_save():
            changes=[]
            for cat,e in entries.items():
                txt=e.get().strip().replace("$",""); had=cat in current
                if txt:
                    try: rate=float(txt)
                    except Exception:
                        e.config(bg=DANGER_BG); messagebox.showerror("Not a number",f"{cat}: '{txt}' isn't a rate. Type a number like 45 or 52.50, or leave it blank for the global rate.",parent=d); return
                    if rate<=0:
                        e.config(bg=DANGER_BG); messagebox.showerror("Invalid rate",f"{cat}: a rate must be greater than zero. Leave it blank to use the global rate instead.",parent=d); return
                    if had and abs(current[cat]-rate)<1e-9: continue
                else:
                    if not had: continue
                    rate=None
                changes.append((cat,rate))
            if not changes:
                d.destroy(); on_done(); return
            for cat,rate in changes: self._cache_set_worker_rate(worker,cat,rate)
            save_btn.config(state="disabled",text="Saving…"); status.set("Saving to cloud…")
            def work():
                for cat,rate in changes: set_worker_rate(worker,cat,rate,self.user)
                recost_allocations(new_rate_weeks(),self.user,worker=worker)
                return len(changes)
            def done(_):
                try: d.destroy()
                except Exception: pass
                on_done()
            def fail(exc):
                # Roll the local view back to what the cloud still has, then say so.
                for cat,_r in changes: self._cache_set_worker_rate(worker,cat,current.get(cat))
                try: save_btn.config(state="normal",text="💾 Save Rate Exceptions"); status.set("")
                except Exception: pass
                messagebox.showerror("Cloud save failed",str(exc),parent=self.root)
            self._background_job(work,done,fail,label="set_worker_rate")
        save_btn=mkbtn(body,"💾 Save Rate Exceptions",do_save,ACCENT,"#000"); save_btn.pack(pady=16)

    # ----- workers dialog (6 weekly wage fields, manual) -----
    def workers_dialog(self):
        d,body=branded_dialog(self.root,"Workers","Set weekly wages per worker — each column shows its Week Ending date",1060,680)
        tk.Label(body,text="",bg=BG_DARK).pack(pady=2)
        addf=tk.Frame(body,bg=BG_DARK); addf.pack(fill="x",padx=16)
        nv=tk.Entry(addf,font=FONT,bg=BG_LIGHT,fg=TEXT,insertbackground=TEXT,relief="flat",width=24); nv.pack(side="left",ipady=4)
        def addw():
            n=nv.get().strip()
            if not n:return
            nv.delete(0,"end")
            # Optimistic local UI: appear immediately; cloud save follows in queue.
            self._cache_add_worker(n); build()
            def fail(exc):
                self._cache_delete_worker(n); build(); messagebox.showerror("Cloud save failed",str(exc),parent=d)
            self._background_job(lambda:add_worker(n),on_error=fail,label="add_worker")
        mkbtn(addf,"Add Worker",addw,SUCCESS,"#000").pack(side="left",padx=8)
        mkbtn(addf,"＋ Add from saved workers…",lambda:self.add_saved_workers_dialog(on_done=lambda:(d.winfo_exists() and build())),SECONDARY).pack(side="left",padx=4)
        mkbtn(addf,"💲 Global rates / GST…",lambda:self.global_rates_dialog(on_done=lambda:(d.winfo_exists() and build())),SECONDARY).pack(side="left",padx=4)
        cont=tk.Frame(body,bg=BG_DARK); cont.pack(fill="both",expand=True,padx=16,pady=12)
        cv=tk.Canvas(cont,bg=BG_DARK,highlightthickness=0); sb=tk.Scrollbar(cont,orient="vertical",command=cv.yview)
        inner=tk.Frame(cv,bg=BG_DARK); inner.bind("<Configure>",lambda e:cv.configure(scrollregion=cv.bbox("all")))
        cv.create_window((0,0),window=inner,anchor="nw"); cv.configure(yscrollcommand=sb.set)
        cv.pack(side="left",fill="both",expand=True); sb.pack(side="right",fill="y")
        entries={}
        def build():
            for w in inner.winfo_children(): w.destroy()
            entries.clear()
            for w in self._snapshot["workers"]:
                box=tk.Frame(inner,bg=BG_PANEL); box.pack(fill="x",pady=6)
                tk.Label(box,text=w,fg=ACCENT,bg=BG_PANEL,font=FONTB,width=14,anchor="w").pack(side="left",padx=8,pady=8)
                for wk in WEEKS:
                    cell=tk.Frame(box,bg=BG_PANEL); cell.pack(side="left",padx=3)
                    tk.Label(cell,text=f"{wk.replace('Week ','W')}\n{(parse_week_date(get_week_date(wk)).strftime('%d %b %y') if parse_week_date(get_week_date(wk)) else '—')}",fg=TEXT2,bg=BG_PANEL,font=("Segoe UI",8),justify="center").pack()
                    e=tk.Entry(cell,font=FONT,bg=BG_LIGHT,fg=TEXT,insertbackground=TEXT,relief="flat",width=8,justify="center")
                    e.insert(0,fmt(self._snapshot["wages"].get((w,wk),0.0))); e.pack(ipady=2)
                    entries[(w,wk)]=e
                def do_rename(old=w):
                    self._rename_worker_prompt(old, build)
                def do_delete(name=w):
                    def ok(_=None):
                        self._cache_delete_worker(name); build()
                    self._background_job(lambda:delete_worker(name),ok,lambda e:messagebox.showwarning("Can't delete",str(e),parent=d),label="delete_worker")
                def do_rates(name=w):
                    self._worker_rates_prompt(name, build)
                has_exc=any(k[0]==w for k in self._snapshot.get("worker_rates",{}))
                mkbtn(box,("💲*" if has_exc else "💲"),do_rates,ACCENT if has_exc else SECONDARY).pack(side="left",padx=(8,2))
                mkbtn(box,"✏",do_rename,SECONDARY).pack(side="left",padx=2)
                mkbtn(box,"🗑",do_delete,DANGER).pack(side="left",padx=2)
        wage_status=tk.StringVar(value="")
        tk.Label(body,textvariable=wage_status,fg=SUCCESS,bg=BG_DARK,font=("Segoe UI Semibold",8,"bold")).pack(side="bottom",pady=(0,4))
        def save():
            changes=[]
            for (w,wk),e in entries.items():
                txt=e.get().strip().replace("$","").replace(",","")
                try: v=float(txt or 0)
                except Exception:
                    e.config(bg=DANGER_BG); messagebox.showerror("Not a number",f"{w} · {wk}: '{e.get()}' isn't an amount. Nothing was saved — fix it and click Save again.",parent=d); return
                if v<0:
                    e.config(bg=DANGER_BG); messagebox.showerror("Negative wage",f"{w} · {wk}: a wage can't be negative. Nothing was saved.",parent=d); return
                changes.append((w,wk,v))
            if not changes:return
            self._cache_set_wages(changes); wage_status.set("✓ Saved locally • syncing in background")
            def done(_): wage_status.set("✓ Synced")
            def fail(exc):
                wage_status.set("Cloud sync failed — retrying on next save")
                messagebox.showerror("Cloud save failed",str(exc),parent=d)
            self._background_job(lambda:save_worker_wages_batch(changes,self.user),done,fail,label="save_wages_batch")
        mkbtn(body,"💾 Save All Wages",save,ACCENT,"#000").pack(side="bottom",pady=10)
        build()

    # ----- clients dialog (editable hours per week per category) -----
    def clients_dialog(self):
        d,body=branded_dialog(self.root,"Clients","Period actual hours + weekly estimates",820,640)
        addf=tk.Frame(body,bg=BG_DARK); addf.pack(fill="x",padx=16,pady=(10,0))
        nv=tk.Entry(addf,font=FONT,bg=BG_LIGHT,fg=TEXT,insertbackground=TEXT,relief="flat",width=22); nv.pack(side="left",ipady=4)
        def addc():
            n=nv.get().strip()
            if not n:return
            nv.delete(0,"end")
            self._cache_add_client(n); sel.set(n); build()
            def fail(exc):
                # Remove only the optimistic client if cloud rejected it.
                self._snapshot["clients"]=[c for c in self._snapshot["clients"] if c!=n]
                self._snapshot["period"]={k:v for k,v in self._snapshot["period"].items() if k[0]!=n}
                self._snapshot["estimates"]={k:v for k,v in self._snapshot["estimates"].items() if k[0]!=n}
                self._cache_redraw(); build(); messagebox.showerror("Cloud save failed",str(exc),parent=d)
            self._background_job(lambda:add_client(n),on_error=fail,label="add_client")
        mkbtn(addf,"Add Client",addc,SUCCESS,"#000").pack(side="left",padx=8)
        def _after_saved():
            if not d.winfo_exists(): return
            try: om.configure(values=self._snapshot["clients"])
            except Exception: pass
            try: build()
            except Exception: pass
        mkbtn(addf,"＋ Add from saved clients…",lambda:self.add_saved_clients_dialog(on_done=_after_saved),SECONDARY).pack(side="left",padx=4)
        def _after_removed():
            if not d.winfo_exists(): return
            if sel.get() not in self._snapshot["clients"]: sel.set("")
            _after_saved()
        mkbtn(addf,"− Remove clients…",lambda:self.remove_clients_dialog(on_done=_after_removed),DANGER).pack(side="left",padx=4)
        sel=tk.StringVar()
        selrow=tk.Frame(body,bg=BG_DARK); selrow.pack(fill="x",padx=16,pady=8)
        tk.Label(selrow,text="Edit client:",fg=TEXT,bg=BG_DARK,font=FONTB).pack(side="left")
        om=ttk.Combobox(selrow,textvariable=sel,values=self._snapshot["clients"],state="readonly",width=24); om.pack(side="left",padx=8)
        def do_rename_client():
            c=sel.get()
            if not c:
                messagebox.showinfo("Pick a client","Choose a client from the dropdown first.",parent=d); return
            def after(new_name):
                sel.set(new_name); build()
            self._rename_client_prompt(c, after)
        mkbtn(selrow,"✏ Rename",do_rename_client,SECONDARY).pack(side="left",padx=(4,0))
        def do_remove_selected():
            c=sel.get()
            if not c:
                messagebox.showinfo("Pick a client","Choose a client from the dropdown first.",parent=d); return
            self.remove_clients_dialog(on_done=_after_removed,preselect=[c])
        mkbtn(selrow,"🗑 Remove",do_remove_selected,DANGER).pack(side="left",padx=(4,0))
        mkbtn(selrow,"⤴ Fill estimates from allocations",lambda:self._fill_estimates_prompt(parent=d,on_done=build),ACCENT,"#000").pack(side="left",padx=(6,0))
        cont=tk.Frame(body,bg=BG_DARK); cont.pack(fill="both",expand=True,padx=16,pady=8)
        per_entries={}; est_entries={}; plan_lbls={}
        def update_plan():
            # for each category: actual period total - sum of weekly estimates = left to plan
            for cat in CATEGORIES:
                try: total=float(per_entries[cat].get() or 0)
                except Exception: total=0
                planned=0
                for wk in WEEKS:
                    try: planned+=float(est_entries[(wk,cat)].get() or 0)
                    except Exception: pass
                left=total-planned
                col=DANGER if left<-1e-9 else SUCCESS
                plan_lbls[cat].config(text=f"plan left: {fmt(left)}",fg=col)
        def build():
            om["values"]=self._snapshot["clients"]
            for w in cont.winfo_children(): w.destroy()
            per_entries.clear(); est_entries.clear(); plan_lbls.clear()
            c=sel.get()
            if not c:
                tk.Label(cont,text="Pick a client to edit.",fg=TEXT2,bg=BG_DARK,font=FONT).pack(anchor="w"); return
            # ACTUAL period totals row
            tk.Label(cont,text="ACTUAL — hours for the whole period (one total per category)",fg=ACCENT,bg=BG_DARK,font=FONTB).pack(anchor="w",pady=(2,4))
            arow=tk.Frame(cont,bg=BG_PANEL); arow.pack(fill="x",pady=2)
            tk.Label(arow,text="Period total",fg=TEXT,bg=BG_PANEL,font=FONTB,width=14,anchor="w").grid(row=0,column=0,padx=6,pady=6,sticky="w")
            for j,cat in enumerate(CATEGORIES):
                cell=tk.Frame(arow,bg=BG_PANEL); cell.grid(row=0,column=j+1,padx=10,pady=4)
                tk.Label(cell,text=CAT_ABBR[cat],fg=ACCENT,bg=BG_PANEL,font=("Segoe UI",8,"bold")).pack()
                e=tk.Entry(cell,font=FONT,bg=BG_LIGHT,fg=TEXT,insertbackground=TEXT,relief="flat",width=8,justify="center")
                e.insert(0,fmt(self._snapshot["period"].get((c,cat),0.0))); e.pack(ipady=2)
                e.bind("<KeyRelease>",lambda ev:update_plan())
                per_entries[cat]=e
                pl=tk.Label(cell,text="",fg=SUCCESS,bg=BG_PANEL,font=("Segoe UI",7)); pl.pack()
                plan_lbls[cat]=pl
            # ESTIMATE weekly grid
            tk.Label(cont,text="ESTIMATE — planned per week (guide only, never deducts from actual)",fg=SECONDARY,bg=BG_DARK,font=FONTB).pack(anchor="w",pady=(12,4))
            eg=tk.Frame(cont,bg=BG_DARK); eg.pack(fill="x")
            tk.Label(eg,text="",bg=BG_DARK,width=14).grid(row=0,column=0)
            for j,cat in enumerate(CATEGORIES):
                tk.Label(eg,text=CAT_ABBR[cat],fg=SECONDARY,bg=BG_DARK,font=FONTB).grid(row=0,column=j+1,padx=10)
            for i,wk in enumerate(WEEKS):
                tk.Label(eg,text=week_label_short(wk),fg=TEXT,bg=BG_DARK,font=("Segoe UI",9),anchor="w").grid(row=i+1,column=0,sticky="w",padx=4,pady=2)
                for j,cat in enumerate(CATEGORIES):
                    es=tk.Entry(eg,font=FONT,bg=BG_DARK,fg=SECONDARY,insertbackground=SECONDARY,relief="flat",width=7,justify="center")
                    es.insert(0,fmt(self._snapshot["estimates"].get((c,wk,cat),0.0))); es.grid(row=i+1,column=j+1,padx=10,pady=2)
                    es.bind("<KeyRelease>",lambda ev:update_plan())
                    est_entries[(wk,cat)]=es
            update_plan()
        def save():
            c=sel.get()
            if not c:return
            per=[]; est=[]
            def _hours(entry,label):
                txt=entry.get().strip().replace(",","")
                try: v=float(txt or 0)
                except Exception:
                    entry.config(bg=DANGER_BG); messagebox.showerror("Not a number",f"{label}: '{entry.get()}' isn't an hours value. Nothing was saved — fix it and click Save again.",parent=d); return None
                if v<0:
                    entry.config(bg=DANGER_BG); messagebox.showerror("Negative hours",f"{label}: hours can't be negative. Nothing was saved.",parent=d); return None
                return v
            for cat,e in per_entries.items():
                v=_hours(e,f"Period total · {CAT_ABBR.get(cat,cat)}")
                if v is None: return
                per.append((cat,v))
            for (wk,cat),es in est_entries.items():
                v=_hours(es,f"{wk} · {CAT_ABBR.get(cat,cat)}")
                if v is None: return
                est.append((wk,cat,v))
            perdict=dict(per); estdict={(wk,cat):v for wk,cat,v in est}
            # Immediate local feedback. The network commit never owns the UI.
            self._cache_set_client_data(c,perdict,estdict); client_status.set("✓ Saved locally • syncing in background")
            def done(_): client_status.set("✓ Synced")
            def fail(exc):
                client_status.set("Cloud sync failed")
                messagebox.showerror("Cloud save failed",str(exc),parent=d)
            self._background_job(lambda:save_client_data_batch(c,per,est,self.user),done,fail,label="save_client_hours")
        om.bind("<<ComboboxSelected>>",lambda e:build())
        client_status=tk.StringVar(value="")
        tk.Label(body,textvariable=client_status,fg=SUCCESS,bg=BG_DARK,font=("Segoe UI Semibold",8,"bold")).pack(side="bottom",pady=(0,4))
        mkbtn(body,"💾 Save Client",save,ACCENT,"#000").pack(side="bottom",pady=10)
        build()

    # ----- SMART allocation dialog -----
    def shift_import_dialog(self):
        d,body=branded_dialog(self.root,"Import Shift Export (CSV)",
            "Pick a clock-in/clock-out export — shifts are ADDED to their matching week and never clear the other weeks. Exact times stay attached; category comes from the real day.",
            920,760)
        state={"shifts":[]}
        top=tk.Frame(body,bg=BG_DARK); top.pack(fill="x",padx=16,pady=(10,4))
        filelbl=tk.Label(top,text="No file chosen.",fg=TEXT2,bg=BG_DARK,font=FONT); filelbl.pack(side="left")

        def pick_file():
            path=filedialog.askopenfilename(filetypes=[("CSV files","*.csv"),("All files","*.*")])
            if not path: return
            try:
                shifts=parse_shift_export(path)
            except PermissionError:
                messagebox.showerror("Can't open the file — it's locked or not fully synced",
                    "Close it in Excel if it's open there, or if it's on OneDrive, make sure it's fully downloaded "
                    "('Always keep on this device'), then try again.",parent=d)
                return
            except Exception as e:
                messagebox.showerror("Could not read file",f"File: {path}\n\nError: {e}",parent=d); return
            if not shifts:
                messagebox.showwarning("Nothing to import",
                    "No complete shifts found (every row was either still in progress or unreadable).",parent=d)
                return
            state["shifts"]=shifts
            filelbl.config(text=f"✓ {os.path.basename(path)} — {len(shifts)} complete shift(s) found",fg=SUCCESS)
            messagebox.showinfo("File read successfully",f"Found {len(shifts)} complete shift(s) in {os.path.basename(path)}.\n\nClick Parse & Preview below.",parent=d)
            build_preview()
        mkbtn(top,"📂 Pick File",pick_file,SECONDARY).pack(side="left",padx=10)

        tk.Label(body,text="Preview — review every match before importing:",fg=ACCENT,bg=BG_DARK,font=FONTB).pack(anchor="w",padx=16,pady=(6,2))
        prevwrap=tk.Frame(body,bg=BG_DARK); prevwrap.pack(fill="both",expand=True,padx=16)
        prev_inner=self._scrollable(prevwrap)
        cntlbl=tk.Label(body,text="",fg=ACCENT,bg=BG_DARK,font=FONTB); cntlbl.pack(anchor="w",padx=16,pady=(4,4))

        preview_holder=[[]]   # list of dicts: shift, app_week, worker_match, client_match, worker_addvar, client_addvar
        def build_preview():
            for ch in prev_inner.winfo_children(): ch.destroy()
            shifts=state["shifts"]
            all_workers=list_workers(); all_clients=list_clients()
            items=[]
            skipped_outside_weeks=0
            by_week={}
            for sh in shifts:
                wk=week_for_date(sh["date"])
                if not wk: skipped_outside_weeks+=1; continue
                by_week.setdefault(wk,[]).append(sh)
            for wk in WEEKS:
                if wk not in by_week: continue
                tk.Label(prev_inner,text=f"{wk} — {week_label_short(wk).split('·')[-1].strip()}",fg=CYAN,bg=BG_DARK,font=("Segoe UI",11,"bold")).pack(anchor="w",pady=(10,2))
                for sh in by_week[wk]:
                    wmatch,wreason=fuzzy_match(sh["worker"],all_workers)
                    cmatch,creason=fuzzy_match(sh["client"],all_clients)
                    row=tk.Frame(prev_inner,bg=(BG_PANEL if (wmatch and cmatch) else DANGER_BG)); row.pack(fill="x",pady=1)
                    inclvar=tk.BooleanVar(value=True)   # include this shift by default — untick to skip it
                    topline=tk.Frame(row,bg=row["bg"]); topline.pack(fill="x",padx=10,pady=(4,0))
                    tk.Checkbutton(topline,text="",variable=inclvar,fg=TEXT,bg=row["bg"],selectcolor=BG_LIGHT,
                                   activebackground=row["bg"],activeforeground=TEXT).pack(side="left")
                    txt=(f"{sh['date'].strftime('%d %b')} {sh['start_time']}-{sh['end_time']} ({fmt(sh['hours'])}h, {CAT_ABBR[sh['category']]})   "
                         f"{sh['worker']}"+(f" → {wmatch}" if wmatch else " → ⚠ not in system"))
                    tk.Label(topline,text=txt,fg=(TEXT if wmatch else DANGER),bg=row["bg"],font=("Segoe UI",9),wraplength=760,justify="left").pack(side="left",anchor="w")
                    # Client — an editable dropdown, defaulting to the matched (or raw) name.
                    # Pick any EXISTING client to reassign this shift; leave/type something new
                    # and tick "add as new" below to create it.
                    clientrow=tk.Frame(row,bg=row["bg"]); clientrow.pack(fill="x",padx=(30,10),pady=(2,0))
                    tk.Label(clientrow,text="Client:",fg=TEXT2,bg=row["bg"],font=("Segoe UI",9)).pack(side="left",padx=(0,4))
                    cvar=tk.StringVar(value=cmatch or sh["client"])
                    ttk.Combobox(clientrow,textvariable=cvar,values=all_clients,width=22).pack(side="left")
                    optrow=tk.Frame(row,bg=row["bg"]); optrow.pack(anchor="w",padx=(30,10),pady=(2,4))
                    waddvar=None; caddvar=None
                    if not wmatch:
                        waddvar=tk.BooleanVar(value=False)
                        tk.Checkbutton(optrow,text=f"Add '{sh['worker']}' as new worker",variable=waddvar,fg=TEXT,bg=row["bg"],
                                       selectcolor=BG_LIGHT,activebackground=row["bg"],activeforeground=TEXT,font=("Segoe UI",9)).pack(side="left",padx=(0,12))
                    caddvar=tk.BooleanVar(value=False)
                    tk.Checkbutton(optrow,text="Add as new client if not an existing one above",variable=caddvar,fg=TEXT,bg=row["bg"],
                                   selectcolor=BG_LIGHT,activebackground=row["bg"],activeforeground=TEXT,font=("Segoe UI",9)).pack(side="left")
                    items.append({"shift":sh,"app_week":wk,"worker_match":wmatch,"client_var":cvar,
                                  "worker_addvar":waddvar,"client_addvar":caddvar,"include_var":inclvar})
            preview_holder[0]=items
            n_ready=sum(1 for it in items if it["worker_match"] and it["client_var"].get() in all_clients)
            msg=f"{len(items)} shift(s) in range — {n_ready} ready to import as-is. Untick any you don't want, or change the client per row."
            if skipped_outside_weeks: msg+=f"  ({skipped_outside_weeks} outside your current 6 weeks — skipped.)"
            cntlbl.config(text=msg)
        mkbtn(body,"🔍 Parse & Preview",build_preview,PRIMARY).pack(anchor="w",padx=16,pady=(2,4))

        def do_import():
            items=preview_holder[0]
            existing_c_now=set(list_clients())
            to_import=[]
            for it in items:
                if not it["include_var"].get(): continue   # unticked — skip entirely
                client_val=it["client_var"].get().strip()
                client_ok = client_val in existing_c_now or (it["client_addvar"] and it["client_addvar"].get() and client_val)
                worker_ok = it["worker_match"] or (it["worker_addvar"] and it["worker_addvar"].get())
                if worker_ok and client_ok:
                    to_import.append(it)
            if not to_import:
                messagebox.showwarning("Nothing to import","No shifts are ticked and ready — check the include box, pick a real client, or tick 'add as new'.",parent=d); return
            if not messagebox.askyesno("Confirm Import",
                    f"Import {len(to_import)} shift(s) as new allocations, each with its exact clock-in/clock-out times attached?",parent=d):
                return
            existing_w=set(self._snapshot.get("workers",[])); existing_c=set(self._snapshot.get("clients",[]))
            new_workers=[]; new_clients=[]; rows=[]
            for it in to_import:
                sh=it["shift"]
                worker=it["worker_match"] or sh["worker"]
                client=it["client_var"].get().strip()
                if worker not in existing_w:
                    existing_w.add(worker); new_workers.append(worker)
                if client not in existing_c:
                    existing_c.add(client); new_clients.append(client)
                try: hrs=float(sh["hours"] or 0)
                except Exception: hrs=0
                if hrs<=0: continue
                rows.append((it["app_week"],worker,client,sh["category"],hrs,"","",sh["start_time"],sh["end_time"]))
            if not rows:
                messagebox.showwarning("Nothing to import","No valid positive-hour shifts remain.",parent=d); return
            import_btn.config(state="disabled",text="Importing…")
            def done(n):
                d.destroy(); self.refresh()
                messagebox.showinfo("Imported",f"Created {n} allocation(s) in one batch. Other weeks were left untouched.",parent=self.root)
            def failed(exc):
                import_btn.config(state="normal",text="💾 Import Shifts")
                messagebox.showerror("Import failed",str(exc),parent=d)
            self._background_job(lambda:save_allocations_batch(rows,self.user,new_workers,new_clients),
                                 done,failed,sync_after=True,label="shift_import_batch")
        import_btn=mkbtn(body,"💾 Import Shifts",do_import,PRIMARY); import_btn.pack(side="bottom",pady=12)

    def cmv_week_import_dialog(self,path,cmv):
        """Specialized fast weekly import: Totals->CMV wage only + CareMile source reference."""
        d,body=branded_dialog(self.root,"Import CareMile CMV Week",
            "Imports ONLY the CMV wage column into one chosen week. Choose exactly which workers to add. Other weeks stay untouched.",1040,760)
        targetv=tk.StringVar(value=self.cur_week.get())
        head=tk.Frame(body,bg=CARD,highlightbackground=BORDER,highlightthickness=1); head.pack(fill="x",padx=16,pady=(10,7))
        period=f"{cmv.get('date_start','?')} → {cmv.get('date_end','?')}"
        tk.Label(head,text=f"{os.path.basename(path)}  •  CareMile VIC  •  {period}",fg=TEXT,bg=CARD,font=("Segoe UI Semibold",9,"bold")).pack(side="left",padx=12,pady=9)
        tk.Label(head,text="IMPORT INTO",fg=TEXT2,bg=CARD,font=("Segoe UI Semibold",7,"bold")).pack(side="left",padx=(18,5))
        tcb=ttk.Combobox(head,textvariable=targetv,values=WEEKS,state="readonly",width=10,style="Modern.TCombobox"); tcb.pack(side="left")
        datelbl=tk.Label(head,text="",fg=CYAN,bg=CARD,font=("Segoe UI Semibold",8)); datelbl.pack(side="left",padx=8)
        def upd_date(*_):datelbl.config(text="Week Ending "+fmt_date(get_week_date(targetv.get())))
        targetv.trace_add("write",upd_date); upd_date()

        tk.Label(body,text="SELECT WAGES TO IMPORT — values below are from Totals → CMV only",fg=TEXT2,bg=BG_DARK,font=("Segoe UI Semibold",8,"bold")).pack(anchor="w",padx=18,pady=(4,3))
        wrap=tk.Frame(body,bg=BG_DARK); wrap.pack(fill="both",expand=True,padx=16)
        canvas=tk.Canvas(wrap,bg=BG_DARK,highlightthickness=0); vs=tk.Scrollbar(wrap,orient="vertical",command=canvas.yview)
        inner=tk.Frame(canvas,bg=BG_DARK); win=canvas.create_window((0,0),window=inner,anchor="nw")
        inner.bind("<Configure>",lambda e:canvas.configure(scrollregion=canvas.bbox("all")))
        canvas.bind("<Configure>",lambda e:canvas.itemconfigure(win,width=e.width))
        canvas.configure(yscrollcommand=vs.set); canvas.pack(side="left",fill="both",expand=True); vs.pack(side="right",fill="y")
        existing=list(self._snapshot.get("workers",[])); items=[]
        sessions=cmv.get('sessions',[])
        for entry in cmv.get('wages',[]):
            src=entry['source_worker']; amount=float(entry['amount'])
            matched,reason=fuzzy_match(src,existing)
            if not matched:
                first=[w for w in existing if w.lower().split()[0:1]==src.lower().split()[0:1]]
                if len(first)==1:matched=first[0]
            use=tk.BooleanVar(value=bool(matched)); target=tk.StringVar(value=matched or src)
            srcrows=_cmv_rows_for_source(src,sessions)
            approved=[r for r in srcrows if str(r.get('status','')).strip().lower() not in ('rejected','cancelled','canceled','declined')]
            days=[]
            for r in approved:
                if r.get('date'):
                    try: label=datetime.strptime(r['date'],'%Y-%m-%d').strftime('%a %d %b')
                    except Exception: label=r.get('day','')
                    if label and label not in days:days.append(label)
            row=tk.Frame(inner,bg=CARD,highlightbackground=BORDER,highlightthickness=1); row.pack(fill="x",pady=2)
            tk.Checkbutton(row,variable=use,bg=CARD,selectcolor=BG_LIGHT,activebackground=CARD).pack(side="left",padx=8)
            tk.Label(row,text=src,fg=TEXT,bg=CARD,font=("Segoe UI Semibold",9,"bold"),width=20,anchor="w").pack(side="left",pady=7)
            tk.Label(row,text="$"+fmt(amount),fg=SUCCESS,bg=CARD,font=("Segoe UI Semibold",9,"bold"),width=11,anchor="e").pack(side="left",padx=5)
            tk.Label(row,text="→",fg=TEXT2,bg=CARD).pack(side="left",padx=5)
            cb=ttk.Combobox(row,textvariable=target,values=existing,state="normal",width=23,style="Modern.TCombobox"); cb.pack(side="left",padx=5)
            tk.Label(row,text=("Worked: "+" • ".join(days) if days else "No CareMile shifts found"),fg=CYAN if days else TEXT2,bg=CARD,font=("Segoe UI",8),anchor="w").pack(side="left",fill="x",expand=True,padx=10)
            items.append({'use':use,'target':target,'source':src,'amount':amount,'rows':srcrows})
        controls=tk.Frame(body,bg=BG_DARK); controls.pack(fill="x",padx=16,pady=6)
        tk.Button(controls,text="Select All",command=lambda:[it['use'].set(True) for it in items],bg=CONTROL,fg=TEXT,relief="flat",bd=0,padx=10,pady=5).pack(side="left")
        tk.Button(controls,text="Clear All",command=lambda:[it['use'].set(False) for it in items],bg=CONTROL,fg=TEXT,relief="flat",bd=0,padx=10,pady=5).pack(side="left",padx=6)
        status=tk.StringVar(value=f"{len(items)} non-zero CMV wage rows found. Nothing is imported until you confirm.")
        tk.Label(controls,textvariable=status,fg=TEXT2,bg=BG_DARK,font=("Segoe UI",8)).pack(side="left",padx=12)
        def do_import():
            selected=[it for it in items if it['use'].get() and it['target'].get().strip()]
            if not selected:messagebox.showwarning("Nothing selected","Choose at least one worker wage to import.",parent=d);return
            wk=targetv.get(); new_workers=[]; changes=[]; source_rows=[]; known=set(self._snapshot.get('workers',[]))
            for it in selected:
                target=it['target'].get().strip()
                if target not in known: known.add(target); new_workers.append(target)
                changes.append((target,wk,it['amount']))
                for rr in it['rows']:
                    source_rows.append({'week':wk,'worker':target,'source_worker':rr.get('source_worker',it['source']),
                        'work_date':rr.get('date',''),'day':rr.get('day',''),'client':rr.get('client',''),'service':rr.get('service',''),
                        'hours':rr.get('hours',0),'start_time':rr.get('start_time',''),'end_time':rr.get('end_time',''),
                        'status':rr.get('status',''),'source_note':rr.get('note',''),'source_file':cmv.get('source_file',os.path.basename(path))})
            if not messagebox.askyesno("Confirm CMV Import",f"Import {len(changes)} selected CMV wage(s) into {wk} ({fmt_date(get_week_date(wk))})?\n\nNo other week will be changed.\nCareMile session rows are stored as read-only reference only — no allocations are created.",parent=d):return
            # optimistic wage values immediately; source info appears after cloud commit/reload
            for w in new_workers:self._cache_add_worker(w)
            self._cache_set_wages(changes); status.set("✓ Wages applied locally • saving CMV reference in background…")
            btn.config(state="disabled",text="Saving…")
            def done(res):
                d.destroy(); self._reload_snapshot(); self._update_all_from_cache()
                messagebox.showinfo("CMV week imported",f"Imported {res[0]} selected wage(s) into {wk}.\nStored {res[1]} CareMile source row(s) for reference.\nOther weeks were untouched.",parent=self.root)
            def fail(exc):
                btn.config(state="normal",text="Import Selected Wages"); status.set("Save failed")
                messagebox.showerror("Import failed",str(exc),parent=d)
            self._background_job(lambda:save_cmv_week_import_batch(new_workers,changes,source_rows,self.user),done,fail,sync_after=True,label="cmv_week_import")
        btn=mkbtn(body,"Import Selected Wages",do_import,PRIMARY); btn.pack(side="bottom",pady=10)

    def payroll_import_dialog(self):
        d,body=branded_dialog(self.root,"Import Wages from Payroll File","Import ONE week into any Week 1–6 without touching the other weeks. Bulk 6-week import is still available when you want it.",940,760)
        state={"companies":[],"blocks":[],"path":None}; preview_holder=[[]]; mapping_holder=[[]]
        top=tk.Frame(body,bg=BG_DARK); top.pack(fill="x",padx=16,pady=(10,5))
        filelbl=tk.Label(top,text="No file chosen.",fg=TEXT2,bg=BG_DARK,font=FONT); filelbl.pack(side="left",fill="x",expand=True)
        compv=tk.StringVar(); sourcev=tk.StringVar(); targetv=tk.StringVar(value=self.cur_week.get()); modev=tk.StringVar(value="single")

        def pick_file():
            path=filedialog.askopenfilename(filetypes=[("Excel files","*.xlsx"),("All files","*.*")])
            if not path:return
            try:
                cmv=parse_caremile_weekly_wage_file(path)
                if cmv is not None:
                    d.destroy(); self.cmv_week_import_dialog(path,cmv); return
                companies,blocks=parse_payroll_file(path)
            except Exception as e: messagebox.showerror("Could not read file",str(e),parent=d); return
            if not blocks: messagebox.showwarning("No weeks found","No 'Week ending ...' blocks were found in this payroll file.",parent=d); return
            state.update(path=path,companies=companies,blocks=blocks); filelbl.config(text=f"✓ {os.path.basename(path)} • {len(blocks)} week(s) found",fg=SUCCESS)
            comp_combo.configure(values=companies); source_combo.configure(values=[b["label"] for b in blocks])
            if companies:compv.set(next((c for c in companies if c.lower()=="cmv"),companies[0]))
            # Prefer the source date that already matches the selected app week.
            wanted=parse_week_date(get_week_date(targetv.get()))
            match=next((b for b in blocks if b.get("date")==wanted),blocks[0]); sourcev.set(match["label"]); update_mapping()
        mkbtn(top,"Pick Payroll File",pick_file,SECONDARY).pack(side="right",padx=6)

        mode=tk.Frame(body,bg=CARD,highlightbackground=BORDER,highlightthickness=1); mode.pack(fill="x",padx=16,pady=6)
        tk.Label(mode,text="IMPORT MODE",fg=TEXT2,bg=CARD,font=("Segoe UI",8,"bold")).pack(side="left",padx=(12,6),pady=9)
        tk.Radiobutton(mode,text="One week (recommended)",variable=modev,value="single",fg=TEXT,bg=CARD,selectcolor=BG_LIGHT,activebackground=CARD,activeforeground=TEXT,font=FONT).pack(side="left",padx=8)
        tk.Radiobutton(mode,text="Bulk 6 weeks",variable=modev,value="bulk",fg=TEXT,bg=CARD,selectcolor=BG_LIGHT,activebackground=CARD,activeforeground=TEXT,font=FONT).pack(side="left",padx=8)
        tk.Label(mode,text="Other weeks are never cleared.",fg=SUCCESS,bg=CARD,font=("Segoe UI Semibold",8,"bold")).pack(side="right",padx=12)

        row=tk.Frame(body,bg=BG_DARK); row.pack(fill="x",padx=16,pady=7)
        tk.Label(row,text="Company",fg=TEXT2,bg=BG_DARK,font=FONTB).pack(side="left")
        comp_combo=ttk.Combobox(row,textvariable=compv,values=[],state="readonly",width=14,style="Modern.TCombobox"); comp_combo.pack(side="left",padx=(6,18))
        tk.Label(row,text="Payroll source week",fg=TEXT2,bg=BG_DARK,font=FONTB).pack(side="left")
        source_combo=ttk.Combobox(row,textvariable=sourcev,values=[],state="readonly",width=26,style="Modern.TCombobox"); source_combo.pack(side="left",padx=6)
        tk.Label(row,text="Import into",fg=TEXT2,bg=BG_DARK,font=FONTB).pack(side="left",padx=(16,4))
        target_combo=ttk.Combobox(row,textvariable=targetv,values=WEEKS,state="readonly",width=9,style="Modern.TCombobox"); target_combo.pack(side="left")
        maplbl=tk.Label(body,text="",fg=CYAN,bg=BG_DARK,font=("Segoe UI Semibold",9),justify="left"); maplbl.pack(anchor="w",padx=18,pady=(2,5))

        def update_mapping(*_):
            blocks=state["blocks"]
            if not blocks or not sourcev.get(): mapping_holder[0]=[]; maplbl.config(text=""); return
            idx=next((i for i,b in enumerate(blocks) if b["label"]==sourcev.get()),None)
            if idx is None:return
            if modev.get()=="single":
                mapping_holder[0]=[(targetv.get(),blocks[idx])]
            else:
                picked=blocks[idx:idx+6]; mapping_holder[0]=[(WEEKS[i],b) for i,b in enumerate(picked)]
            maplbl.config(text="   •   ".join(f"{wk} ← {b['label']}" for wk,b in mapping_holder[0]))
        for v in (sourcev,targetv,modev):v.trace_add("write",update_mapping)

        tk.Label(body,text="PREVIEW",fg=TEXT2,bg=BG_DARK,font=("Segoe UI Semibold",9,"bold")).pack(anchor="w",padx=18,pady=(6,3))
        prevwrap=tk.Frame(body,bg=BG_DARK); prevwrap.pack(fill="both",expand=True,padx=16); prev_inner=self._scrollable(prevwrap)
        cntlbl=tk.Label(body,text="",fg=TEXT2,bg=BG_DARK,font=("Segoe UI",9)); cntlbl.pack(anchor="w",padx=18,pady=4)
        def build_preview():
            for ch in prev_inner.winfo_children():ch.destroy()
            mappings=mapping_holder[0]; comp=compv.get()
            if not mappings or not comp: tk.Label(prev_inner,text="Choose a file, company and source week first.",fg=TEXT2,bg=BG_DARK).pack(anchor="w"); return
            all_workers=list_workers(); items=[]
            for app_week,block in mappings:
                tk.Label(prev_inner,text=f"{app_week}  ←  {block['label']}",fg=PRIMARY,bg=BG_DARK,font=("Segoe UI Semibold",10,"bold")).pack(anchor="w",pady=(8,2))
                for name,vals in block["rows"]:
                    val=vals.get(comp,0.0)
                    if val<=1e-9:continue
                    matched,reason=fuzzy_match(name,all_workers); addvar=None
                    rowf=tk.Frame(prev_inner,bg=(CARD if matched else DANGER_BG)); rowf.pack(fill="x",pady=1)
                    if matched:
                        tk.Label(rowf,text=f"{name}  →  {matched}    ${fmt(val)}",fg=(SUCCESS if reason=="exact" else ACCENT),bg=rowf["bg"],font=FONT).pack(side="left",padx=10,pady=4)
                    else:
                        tk.Label(rowf,text=f"{name}    ${fmt(val)}  • not in system",fg=DANGER,bg=rowf["bg"],font=FONT).pack(side="left",padx=10,pady=4)
                        addvar=tk.BooleanVar(value=False); tk.Checkbutton(rowf,text="Add worker",variable=addvar,fg=TEXT,bg=rowf["bg"],selectcolor=BG_LIGHT,activebackground=rowf["bg"],activeforeground=TEXT).pack(side="left",padx=8)
                    items.append({"app_week":app_week,"block":block,"file_name":name,"value":val,"matched":matched,"addvar":addvar})
            preview_holder[0]=items; cntlbl.config(text=f"{len(items)} wage entries ready. Import updates only the workers shown in the target week(s); all other weeks remain untouched.")
        mkbtn(body,"Preview Import",build_preview,SECONDARY).pack(anchor="w",padx=18,pady=(4,6))

        def do_import():
            items=preview_holder[0]
            if not items: messagebox.showwarning("Nothing to import","Preview the import first.",parent=d); return
            selected=[it for it in items if it["matched"] or (it["addvar"] and it["addvar"].get())]
            if not selected: messagebox.showwarning("Nothing selected","No matched or selected new workers.",parent=d); return
            weeks=sorted({it["app_week"] for it in selected},key=lambda x:WEEKS.index(x))
            # Be explicit when the import will CHANGE a week's ending date — that shifts
            # the calendar date of every existing allocation in that week.
            date_notes=[]
            for wk,block in mapping_holder[0]:
                if block.get("date"):
                    new_iso=block["date"].isoformat(); cur_iso=get_week_date(wk)
                    if cur_iso and cur_iso!=new_iso: date_notes.append(f"{wk}: {fmt_date(cur_iso)} → {fmt_date(new_iso)}")
            msg=f"Import {len(selected)} wage values into {', '.join(weeks)}?\n\nNo other week will be cleared or deleted."
            if date_notes: msg+="\n\nThis will also change these week-ending dates:\n  • "+"\n  • ".join(date_notes)
            if not messagebox.askyesno("Confirm Import",msg,parent=d):return
            existing=set(self._snapshot.get("workers",[])); changes=[]; new_workers=[]
            for it in selected:
                target=it["matched"]
                if not target:
                    target=it["file_name"]
                    if target not in existing:
                        existing.add(target); new_workers.append(target)
                changes.append((target,it["app_week"],it["value"]))
            date_updates={wk:block["date"].isoformat() for wk,block in mapping_holder[0] if block.get("date")}
            import_pay_btn.config(state="disabled",text="Importing…")
            def work(): return save_payroll_import_batch(new_workers,changes,date_updates,self.user)
            def done(res):
                n,newn=res; d.destroy(); self.refresh()
                messagebox.showinfo("Imported",f"Imported {n} wage values"+(f" and added {newn} worker(s)" if newn else "")+". Other weeks were left exactly as they were.",parent=self.root)
            def fail(exc):
                import_pay_btn.config(state="normal",text="Import Selected Week(s)")
                messagebox.showerror("Import failed",str(exc),parent=d)
            self._background_job(work,done,fail,sync_after=True,label="payroll_import_batch")
        import_pay_btn=mkbtn(body,"Import Selected Week(s)",do_import,PRIMARY); import_pay_btn.pack(side="bottom",pady=12)

    def bulk_chains_dialog(self):
        d,body=branded_dialog(self.root,"Bulk Import Chains",
            "Paste one client per line: 'Client: Worker1, Worker2, Worker3'. Names don't need to be exact — close spellings (like 'Steph' for 'stephanie') are matched automatically, and you confirm before anything saves.",
            820,700)
        tk.Label(body,text="Paste your chains:",fg=TEXT,bg=BG_DARK,font=FONTB).pack(anchor="w",padx=16,pady=(10,4))
        txt=tk.Text(body,height=8,bg=BG_LIGHT,fg=TEXT,insertbackground=TEXT,relief="flat",font=("Consolas",10))
        txt.pack(fill="x",padx=16)
        template=("Ameer: Manar\n"
                   "Wafaa: Anisa, Mais, Ritima\n"
                   "Steph: Manar, Anisa, Mais\n"
                   "Havaa: Nadin, Wulan, Mais, Asmaa, Ritima, Alok\n"
                   "Aylin: Wulan, Mais, Asmaa, Ritima, Alok\n")
        txt.insert("1.0",template)

        tk.Label(body,text="Preview — review every match before saving:",fg=ACCENT,bg=BG_DARK,font=FONTB).pack(anchor="w",padx=16,pady=(10,2))
        prevwrap=tk.Frame(body,bg=BG_DARK); prevwrap.pack(fill="both",expand=True,padx=16)
        prev_inner=self._scrollable(prevwrap)
        result_holder=[[]]   # list of dicts: {ok, client_in, client_match, workers:[(in,match,ok)], reason}

        def parse_and_preview():
            for ch in prev_inner.winfo_children(): ch.destroy()
            raw=txt.get("1.0","end").strip()
            all_clients=list_clients(); all_workers=list_workers()
            results=[]
            for line in raw.split("\n"):
                line=line.strip()
                if not line or ":" not in line: continue
                cli_in,rest=line.split(":",1)
                cli_in=cli_in.strip()
                cmatch,creason=fuzzy_match(cli_in, all_clients)
                worker_ins=[w.strip() for w in rest.split(",") if w.strip()]
                wresults=[]
                for wi in worker_ins:
                    wmatch,wreason=fuzzy_match(wi, all_workers)
                    wresults.append((wi,wmatch,wreason))
                ok = cmatch is not None and all(wm for _,wm,_ in wresults) and len(wresults)>0
                results.append({"client_in":cli_in,"client_match":cmatch,"client_reason":creason,
                                 "workers":wresults,"ok":ok})
            result_holder[0]=results
            if not results:
                tk.Label(prev_inner,text="Nothing parsed — check the format is 'Client: Worker1, Worker2'.",
                         fg=WARNING,bg=BG_DARK,font=FONT).pack(anchor="w",pady=6)
            for r in results:
                block=tk.Frame(prev_inner,bg=(BG_PANEL if r["ok"] else DANGER_BG)); block.pack(fill="x",pady=3)
                if r["client_match"]:
                    ctext=f"{r['client_in']} → {r['client_match']}"+(" (exact)" if r["client_reason"]=="exact" else " (close match)")
                    ccol=SUCCESS if r["client_reason"]=="exact" else ACCENT
                else:
                    ctext=f"{r['client_in']} → ❌ no client found ({r['client_reason']})"; ccol=DANGER
                tk.Label(block,text=ctext,fg=ccol,bg=block["bg"],font=FONTB).pack(anchor="w",padx=10,pady=(6,2))
                wparts=[]
                for wi,wm,wreason in r["workers"]:
                    if wm: wparts.append(f"{wi}→{wm}")
                    else: wparts.append(f"{wi}→❌({wreason})")
                wcol=SUCCESS if r["ok"] else DANGER
                tk.Label(block,text="   "+"   ".join(wparts),fg=wcol,bg=block["bg"],font=("Segoe UI",9)).pack(anchor="w",padx=10,pady=(0,6))
            ok_n=sum(1 for r in results if r["ok"])
            cntlbl.config(text=f"{ok_n} of {len(results)} line(s) fully matched and ready to save.")
        mkbtn(body,"🔍 Parse & Preview",parse_and_preview,SECONDARY).pack(anchor="w",padx=16,pady=(6,4))

        cntlbl=tk.Label(body,text="",fg=ACCENT,bg=BG_DARK,font=FONTB); cntlbl.pack(anchor="w",padx=16,pady=(2,4))

        def do_save():
            results=result_holder[0]
            good=[r for r in results if r["ok"]]
            if not good:
                messagebox.showwarning("Nothing to save","No fully-matched lines yet. Click Parse & Preview first, and fix any ❌ lines.",parent=d); return
            names=", ".join(r["client_match"] for r in good)
            if not messagebox.askyesno("Confirm Save",f"Save chains for: {names}?\n\nAny ❌ lines above are skipped — fix and re-paste those separately.",parent=d):
                return
            chains=[(r["client_match"],[wm for _,wm,_ in r["workers"]]) for r in good]
            bulk_chain_btn.config(state="disabled",text="Saving…")
            def done(n):
                d.destroy(); messagebox.showinfo("Saved",f"Saved {n} chain(s): {names}",parent=self.root)
            def fail(exc):
                bulk_chain_btn.config(state="normal",text="💾 Save All Matched Chains")
                messagebox.showerror("Save failed",str(exc),parent=d)
            self._background_job(lambda:save_chains_batch(chains,self.user),done,fail,label="save_chains_batch")
        bulk_chain_btn=mkbtn(body,"💾 Save All Matched Chains",do_save,PRIMARY); bulk_chain_btn.pack(side="bottom",pady=12)
        parse_and_preview()

    def users_dialog(self):
        if self.role!="manager":
            messagebox.showwarning("Managers only","Only a manager account can add users or reset passwords.")
            return
        d,body=branded_dialog(self.root,"Manage Users","Add a new login, or reset someone's forgotten password.",680,600)
        inner=self._scrollable(body)

        tk.Label(inner,text="Existing users:",fg=ACCENT,bg=BG_DARK,font=("Segoe UI",12,"bold")).pack(anchor="w",padx=16,pady=(14,6))
        listwrap=tk.Frame(inner,bg=BG_DARK); listwrap.pack(fill="x",padx=16)
        def draw_users():
            for ch in listwrap.winfo_children(): ch.destroy()
            for uname,urole,ucreated in list_users():
                row=tk.Frame(listwrap,bg=BG_PANEL); row.pack(fill="x",pady=2)
                tk.Label(row,text=f"{uname}  ({urole})",fg=TEXT,bg=BG_PANEL,font=FONTB).pack(side="left",padx=10,pady=8)
                def do_reset(u=uname): self._reset_password_prompt(u, draw_users)
                mkbtn(row,"🔑 Reset Password",do_reset,WARNING).pack(side="right",padx=8,pady=6)
        draw_users()

        sep=tk.Frame(inner,bg=BG_LIGHT,height=1); sep.pack(fill="x",padx=16,pady=16)
        tk.Label(inner,text="Add a new user:",fg=ACCENT,bg=BG_DARK,font=("Segoe UI",12,"bold")).pack(anchor="w",padx=16,pady=(0,6))
        f=tk.Frame(inner,bg=BG_DARK); f.pack(fill="x",padx=16)
        tk.Label(f,text="Username",fg=TEXT2,bg=BG_DARK,font=FONT).grid(row=0,column=0,sticky="w",pady=6)
        uv=tk.StringVar()
        tk.Entry(f,textvariable=uv,font=FONT,bg=BG_LIGHT,fg=TEXT,insertbackground=TEXT,relief="flat",width=24).grid(row=0,column=1,padx=8)
        tk.Label(f,text="Password",fg=TEXT2,bg=BG_DARK,font=FONT).grid(row=1,column=0,sticky="w",pady=6)
        pv=tk.StringVar()
        tk.Entry(f,textvariable=pv,font=FONT,bg=BG_LIGHT,fg=TEXT,insertbackground=TEXT,relief="flat",width=24,show="•").grid(row=1,column=1,padx=8)
        tk.Label(f,text="Role",fg=TEXT2,bg=BG_DARK,font=FONT).grid(row=2,column=0,sticky="w",pady=6)
        rv=tk.StringVar(value="staff")
        ttk.Combobox(f,textvariable=rv,values=["manager","staff"],state="readonly",width=21).grid(row=2,column=1,padx=8)
        def do_add():
            u=uv.get().strip(); pw=pv.get()
            if not u or not pw:
                messagebox.showwarning("Missing info","Enter a username and password.",parent=d); return
            if len(pw)<4:
                messagebox.showwarning("Too short","Use at least 4 characters for the password.",parent=d); return
            role=rv.get()
            add_btn.config(state="disabled",text="Adding…")
            def done(_):
                add_btn.config(state="normal",text="➕ Add User")
                messagebox.showinfo("User added",f"'{u}' can now log in with the password you set.",parent=d)
                uv.set(""); pv.set(""); draw_users()
            def fail(exc):
                add_btn.config(state="normal",text="➕ Add User")
                messagebox.showerror("Could not add",str(exc),parent=d)
            # Cloud round-trip off the UI thread, and always into the LIVE user table.
            self._background_job(lambda:create_user(u,pw,role),done,fail,label="create_user")
        add_btn=mkbtn(inner,"➕ Add User",do_add,SUCCESS,"#000"); add_btn.pack(anchor="w",padx=16,pady=14)

    def _reset_password_prompt(self, username, on_done):
        d,body=branded_dialog(self.root,f"Reset Password — {username}","Set a new password. The old one stops working immediately.",420,240)
        tk.Label(body,text="New password",fg=TEXT2,bg=BG_DARK,font=FONT).pack(anchor="w",padx=16,pady=(16,4))
        pv=tk.StringVar()
        tk.Entry(body,textvariable=pv,font=FONT,bg=BG_LIGHT,fg=TEXT,insertbackground=TEXT,relief="flat",width=28,show="•").pack(padx=16,ipady=5)
        def do_reset():
            pw=pv.get()
            if len(pw)<4:
                messagebox.showwarning("Too short","Use at least 4 characters.",parent=d); return
            if not messagebox.askyesno("Confirm",f"Reset the password for '{username}'? They'll need the new password to log in from now on.",parent=d):
                return
            reset_btn.config(state="disabled",text="Resetting…")
            def done(ok):
                if not ok:
                    reset_btn.config(state="normal",text="🔑 Reset Password")
                    messagebox.showerror("Not found",f"No user called '{username}' exists any more.",parent=d); return
                messagebox.showinfo("Password reset",f"'{username}''s password has been changed. Tell them the new password directly — it's never shown or stored anywhere readable.",parent=self.root)
                try: d.destroy()
                except Exception: pass
                on_done()
            def fail(exc):
                reset_btn.config(state="normal",text="🔑 Reset Password")
                messagebox.showerror("Reset failed",str(exc),parent=d)
            self._background_job(lambda:reset_password(username,pw),done,fail,label="reset_password")
        reset_btn=mkbtn(body,"🔑 Reset Password",do_reset,WARNING); reset_btn.pack(pady=18)

    def chains_dialog(self):
        d,body=branded_dialog(self.root,"Worker Chains",
            "Set an ORDERED fallback list of workers for a client. Try worker 1 first — whatever's still needed rolls to worker 2, then worker 3, and so on.",
            700,640)
        top=tk.Frame(body,bg=BG_DARK); top.pack(fill="x",padx=16,pady=(10,6))
        tk.Label(top,text="Client:",fg=TEXT,bg=BG_DARK,font=FONTB).pack(side="left")
        cv=tk.StringVar()
        ttk.Combobox(top,textvariable=cv,values=list_clients(),state="readonly",width=24).pack(side="left",padx=8)
        mkbtn(top,"📋 Bulk Import (paste multiple)",self.bulk_chains_dialog,SECONDARY).pack(side="left",padx=12)

        chainwrap=tk.Frame(body,bg=BG_PANEL); chainwrap.pack(fill="both",expand=True,padx=16,pady=6)
        tk.Label(chainwrap,text="Chain order (worker 1 tried first):",fg=ACCENT,bg=BG_PANEL,font=FONTB).pack(anchor="w",padx=10,pady=(8,4))
        rows_frame=tk.Frame(chainwrap,bg=BG_PANEL); rows_frame.pack(fill="both",expand=True,padx=10)

        current=[]  # list of worker names, in order — the working copy being edited
        def redraw():
            for ch in rows_frame.winfo_children(): ch.destroy()
            if not current:
                tk.Label(rows_frame,text="No workers in this chain yet. Add one below.",fg=TEXT2,bg=BG_PANEL,font=FONT).pack(anchor="w",pady=6)
            for i,w in enumerate(current):
                r=tk.Frame(rows_frame,bg=BG_LIGHT); r.pack(fill="x",pady=2)
                tk.Label(r,text=f"{i+1}.",fg=ACCENT,bg=BG_LIGHT,font=FONTB,width=3).pack(side="left",padx=(8,2),pady=6)
                tk.Label(r,text=w,fg=TEXT,bg=BG_LIGHT,font=FONTB,anchor="w").pack(side="left",fill="x",expand=True,pady=6)
                def mk_up(i=i):
                    def go():
                        if i>0: current[i-1],current[i]=current[i],current[i-1]; redraw()
                    return go
                def mk_down(i=i):
                    def go():
                        if i<len(current)-1: current[i+1],current[i]=current[i],current[i+1]; redraw()
                    return go
                def mk_del(i=i):
                    def go(): current.pop(i); redraw()
                    return go
                tk.Button(r,text="↑",command=mk_up(),bg=BG_DARK,fg=TEXT,relief="flat",width=3).pack(side="left",padx=1)
                tk.Button(r,text="↓",command=mk_down(),bg=BG_DARK,fg=TEXT,relief="flat",width=3).pack(side="left",padx=1)
                tk.Button(r,text="✕",command=mk_del(),bg=DANGER,fg="#fff",relief="flat",width=3).pack(side="left",padx=(1,8))

        addrow=tk.Frame(chainwrap,bg=BG_PANEL); addrow.pack(fill="x",padx=10,pady=(6,10))
        addv=tk.StringVar()
        ttk.Combobox(addrow,textvariable=addv,values=list_workers(),state="readonly",width=20).pack(side="left")
        def add_worker_to_chain():
            w=addv.get()
            if w and w not in current: current.append(w); redraw()
        mkbtn(addrow,"+ Add to chain",add_worker_to_chain,SECONDARY).pack(side="left",padx=8)

        def load_for_client(*_):
            current.clear(); current.extend(get_chain(cv.get())); redraw()
        cv.trace_add("write", load_for_client)

        def save_chain():
            if not cv.get():
                messagebox.showwarning("Pick a client","Choose a client first.",parent=d); return
            client=cv.get(); workers=list(current)
            chain_save_btn.config(state="disabled",text="Saving…")
            def done(_):
                chain_save_btn.config(state="normal",text="💾 Save Chain")
                messagebox.showinfo("Saved", f"Chain saved for {client}: "+" → ".join(workers) if workers else f"Chain cleared for {client}.",parent=d)
            def fail(exc):
                chain_save_btn.config(state="normal",text="💾 Save Chain")
                messagebox.showerror("Save failed",str(exc),parent=d)
            self._background_job(lambda:set_chain(client,workers,self.user),done,fail,label="save_worker_chain")
        chain_save_btn=mkbtn(body,"💾 Save Chain",save_chain,PRIMARY); chain_save_btn.pack(pady=10)
        redraw()

    def chain_auto_allocate_dialog(self):
        chain_clients=list_chain_clients()
        if not chain_clients:
            messagebox.showinfo("No chains yet","Set up a worker chain first (🔗 Worker Chains button).")
            return
        d,body=branded_dialog(self.root,"Auto Allocate (Chain)",
            "Fills a client's weekly estimates using their worker chain — across ALL 6 weeks — trying each worker in order until covered.",
            820,680)
        top=tk.Frame(body,bg=BG_DARK); top.pack(fill="x",padx=16,pady=(10,6))
        tk.Label(top,text="Client:",fg=TEXT,bg=BG_DARK,font=FONTB).pack(side="left")
        cv=tk.StringVar()
        ttk.Combobox(top,textvariable=cv,values=chain_clients,state="readonly",width=24).pack(side="left",padx=8)
        chainlbl=tk.Label(top,text="",fg=SECONDARY,bg=BG_DARK,font=FONT); chainlbl.pack(side="left",padx=12)

        tk.Label(body,text="Preview — what will be created, week by week:",fg=ACCENT,bg=BG_DARK,font=FONTB).pack(anchor="w",padx=16,pady=(6,2))
        prevwrap=tk.Frame(body,bg=BG_DARK); prevwrap.pack(fill="both",expand=True,padx=16)
        prev_inner=self._scrollable(prevwrap)

        plan_holder=[[]]  # mutable box so the closure can update it
        def build_preview(*_):
            for ch in prev_inner.winfo_children(): ch.destroy()
            c=cv.get()
            if not c:
                chainlbl.config(text=""); cntlbl.config(text=""); return
            chain=get_chain(c)
            chainlbl.config(text="Chain: "+" → ".join(chain))
            plan,shortfalls=plan_chain_allocation(c)
            plan_holder[0]=plan
            hdr=tk.Frame(prev_inner,bg=BG_DARK); hdr.pack(fill="x")
            for t,wd in [("Week",18),("Worker",16),("Category",10),("Hours",8),("Day",10)]:
                tk.Label(hdr,text=t,fg=TEXT2,bg=BG_DARK,font=("Segoe UI",8,"bold"),width=wd,anchor="w").pack(side="left")
            for wk,worker,cat,hrs,day in plan:
                rw=tk.Frame(prev_inner,bg=BG_DARK); rw.pack(fill="x",pady=1)
                for val,wd in [(week_label_short(wk),18),(worker,16),(CAT_ABBR[cat],10),(fmt(hrs),8),(day or "—",10)]:
                    tk.Label(rw,text=val,fg=TEXT,bg=BG_DARK,font=("Segoe UI",9),width=wd,anchor="w").pack(side="left")
            if shortfalls:
                tk.Label(prev_inner,text="⚠ Chain not enough — still needed (nothing forced onto anyone):",
                         fg=DANGER,bg=BG_DARK,font=("Segoe UI",9,"bold")).pack(anchor="w",pady=(10,2))
                for wk,cat,hrs in shortfalls:
                    tk.Label(prev_inner,text=f"   {week_label_short(wk)} · {CAT_ABBR[cat]}: {fmt(hrs)} hrs still needed",
                             fg=DANGER,bg=BG_DARK,font=("Segoe UI",9)).pack(anchor="w")
            if not plan and not shortfalls:
                tk.Label(prev_inner,text="Nothing to allocate — either no estimates are set, or everything is already covered.",
                         fg=TEXT2,bg=BG_DARK,font=FONT).pack(anchor="w",pady=6)
            msg=f"{len(plan)} allocation(s) will be created across all weeks."
            if shortfalls: msg+=f"   ({len(shortfalls)} shortfall spot(s) — see above)"
            cntlbl.config(text=msg)
        cv.trace_add("write", build_preview)

        cntlbl=tk.Label(body,text="",fg=ACCENT,bg=BG_DARK,font=FONTB); cntlbl.pack(anchor="w",padx=16,pady=(6,4))

        def do_run():
            c=cv.get(); plan=plan_holder[0]
            if not c or not plan:
                messagebox.showwarning("Nothing to do","Pick a client with something to allocate.",parent=d); return
            if not messagebox.askyesno("Confirm Auto Allocate (Chain)",
                    f"Create {len(plan)} allocation(s) for {c} using the chain, across all 6 weeks?",parent=d): return
            rows=[(wk,worker,c,cat,hrs,day,"auto-chain","","") for wk,worker,cat,hrs,day in plan if float(hrs or 0)>0]
            chain_run_btn.config(state="disabled",text="Allocating…")
            def done(n):
                d.destroy(); self.refresh(); messagebox.showinfo("Done",f"Created {n} allocation(s) in one batch.",parent=self.root)
            def fail(exc):
                chain_run_btn.config(state="normal",text="⚡ Run Chain Auto Allocate")
                messagebox.showerror("Auto Allocate failed",str(exc),parent=d)
            self._background_job(lambda:save_allocations_batch(rows,self.user),done,fail,sync_after=True,label="chain_auto_allocate_batch")
        chain_run_btn=mkbtn(body,"⚡ Run Chain Auto Allocate",do_run,PRIMARY); chain_run_btn.pack(side="bottom",pady=12)
        if chain_clients: cv.set(chain_clients[0])

    def auto_allocate_dialog(self):
        if not self._snapshot["workers"] or not self._snapshot["clients"]:
            messagebox.showwarning("Setup first","Add at least one worker and one client."); return
        d,body=branded_dialog(self.root,"Auto Allocate","Place a client's weekly estimates automatically under one worker",780,700)
        form=tk.Frame(body,bg=BG_DARK); form.pack(fill="x",padx=16,pady=(10,4))
        tk.Label(form,text="Worker",fg=TEXT2,bg=BG_DARK,font=FONT).grid(row=0,column=0,sticky="w",pady=5)
        wv=tk.StringVar(); ttk.Combobox(form,textvariable=wv,values=list_workers(),state="readonly",width=24).grid(row=0,column=1,padx=8)
        tk.Label(form,text="Client",fg=TEXT2,bg=BG_DARK,font=FONT).grid(row=1,column=0,sticky="w",pady=5)
        cv=tk.StringVar(); ttk.Combobox(form,textvariable=cv,values=list_clients(),state="readonly",width=24).grid(row=1,column=1,padx=8)
        # mode: whole period or one week
        tk.Label(form,text="Mode",fg=TEXT2,bg=BG_DARK,font=FONT).grid(row=2,column=0,sticky="w",pady=5)
        modev=tk.StringVar(value="Whole period")
        ttk.Combobox(form,textvariable=modev,values=["Whole period","One week"],state="readonly",width=24).grid(row=2,column=1,padx=8)
        tk.Label(form,text="Week (if One week)",fg=TEXT2,bg=BG_DARK,font=FONT).grid(row=3,column=0,sticky="w",pady=5)
        wkv=tk.StringVar(value=WEEKS[0])
        ttk.Combobox(form,textvariable=wkv,values=WEEKS,state="readonly",width=24).grid(row=3,column=1,padx=8)

        tk.Label(body,text="Preview — only what's MISSING will be created (already-allocated ones are skipped):",fg=ACCENT,bg=BG_DARK,font=FONTB).pack(anchor="w",padx=16,pady=(8,2))
        prevwrap=tk.Frame(body,bg=BG_DARK); prevwrap.pack(fill="both",expand=True,padx=16)
        prev_inner=self._scrollable(prevwrap)

        plan=[]  # (week, category, hours, day) — ONLY missing ones
        def weeks_in_scope():
            return [wkv.get()] if modev.get()=="One week" else WEEKS
        def build_preview(*_):
            for ch in prev_inner.winfo_children(): ch.destroy()
            plan.clear()
            w=wv.get(); c=cv.get()
            if not w or not c:
                tk.Label(prev_inner,text="Pick a worker and a client.",fg=TEXT2,bg=BG_DARK,font=FONT).pack(anchor="w",pady=6)
                cntlbl.config(text=""); leftlbl.config(text=""); return
            hdr=tk.Frame(prev_inner,bg=BG_DARK); hdr.pack(fill="x")
            for t,wd in [("Week",20),("Category",10),("Estimate",10),("Allocated",10),("Left",8),("Day",10)]:
                tk.Label(hdr,text=t,fg=TEXT2,bg=BG_DARK,font=("Segoe UI",8,"bold"),width=wd,anchor="w").pack(side="left")
            skipped=0
            for wk in weeks_in_scope():
                for cat in CATEGORIES:
                    est=get_client_estimate(c,wk,cat)
                    if est<=1e-9: continue
                    # already allocated against this client+week+category BY ANYONE
                    placed=sum(r[5] for r in allocations_for(wk) if r[3]==c and r[4]==cat)
                    left=est-placed
                    if left<=1e-9:
                        skipped+=1; continue   # fully covered -> skip
                    day = "Saturday" if cat=="Saturday" else ("Sunday" if cat=="Sunday" else "")
                    plan.append((wk,cat,left,day))
                    rw=tk.Frame(prev_inner,bg=BG_DARK); rw.pack(fill="x",pady=1)
                    for val,wd in [(week_label_short(wk),20),(CAT_ABBR[cat],10),(fmt(est),10),
                                   (fmt(placed),10),(fmt(left),8),(day or "—",10)]:
                        tk.Label(rw,text=val,fg=TEXT,bg=BG_DARK,font=("Segoe UI",9),width=wd,anchor="w").pack(side="left")
            if not plan:
                tk.Label(prev_inner,text=("All estimates in scope are already fully allocated — nothing left to create." if skipped else
                         "This client has no weekly estimates in scope. Add estimates first (Clients screen)."),
                         fg=WARNING,bg=BG_DARK,font=FONT).pack(anchor="w",pady=6)
            msg=f"{len(plan)} allocation(s) will be created."
            if skipped: msg+=f"   ({skipped} skipped — already fully allocated)"
            cntlbl.config(text=msg)
            # worker-left projection AFTER this plan, by name; respects mode
            self._auto_left_preview(w, plan, modev.get()=="One week", wkv.get(), leftlbl)
        for v in (wv,cv,modev,wkv): v.trace_add("write",build_preview)

        cntlbl=tk.Label(body,text="",fg=ACCENT,bg=BG_DARK,font=FONTB); cntlbl.pack(anchor="w",padx=16,pady=(6,2))
        leftlbl=tk.Label(body,text="",fg=SUCCESS,bg=BG_DARK,font=FONT,justify="left"); leftlbl.pack(anchor="w",padx=16,pady=(0,4))

        def do_auto():
            w=wv.get(); c=cv.get()
            if not w or not c or not plan:
                messagebox.showwarning("Nothing to do","Nothing missing to allocate for this selection.",parent=d); return
            scope = "the whole period" if modev.get()=="Whole period" else wkv.get()
            if not messagebox.askyesno("Confirm Auto Allocate",
                f"Create {len(plan)} allocation(s) for {w} → {c} across {scope}?\n\n(Already-allocated ones are skipped.)",parent=d): return
            rows=[(wk,w,c,cat,est,day,"auto","","") for wk,cat,est,day in plan if float(est or 0)>0]
            auto_run_btn.config(state="disabled",text="Allocating…")
            def done(n):
                d.destroy(); self.refresh(); messagebox.showinfo("Auto Allocate done",f"Created {n} allocation(s) in one batch.",parent=self.root)
            def fail(exc):
                auto_run_btn.config(state="normal",text="⚡ Run Auto Allocate")
                messagebox.showerror("Auto Allocate failed",str(exc),parent=d)
            self._background_job(lambda:save_allocations_batch(rows,self.user),done,fail,sync_after=True,label="auto_allocate_batch")
        auto_run_btn=mkbtn(body,"⚡ Run Auto Allocate",do_auto,PRIMARY); auto_run_btn.pack(side="bottom",pady=12)
        build_preview()

    def _auto_left_preview(self, worker, plan, one_week, chosen_week, leftlbl):
        """Show what the worker will have left AFTER the planned allocations, by name.
        Whole period -> period left. One week -> that week's left AND period left."""
        if not worker:
            leftlbl.config(text=""); return
        # cost the plan would add, per week
        add_cost={wk:0.0 for wk in WEEKS}
        for wk,cat,est,day in plan:
            add_cost[wk]+=allocation_cost(est,cat,worker,week=wk)
        # projected per-week left = current left - planned cost this week
        proj_week={wk: worker_wage_left(worker,wk)-add_cost[wk] for wk in WEEKS}
        proj_period=sum(proj_week.values())
        if one_week:
            wl=proj_week.get(chosen_week,0.0)
            tag_w = " ⚠ over" if wl<-1e-9 else ""
            tag_p = " ⚠ over" if proj_period<-1e-9 else ""
            leftlbl.config(
                text=f"After this — {worker} will have left:\n   {chosen_week}: ${fmt(wl)}{tag_w}     ·     Period: ${fmt(proj_period)}{tag_p}",
                fg=DANGER if (wl<-1e-9 or proj_period<-1e-9) else SUCCESS)
        else:
            tag_p = " ⚠ over" if proj_period<-1e-9 else ""
            leftlbl.config(
                text=f"After this — {worker} will have left:  Period ${fmt(proj_period)}{tag_p}",
                fg=DANGER if proj_period<-1e-9 else SUCCESS)

    def wages_dialog(self):
        d,body=branded_dialog(self.root,"Wages — All Weeks","Every worker's wage, placed, and left — for all 6 weeks at a glance",900,640)
        inner=self._scrollable(body)
        workers=list_workers()
        if not workers:
            tk.Label(inner,text="No workers yet.",fg=TEXT2,bg=BG_DARK,font=FONT).pack(padx=16,pady=16); return
        # header row: Worker + one column per week
        hdr=tk.Frame(inner,bg=BG_DARK); hdr.pack(fill="x",padx=10,pady=(10,4))
        tk.Label(hdr,text="Worker",fg=TEXT2,bg=BG_DARK,font=("Segoe UI",9,"bold"),width=16,anchor="w").pack(side="left")
        for wk in WEEKS:
            tk.Label(hdr,text=wk.replace("Week ","W"),fg=TEXT2,bg=BG_DARK,font=("Segoe UI",9,"bold"),width=13,anchor="center").pack(side="left")
        for i,w in enumerate(workers):
            row=tk.Frame(inner,bg=(BG_PANEL if i%2==0 else BG_DARK)); row.pack(fill="x",padx=10,pady=1)
            tk.Label(row,text=w,fg=ACCENT,bg=row["bg"],font=FONTB,width=16,anchor="w").pack(side="left",pady=6)
            for wk in WEEKS:
                left=worker_wage_left(w,wk)
                col=DANGER if left<-1e-9 else (SUCCESS if left>1e-9 else TEXT2)
                tk.Label(row,text=f"${fmt(left)}",fg=col,bg=row["bg"],font=("Segoe UI",10,"bold"),width=13,anchor="center").pack(side="left",pady=6)
        # totals row
        trow=tk.Frame(inner,bg=BG_LIGHT); trow.pack(fill="x",padx=10,pady=(6,10))
        tk.Label(trow,text="ALL WORKERS",fg=ACCENT,bg=BG_LIGHT,font=FONTB,width=16,anchor="w").pack(side="left",pady=8)
        for wk in WEEKS:
            tot=sum(worker_wage_left(w,wk) for w in workers)
            tk.Label(trow,text=f"${fmt(tot)}",fg=(DANGER if tot<-1e-9 else ACCENT),bg=BG_LIGHT,font=("Segoe UI",10,"bold"),width=13,anchor="center").pack(side="left",pady=8)
        tk.Label(inner,text="Green = wage still available this week   ·   Red = over-allocated",
                 fg=TEXT2,bg=BG_DARK,font=("Segoe UI",8)).pack(anchor="w",padx=10,pady=(0,10))

    @staticmethod
    def _auto_source(note):
        """Which automatic tool made an allocation, from its note; None = typed by hand."""
        n=str(note or "")
        if n=="auto": return "Auto Allocate"
        if n=="auto-chain": return "Auto Allocate (Chain)"
        if n.startswith("Copied from"): return "Copy week"
        if n=="From payroll": return "Copy week (payroll)"
        if n.startswith("Monday auto"): return "Monday auto-import"
        return None

    def remove_auto_dialog(self,source=None,only_last=False):
        d,body=branded_dialog(self.root,"Remove Auto & Copied Allocations",
            "Undo what the app added for you: Auto Allocate, Auto Allocate (Chain) and Copy week. Shifts typed by hand are never listed here.",
            900,700)
        top=tk.Frame(body,bg=BG_DARK); top.pack(fill="x",padx=16,pady=(10,6))
        def mkf(lbl,var,vals,w):
            tk.Label(top,text=lbl,fg=TEXT,bg=BG_DARK,font=FONTB).pack(side="left")
            ttk.Combobox(top,textvariable=var,values=vals,state="readonly",width=w).pack(side="left",padx=(6,16))
        fsrc=tk.StringVar(value=source or "(Anything automatic)"); fwk=tk.StringVar(value="(All weeks)"); fcli=tk.StringVar(value="(All clients)")
        mkf("Made by:",fsrc,["(Anything automatic)","Monday auto-import","Copy week","Auto Allocate","Auto Allocate (Chain)"],22)
        mkf("Week:",fwk,["(All weeks)"]+WEEKS,12)
        mkf("Client:",fcli,["(All clients)"]+list(self._snapshot.get("clients",[])),20)
        lastv=tk.BooleanVar(value=bool(only_last))
        tk.Checkbutton(top,text="Only the last copy / Monday run",variable=lastv,fg=TEXT,bg=BG_DARK,selectcolor=BG_LIGHT,
                       activebackground=BG_DARK,activeforeground=TEXT,font=FONT,command=lambda:build_preview()).pack(side="left")

        tk.Label(body,text="Preview — allocations that will be REMOVED:",fg=DANGER,bg=BG_DARK,font=FONTB).pack(anchor="w",padx=16,pady=(6,2))
        prevwrap=tk.Frame(body,bg=BG_DARK); prevwrap.pack(fill="both",expand=True,padx=16)
        prev_tree=make_fast_tree(prevwrap,("week","worker","client","cat","hrs","cost","src","when"),
                                 ("Week","Worker","Client","Cat","Hours","Cost","Made by","Added"),
                                 (130,140,150,55,60,80,150,120),("w","w","w","c","e","e","w","w"),height=14)
        cntlbl=tk.Label(body,text="",fg=ACCENT,bg=BG_DARK,font=FONTB); cntlbl.pack(anchor="w",padx=16,pady=(6,4))

        matches_holder=[[]]
        def build_preview(*_):
            src_f=fsrc.get(); wk_f=fwk.get(); cli_f=fcli.get()
            rows=[]
            for r in self._snapshot.get("allocations",[]):
                if str(r[0]).startswith("-"): continue          # still syncing — not deletable yet
                src=self._auto_source(r[9])
                if not src: continue
                if src_f=="Copy week" and not src.startswith("Copy week"): continue
                if src_f not in ("","(Anything automatic)","Copy week") and src!=src_f: continue
                if wk_f not in ("","(All weeks)") and r[1]!=wk_f: continue
                if cli_f not in ("","(All clients)") and r[3]!=cli_f: continue
                rows.append((r,src))
            if lastv.get():
                # A copy (or a Monday run) saves all its shifts in one go, so they share
                # the same "added" time: keep only the newest such batch.
                batch=lambda s_:s_.startswith("Copy week") or s_=="Monday auto-import"
                copies=[r for r,src in rows if batch(src)]
                last=max((str(r[11] or "")[:19] for r in copies),default="")
                rows=[(r,src) for r,src in rows if batch(src) and str(r[11] or "")[:19]==last]
            matches_holder[0]=[r for r,_s in rows]
            wl={wk:week_label_short(wk) for wk in WEEKS}
            def when(c):
                try: return datetime.fromisoformat(str(c)).strftime("%d %b %H:%M")
                except Exception: return str(c or "")
            self._tree_replace(prev_tree,[(None,(wl.get(r[1],r[1]),r[2],r[3],CAT_ABBR.get(r[4],r[4]),fmt(float(r[5] or 0)),
                                                 "$"+fmt(float(r[7] or 0)),src,when(r[11])),("odd" if i%2 else "even",))
                                          for i,(r,src) in enumerate(rows)])
            th=sum(float(r[5] or 0) for r,_s in rows); tc=sum(float(r[7] or 0) for r,_s in rows)
            cntlbl.config(text=(f"{len(rows)} allocation(s) match — {fmt(th)} hours, ${fmt(tc)} total." if rows
                                else "Nothing matches — no automatic or copied allocations for this selection."))
        for v in (fsrc,fwk,fcli): v.trace_add("write",build_preview)

        def do_remove():
            matches=matches_holder[0]
            if not matches:
                messagebox.showinfo("Nothing to remove","No automatic or copied allocations match this selection.",parent=d); return
            th=sum(float(r[5] or 0) for r in matches); tc=sum(float(r[7] or 0) for r in matches)
            if not messagebox.askyesno("Confirm Remove",
                    f"Permanently remove {len(matches)} allocation(s) — {fmt(th)} hours, ${fmt(tc)}?\n\nShifts typed by hand are not touched.\n"
                    "This cannot be undone (though your period is backed up automatically).",parent=d):
                return
            aids=[r[0] for r in matches]
            remove_auto_btn.config(state="disabled",text="Removing…")
            def done(n):
                d.destroy(); self.refresh(); messagebox.showinfo("Removed",f"Removed {n} allocation(s).",parent=self.root)
            def fail(exc):
                remove_auto_btn.config(state="normal",text="🗑 Remove Matching Allocations")
                messagebox.showerror("Remove failed",str(exc),parent=d)
            self._background_job(lambda:delete_allocations_batch(aids,self.user),done,fail,sync_after=True,label="remove_auto_batch")
        remove_auto_btn=mkbtn(body,"🗑 Remove Matching Allocations",do_remove,DANGER); remove_auto_btn.pack(side="bottom",pady=12)
        build_preview()

    # ================= COPY WEEK (12.2.7) =================
    # Copy the shifts of chosen clients from one week to another week of the open period:
    # same day, same worker, same hours. Shifts the payroll (FoxOzy import) already shows for
    # the TO week go in FIRST; the copy fills the rest without clashing. "Small changes" moves
    # each start a little (keeps the length). A client still short of that week's estimate is
    # left short, or topped up on its copied shifts. Nothing is saved until you press Copy.
    def copy_week_dialog(self):
        d,body=branded_dialog(self.root,"Copy Week",
            "Copy the shifts of the clients you pick from one week to another. Payroll shifts of that week go in first. Nothing is saved until you press Copy.",
            1100,820)
        d.bind("<Escape>",lambda e:d.destroy())
        snap=self._snapshot
        def wk_label(wk):
            try: return f"{wk} · {fmt_date(get_week_date(wk))}"
            except Exception: return wk
        labels=[wk_label(w) for w in WEEKS]; lab2wk=dict(zip(labels,WEEKS))
        cur=self.cur_week.get() if hasattr(self,"cur_week") else WEEKS[0]
        i0=WEEKS.index(cur) if cur in WEEKS else 0
        fromv=tk.StringVar(value=labels[i0]); tov=tk.StringVar(value=labels[min(i0+1,len(WEEKS)-1)])
        modev=tk.StringVar(value="exact"); stepv=tk.StringVar(value="15")
        payv=tk.BooleanVar(value=True); shortv=tk.StringVar(value="leave")
        CK=dict(fg=TEXT,bg=CARD,selectcolor=BG_LIGHT,activebackground=CARD,activeforeground=TEXT,font=FONT)
        top=tk.Frame(body,bg=CARD,highlightbackground=BORDER,highlightthickness=1); top.pack(fill="x",padx=16,pady=(10,6))
        tk.Label(top,text="FROM",fg=TEXT2,bg=CARD,font=("Segoe UI Semibold",8,"bold")).pack(side="left",padx=(12,5),pady=10)
        ttk.Combobox(top,textvariable=fromv,values=labels,state="readonly",width=24,style="Modern.TCombobox").pack(side="left")
        tk.Label(top,text="  TO",fg=TEXT2,bg=CARD,font=("Segoe UI Semibold",8,"bold")).pack(side="left",padx=(12,5))
        ttk.Combobox(top,textvariable=tov,values=labels,state="readonly",width=24,style="Modern.TCombobox").pack(side="left")
        tk.Checkbutton(top,text="Payroll shifts of the TO week go in first",variable=payv,command=lambda:build_preview(),**CK).pack(side="left",padx=(18,6))
        mode=tk.Frame(body,bg=CARD,highlightbackground=BORDER,highlightthickness=1); mode.pack(fill="x",padx=16,pady=(0,6))
        tk.Radiobutton(mode,text="Copy exactly",variable=modev,value="exact",**CK).pack(side="left",padx=(12,8),pady=6)
        tk.Radiobutton(mode,text="Small changes: move each start by up to",variable=modev,value="vary",**CK).pack(side="left",padx=(8,4))
        ttk.Combobox(mode,textvariable=stepv,values=["15","30","45","60"],state="readonly",width=4,style="Modern.TCombobox").pack(side="left")
        tk.Label(mode,text="min (same hours)",fg=TEXT,bg=CARD,font=FONT).pack(side="left",padx=(4,8))
        mkbtn(mode,"↻ New changes",lambda:build_preview(new_seed=True),CONTROL,fg=TEXT).pack(side="right",padx=10)
        mode2=tk.Frame(body,bg=CARD,highlightbackground=BORDER,highlightthickness=1); mode2.pack(fill="x",padx=16,pady=(0,6))
        tk.Label(mode2,text="IF A CLIENT IS STILL SHORT",fg=TEXT2,bg=CARD,font=("Segoe UI Semibold",8,"bold")).pack(side="left",padx=(12,8),pady=6)
        tk.Radiobutton(mode2,text="Leave it short",variable=shortv,value="leave",**CK).pack(side="left",padx=6)
        tk.Radiobutton(mode2,text="Top up: make its copied shifts longer (no clash, 12h a day max, only while the worker has wage left)",
                       variable=shortv,value="topup",**CK).pack(side="left",padx=6)
        allow21v=tk.BooleanVar(value=False); skipoverv=tk.BooleanVar(value=False)
        mode3=tk.Frame(body,bg=CARD,highlightbackground=BORDER,highlightthickness=1); mode3.pack(fill="x",padx=16,pady=(0,6))
        tk.Label(mode3,text="CHECKS",fg=TEXT2,bg=CARD,font=("Segoe UI Semibold",8,"bold")).pack(side="left",padx=(12,8),pady=6)
        tk.Checkbutton(mode3,text="Allow 2:1 (two workers with the same client at the same time)",variable=allow21v,**CK).pack(side="left",padx=6)
        tk.Checkbutton(mode3,text="Leave out shifts that would put a worker over their pay",variable=skipoverv,**CK).pack(side="left",padx=6)
        # clients with shifts in the FROM week
        cl=tk.Frame(body,bg=CARD,highlightbackground=BORDER,highlightthickness=1); cl.pack(fill="x",padx=16,pady=(0,6))
        clhead=tk.Frame(cl,bg=CARD); clhead.pack(fill="x")
        tk.Label(clhead,text="CLIENTS",fg=TEXT2,bg=CARD,font=("Segoe UI Semibold",8,"bold")).pack(side="left",padx=12,pady=(8,2))
        # Many clients must not push the preview off the window: the list scrolls in a box
        # of at most ~5 rows instead of growing.
        clscroll=ScrollArea(cl,CARD); clscroll.pack(fill="x",padx=10,pady=(0,8))
        clbox=clscroll.body
        def _fit_clients(_e=None):
            try: clscroll.canvas.configure(height=min(max(28,clbox.winfo_reqheight()),ui_px(132)))
            except Exception: pass
        clbox.bind("<Configure>",_fit_clients,add="+")
        cvars={}
        def all_clients(val):
            for v in cvars.values(): v.set(val)
            build_preview()
        mkbtn(clhead,"All",lambda:all_clients(True),CONTROL,fg=TEXT).pack(side="right",padx=(4,10),pady=4)
        mkbtn(clhead,"None",lambda:all_clients(False),CONTROL,fg=TEXT).pack(side="right",padx=4,pady=4)
        def src_rows():
            wk=lab2wk.get(fromv.get())
            return [r for r in snap.get("allocations",[]) if r[1]==wk and float(r[5] or 0)>0]
        def build_clients(*_):
            for w in clbox.winfo_children(): w.destroy()
            old={c:v.get() for c,v in cvars.items()}; cvars.clear()
            hrs={}
            for r in src_rows(): hrs[r[3]]=hrs.get(r[3],0.0)+float(r[5] or 0)
            if not hrs:
                tk.Label(clbox,text="No shifts in this week.",fg=TEXT2,bg=CARD,font=FONT).grid(row=0,column=0,sticky="w",padx=4); return
            for i,c in enumerate(sorted(hrs,key=str.lower)):
                v=tk.BooleanVar(value=old.get(c,False)); cvars[c]=v
                tk.Checkbutton(clbox,text=f"{c}  ({fmt(hrs[c])}h)",variable=v,command=build_preview,anchor="w",**CK).grid(row=i//4,column=i%4,sticky="w",padx=4,pady=1)
        covbox=tk.Frame(body,bg=CARD,highlightbackground=BORDER,highlightthickness=1)
        tk.Label(covbox,text="DOES IT COVER THE WEEK?  (that week's estimate vs what it will have after the copy — problems first)",fg=TEXT2,bg=CARD,
                 font=("Segoe UI Semibold",8,"bold")).pack(anchor="w",padx=12,pady=(6,0))
        covscroll=ScrollArea(covbox,CARD); covscroll.pack(fill="x",padx=12,pady=(2,6))
        covlbl=tk.Label(covscroll.body,text="",fg=TEXT,bg=CARD,font=("Consolas",ui_pt(9)),justify="left",anchor="w")
        covlbl.pack(anchor="w",fill="x")
        def _fit_cov(_e=None):
            try: covscroll.canvas.configure(height=min(max(18,covscroll.body.winfo_reqheight()),ui_px(96)))
            except Exception: pass
        covscroll.body.bind("<Configure>",_fit_cov,add="+")
        tk.Label(body,text="PREVIEW — double-click a row to leave it out or put it back",fg=TEXT2,bg=BG_DARK,
                 font=("Segoe UI Semibold",8,"bold")).pack(anchor="w",padx=18,pady=(4,2))
        foot=tk.Frame(body,bg=TOPBAR,highlightbackground=BORDER,highlightthickness=1); foot.pack(fill="x",side="bottom")
        status=tk.Label(foot,text="",fg=TEXT2,bg=TOPBAR,font=("Segoe UI",9),anchor="w"); status.pack(side="left",padx=14,fill="x",expand=True)
        covbox.pack(fill="x",side="bottom",padx=16,pady=(0,6))
        tree=make_fast_tree(body,("use","day","worker","client","cat","was","new","hours","note"),
                            ("Copy","Day","Worker","Client","Category","Was","New","Hours","Check"),
                            (50,130,115,160,90,100,100,60,230),("center","w","w","w","w","w","w","e","w"),height=12)
        plan={"rows":[],"seed":1}
        def mins(t):
            try: h,m=[int(x) for x in str(t).split(":")[:2]]; return h*60+m
            except Exception: return None
        def hhmm(m): m%=1440; return f"{m//60:02d}:{m%60:02d}"
        def span(st,et):
            a=mins(st); b=mins(et)
            if a is None or b is None: return None
            if b<=a: b+=1440
            return a,b
        def map_client(raw):
            """Payroll client text ('Havva Cokacar-CO-CM025') -> the Allocate Pro client ('Hava')."""
            name=re.split(r"-(?:CO|SC)-",str(raw or ""),maxsplit=1,flags=re.I)[0].strip()
            if not name or name.lower().startswith("general admin"): return None
            clients=list(snap.get("clients",[])) or sorted({r[3] for r in snap.get("allocations",[])})
            low={c.lower():c for c in clients}
            if name.lower() in low: return low[name.lower()]
            first=name.split()[0].lower()
            if first in low: return low[first]
            firsts=[c for c in clients if c.split()[0].lower()==first]
            if len(firsts)==1: return firsts[0]
            try:
                m,_r=fuzzy_match(name.split()[0],[c.split()[0] for c in clients])
                if m:
                    hit=[c for c in clients if c.split()[0]==m]
                    if len(hit)==1: return hit[0]
            except Exception: pass
            return None
        def payroll_rows(tw,picked):
            out=[]
            for r in snap.get("cmv_info",[]) or []:
                # (id,week,worker,source_worker,work_date,day,client,service,hours,start,end,status,...)
                if r[1]!=tw or str(r[11] or "").strip().lower() in ("rejected","cancelled","canceled","declined"): continue
                c=map_client(r[6])
                if c not in picked: continue
                try: h=float(r[8] or 0)
                except Exception: h=0.0
                if h<=0: continue
                day=r[5] or ""
                try:
                    dt=datetime.strptime(str(r[4])[:10],"%Y-%m-%d"); day=day or dt.strftime("%A")
                except Exception: pass
                cat="Saturday" if day=="Saturday" else "Sunday" if day=="Sunday" else "Weekday"
                out.append({"worker":r[2],"client":c,"cat":cat,"hours":round(h,4),"day":day,"st":r[9] or "","et":r[10] or ""})
            return out
        def to_category(tw,day,cat):
            """Category for a shift on `day` of week tw: a Victorian public holiday that day
            makes it Public Holiday; a Public Holiday shift copied onto an ordinary day goes
            back to Weekday/Saturday/Sunday. Returns (category, note or "")."""
            try: dd=day_date_for(parse_week_date(get_week_date(tw)),day) if day else None
            except Exception: dd=None
            if dd and dd in REV_VIC_PH: return "Public Holiday",("" if cat=="Public Holiday" else f"Public holiday {dd.strftime('%d %b')} — PH rate")
            if cat=="Public Holiday": return _CAT_OF_DAY.get(day,"Weekday"),"Not a public holiday in this week"
            return cat,""
        def build_preview(*_,new_seed=False):
            import random as _rnd
            if new_seed: plan["seed"]+=1
            rng=_rnd.Random(plan["seed"])
            fw=lab2wk.get(fromv.get()); tw=lab2wk.get(tov.get())
            tree.delete(*tree.get_children()); plan["rows"]=[]
            if fw==tw:
                status.config(text="Pick two different weeks.",fg=WARNING); covlbl.config(text=""); return
            picked={c for c,v in cvars.items() if v.get()}
            vary=modev.get()=="vary"; step=int(stepv.get() or 15)
            busy={}            # day -> [[worker, client, a, b, plan_idx or None]]
            existing=[]
            for r in snap.get("allocations",[]):
                if r[1]!=tw: continue
                st=(r[12] if len(r)>12 else "") or ""; et=(r[13] if len(r)>13 else "") or ""
                existing.append((r[2],r[3],r[8] or "",span(st,et)))
                sp=span(st,et)
                if sp and r[8]: busy.setdefault(r[8],[]).append([r[2],r[3],sp[0],sp[1],None])
            def clash(day,w,c,a,b,skip=None):
                for (w2,c2,a2,b2,ix) in busy.get(day,[]):
                    if skip is not None and ix==skip: continue
                    if a<b2 and a2<b and (w2==w or (c2==c and not allow21v.get())): return f"{w2} / {c2} already {hhmm(a2)}–{hhmm(b2)}"
                return None
            def add(p):
                plan["rows"].append(p); return len(plan["rows"])-1
            # every payroll shift of the TO week (any client) blocks that worker's time
            for r in snap.get("cmv_info",[]) or []:
                if r[1]!=tw or str(r[11] or "").strip().lower() in ("rejected","cancelled","canceled","declined"): continue
                sp=span(r[9] or "",r[10] or ""); day=r[5] or ""; mc=map_client(r[6])
                if payv.get() and mc in picked: continue          # added (and checked) just below
                if sp and day: busy.setdefault(day,[]).append([r[2],mc or ("payroll:"+str(r[6] or "")),sp[0],sp[1],None])
            # 1) payroll shifts of the TO week first
            pay_days=set()
            if payv.get():
                for p in payroll_rows(tw,picked):
                    sp=span(p["st"],p["et"]); dup=False
                    for (w2,c2,day2,sp2) in existing:
                        if w2==p["worker"] and c2==p["client"] and day2==p["day"] and (sp is None or sp2 is None or (sp[0]<sp2[1] and sp2[0]<sp[1])):
                            dup=True; break
                    pay_days.add((p["worker"],p["client"],p["day"]))
                    p["cat"],phn=to_category(tw,p["day"],p["cat"])
                    if dup:
                        add(dict(p,use=False,src="payroll",was="",note="Payroll shift already in that week")); continue
                    why=clash(p["day"],p["worker"],p["client"],*sp) if sp and p["day"] else None
                    ix=add(dict(p,use=not why,src="payroll",was="",note=("From payroll" if not why else "From payroll — clash: "+why)+(f" · {phn}" if phn else "")))
                    if sp and p["day"] and not why: busy.setdefault(p["day"],[]).append([p["worker"],p["client"],sp[0],sp[1],ix])
            # 2) the copy fills the rest
            rows=sorted([r for r in src_rows() if r[3] in picked],key=lambda r:(DAY_OFFSET.get(r[8],9),(r[12] if len(r)>12 else "") or "",r[2]))
            for r in rows:
                w,c,cat,h,day=r[2],r[3],r[4],float(r[5] or 0),r[8] or ""
                cat,phn=to_category(tw,day,cat)
                st=(r[12] if len(r)>12 else "") or ""; et=(r[13] if len(r)>13 else "") or ""
                sp=span(st,et); nst,net=st,et; note="OK"; use=True
                if (w,c,day) in pay_days:
                    note="Payroll already has this worker for this client that day"; use=False
                elif any(w2==w and c2==c and d2==day and sp2==sp for (w2,c2,d2,sp2) in existing) and not vary:
                    note="Already in that week"; use=False
                elif sp and day:
                    a,b=sp; L=b-a; offs=[0]
                    if vary:
                        k=max(1,step//15); cand=[i*15 for i in range(-k,k+1) if i!=0]
                        rng.shuffle(cand); offs=cand+[0]
                    chosen=None; why=None
                    for o in offs:
                        why=clash(day,w,c,a+o,a+o+L)
                        if not why: chosen=o; break
                    if chosen is None: note="Clash: "+why; use=False
                    else:
                        nst,net=hhmm(a+chosen),hhmm(a+chosen+L)
                        if chosen: note=f"Start {'+' if chosen>0 else '−'}{abs(chosen)} min"
                elif not day: note="No day set — copied without a day"
                if phn: note=phn if note=="OK" else note+" · "+phn
                ix=add({"use":use,"src":"copy","worker":w,"client":c,"cat":cat,"hours":h,"day":day,"st":nst,"et":net,"was":f"{st}–{et}" if st else "","note":note})
                if use and day and nst and net:
                    s2=span(nst,net); busy.setdefault(day,[]).append([w,c,s2[0],s2[1],ix])
            # 3) top up clients still short (only the copied shifts are made longer)
            if shortv.get()=="topup": top_up(tw,busy,clash)
            if skipoverv.get():
                for i in pay_over(tw,only_used=True):
                    plan["rows"][i]["use"]=False
                    plan["rows"][i]["note"]="Left out — would put the worker over their pay"
            draw()
        def pay_over(tw,only_used=True):
            """Rows (in plan order) that take their worker past what they were paid in week tw.
            Returns {row index: (amount over after this row, paid)}."""
            wrates=snap.get("worker_rates",{}) or {}
            paid={w:float(v or 0) for (w,wk),v in (snap.get("wages",{}) or {}).items() if wk==tw}
            used={}
            for r in snap.get("allocations",[]):
                if r[1]==tw: used[r[2]]=used.get(r[2],0.0)+float(r[7] or 0)
            out={}
            for i,p in enumerate(plan["rows"]):
                if only_used and not p["use"]: continue
                try: rate=effective_rate(p["worker"],p["cat"],wrates,week=tw)
                except Exception: rate=GLOBAL_RATES.get(p["cat"],0)
                used[p["worker"]]=used.get(p["worker"],0.0)+p["hours"]*rate
                over=used[p["worker"]]-paid.get(p["worker"],0.0)
                if over>0.01: out[i]=(over,paid.get(p["worker"],0.0))
            return out
        def top_up(tw,busy,clash):
            est=snap.get("estimates",{}) or {}; wrates=snap.get("worker_rates",{}) or {}
            have={}
            for r in snap.get("allocations",[]):
                if r[1]==tw: have[(r[3],r[4])]=have.get((r[3],r[4]),0.0)+float(r[5] or 0)
            for p in plan["rows"]:
                if p["use"]: have[(p["client"],p["cat"])]=have.get((p["client"],p["cat"]),0.0)+p["hours"]
            # wage left in the TO week per worker, after what is already there and this plan
            wl={}
            for (w,wk),v in (snap.get("wages",{}) or {}).items():
                if wk==tw: wl[w]=float(v or 0)
            for r in snap.get("allocations",[]):
                if r[1]==tw: wl[r[2]]=wl.get(r[2],0.0)-float(r[7] or 0)
            def rate(w,cat):
                try: return effective_rate(w,cat,wrates,week=tw)
                except Exception: return GLOBAL_RATES.get(cat,0)
            for p in plan["rows"]:
                if p["use"]: wl[p["worker"]]=wl.get(p["worker"],0.0)-p["hours"]*rate(p["worker"],p["cat"])
            def day_minutes(w,day):
                return sum(b-a for (w2,c2,a,b,ix) in busy.get(day,[]) if w2==w)
            for (c,cat),hv in list(have.items()):
                e=float(est.get((c,tw,cat),0) or 0)
                short=round(e-hv,4)
                if e<=0.001 or short<=0.009: continue
                cands=[i for i,p in enumerate(plan["rows"]) if p["use"] and p["src"]=="copy" and p["client"]==c and p["cat"]==cat and p["day"] and p["st"] and p["et"]]
                added={i:0 for i in cands}
                progress=True
                while short>0.009 and progress:
                    progress=False
                    for i in cands:
                        if short<=0.009: break
                        p=plan["rows"][i]; sp=span(p["st"],p["et"]); a,b=sp
                        cost=0.25*rate(p["worker"],cat)
                        if wl.get(p["worker"],0.0)-cost< -0.01: continue
                        if day_minutes(p["worker"],p["day"])+15>12*60: continue
                        if clash(p["day"],p["worker"],c,b,b+15,skip=i): continue
                        p["et"]=hhmm(b+15); p["hours"]=round(p["hours"]+0.25,4); added[i]+=0.25
                        wl[p["worker"]]=wl.get(p["worker"],0.0)-cost; short=round(short-0.25,4)
                        for e2 in busy.get(p["day"],[]):
                            if e2[4]==i: e2[3]=b+15
                        progress=True
                for i,x in added.items():
                    if x>0: plan["rows"][i]["note"]=(plan["rows"][i]["note"] if plan["rows"][i]["note"]!="OK" else "")+(" · " if plan["rows"][i]["note"] not in ("OK","") else "")+f"Topped up +{fmt(x)}h"
        def draw():
            tree.delete(*tree.get_children()); tw=lab2wk.get(tov.get())
            over=pay_over(tw)
            for i,p in enumerate(plan["rows"]):
                dd=day_with_date(tw,p["day"]) if p["day"] else "—"
                note=p["note"]
                if i in over:
                    amt,pd=over[i]
                    note=(f"⚠ not paid in {tw} yet" if pd<=0.01 else f"⚠ ${fmt(amt)} over pay")+("" if note=="OK" else " · "+note)
                tree.insert("","end",iid=str(i),values=("✓" if p["use"] else "—",dd,p["worker"],p["client"],p["cat"],
                            p["was"] or ("payroll" if p["src"]=="payroll" else "—"),f"{p['st']}–{p['et']}" if p["st"] else "—",fmt(p["hours"]),note),
                            tags=(("danger",) if i in over and p["use"] else ()))
            n=sum(1 for p in plan["rows"] if p["use"]); hrs=sum(p["hours"] for p in plan["rows"] if p["use"]); skip=len(plan["rows"])-n
            npay=sum(1 for p in plan["rows"] if p["use"] and p["src"]=="payroll")
            if not plan["rows"]: status.config(text="Tick the clients to copy.",fg=TEXT2)
            else:
                ow={plan["rows"][i]["worker"] for i in over}
                unpaid={plan["rows"][i]["worker"] for i,(a,pd) in over.items() if pd<=0.01}
                status.config(text=f"{n} shift(s), {fmt(hrs)}h will be added to {wk_label(tw)}"+(f" ({npay} from payroll)" if npay else "")
                                +(f"  ·  {skip} left out" if skip else "")
                                +(f"  ·  ⚠ {len(ow-unpaid)} worker(s) would go over their pay" if ow-unpaid else "")
                                +(f"  ·  ⚠ {len(unpaid)} not paid in {tw} yet" if unpaid else ""),
                              fg=(WARNING if ow else TEXT))
            coverage()
        def coverage():
            tw=lab2wk.get(tov.get()); picked=sorted({p["client"] for p in plan["rows"]}|{c for c,v in cvars.items() if v.get()},key=str.lower)
            if not picked: covlbl.config(text="Tick a client to see it.",fg=TEXT2); return
            est=snap.get("estimates",{}) or {}
            have={}
            for r in snap.get("allocations",[]):
                if r[1]==tw: have[(r[3],r[4])]=have.get((r[3],r[4]),0.0)+float(r[5] or 0)
            add={}
            for p in plan["rows"]:
                if p["use"]: add[(p["client"],p["cat"])]=add.get((p["client"],p["cat"]),0.0)+p["hours"]
            lines=[]; worst=0.0; rank=[]
            for c in picked:
                cats=[k for k in CATEGORIES if float(est.get((c,tw,k),0) or 0)>0.001 or (c,k) in add or (c,k) in have]
                for k in cats:
                    e=float(est.get((c,tw,k),0) or 0); h=have.get((c,k),0.0); a=add.get((c,k),0.0); tot=h+a; diff=tot-e
                    if e<=0.001: verdict="no estimate set"; r=2
                    elif diff<-0.009: verdict=f"{fmt(-diff)}h SHORT"; worst=min(worst,diff); r=0
                    elif diff>0.009: verdict=f"{fmt(diff)}h over"; r=1
                    else: verdict="covered"; r=3
                    rank.append((r,f"{c[:20]:<20} {k:<14} estimate {fmt(e):>6}h  |  already {fmt(h):>6}h + copy {fmt(a):>6}h = {fmt(tot):>6}h  |  {verdict}"))
            rank.sort(key=lambda t:t[0])
            lines=[t for r,t in rank if r<3]
            ok_n=sum(1 for r,_t in rank if r==3)
            if ok_n: lines.append(f"✓ {ok_n} other client/category line(s) covered")
            covlbl.config(text="\n".join(lines) or "—",fg=(DANGER if worst<-0.009 else TEXT))
        def toggle(_e=None):
            sel=tree.focus()
            if not sel: return
            p=plan["rows"][int(sel)]; p["use"]=not p["use"]
            draw()
        tree.bind("<Double-1>",toggle)
        def do_copy():
            rows=[p for p in plan["rows"] if p["use"]]
            if not rows: messagebox.showwarning("Nothing to copy","Tick at least one client (and leave at least one row in).",parent=d); return
            fw=lab2wk.get(fromv.get()); tw=lab2wk.get(tov.get())
            npay=sum(1 for p in rows if p["src"]=="payroll")
            if not messagebox.askyesno("Copy shifts",f"Add {len(rows)} shift(s) ({fmt(sum(p['hours'] for p in rows))}h) to {wk_label(tw)}?"
                                       +(f"\n{npay} of them are the payroll shifts of that week." if npay else "")
                                       +f"\n\nCopied from {wk_label(fw)}. Nothing in {fw} changes.",parent=d): return
            data=[(tw,p["worker"],p["client"],p["cat"],p["hours"],p["day"],("From payroll" if p["src"]=="payroll" else f"Copied from {fw}"),p["st"],p["et"]) for p in rows]
            btn.config(state="disabled",text="Copying…")
            def done(n):
                try: d.destroy()
                except Exception: pass
                self.refresh()
                messagebox.showinfo("Copied",f"{n} shift(s) added to {wk_label(tw)}.\n\nChanged your mind? Settings & Tools › Undo a copy removes them in one go.",parent=self.root)
            def failed(exc):
                btn.config(state="normal",text="⧉  Copy")
                messagebox.showerror("Copy failed",str(exc),parent=d)
            self._background_job(lambda:save_allocations_batch(data,self.user),done,failed,sync_after=True,label="copy_week")
        btn=mkbtn(foot,"⧉  Copy",do_copy,PRIMARY); btn.pack(side="right",padx=(6,14),pady=8)
        def _wk_changed(*_): build_clients(); build_preview()
        fromv.trace_add("write",_wk_changed); tov.trace_add("write",lambda *_:build_preview())
        for v in (modev,stepv,shortv,allow21v,skipoverv): v.trace_add("write",lambda *_:build_preview())
        build_clients(); build_preview()

    def delete_all_dialog(self):
        d,body=branded_dialog(self.root,"Delete All Allocations",
            "Deletes EVERY allocation matching your filters — manual AND automated. Choose week/worker/client/category, or leave all blank to delete everything.",
            860,700)
        top=tk.Frame(body,bg=BG_DARK); top.pack(fill="x",padx=16,pady=(10,6))
        fwk=tk.StringVar(); fw=tk.StringVar(); fcli=tk.StringVar(); fcat=tk.StringVar()
        def mkf(lbl,var,vals,w=14):
            tk.Label(top,text=lbl,fg=TEXT,bg=BG_DARK,font=FONTB).pack(side="left",padx=(0,4))
            ttk.Combobox(top,textvariable=var,values=vals,state="readonly",width=w).pack(side="left",padx=(0,14))
        mkf("Week:",fwk,["(All weeks)"]+WEEKS)
        mkf("Worker:",fw,["(All workers)"]+list_workers(),18)
        mkf("Client:",fcli,["(All clients)"]+list_clients(),18)
        mkf("Category:",fcat,["(All categories)"]+CATEGORIES,16)
        fwk.set("(All weeks)"); fw.set("(All workers)"); fcli.set("(All clients)"); fcat.set("(All categories)")

        tk.Label(body,text="⚠ Preview — ALL of these will be permanently deleted (manual entries included):",
                 fg=DANGER,bg=BG_DARK,font=FONTB,wraplength=800,justify="left").pack(anchor="w",padx=16,pady=(6,2))
        prevwrap=tk.Frame(body,bg=BG_DARK); prevwrap.pack(fill="both",expand=True,padx=16)
        # One native table, not a grid of labels: a whole period is thousands of rows and
        # building a label for every cell took several seconds just to open this window.
        prev_tree=make_fast_tree(prevwrap,("week","worker","client","cat","hrs","cost","src"),
                                 ("Week","Worker","Client","Cat","Hours","Cost","Source"),
                                 (150,150,170,60,70,90,90),("w","w","w","c","e","e","w"),height=14)
        cntlbl=tk.Label(body,text="",fg=ACCENT,bg=BG_DARK,font=FONTB); cntlbl.pack(anchor="w",padx=16,pady=(6,4))

        matches_holder=[[]]
        def build_preview(*_):
            weeks_scope = WEEKS if fwk.get() in ("","(All weeks)") else [fwk.get()]
            matches=[]
            for wk in weeks_scope:
                for r in allocations_for(wk):
                    aid,week,worker,client,cat,hrs,rate,cost,day,note,created_by=r
                    if fw.get() not in ("","(All workers)") and worker!=fw.get(): continue
                    if fcli.get() not in ("","(All clients)") and client!=fcli.get(): continue
                    if fcat.get() not in ("","(All categories)") and cat!=fcat.get(): continue
                    matches.append(r)
            matches_holder[0]=matches
            wl={wk:week_label_short(wk) for wk in WEEKS}
            self._tree_replace(prev_tree,[(None,(wl.get(r[1],r[1]),r[2],r[3],CAT_ABBR.get(r[4],r[4]),fmt(r[5]),"$"+fmt(r[7]),r[9] or "manual"),
                                           ("odd" if i%2 else "even",)) for i,r in enumerate(matches)])
            th=sum(r[5] for r in matches); tc=sum(r[7] for r in matches)
            cntlbl.config(text=(f"{len(matches)} allocation(s) match — {fmt(th)} hours, ${fmt(tc)} total." if matches
                                else "Nothing matches this selection."))
        for v in (fwk,fw,fcli,fcat): v.trace_add("write",build_preview)

        def do_delete():
            matches=matches_holder[0]
            if not matches:
                messagebox.showinfo("Nothing to delete","No allocations match this selection.",parent=d); return
            th=sum(r[5] for r in matches); tc=sum(r[7] for r in matches)
            all_selected = all(v.get().startswith("(All") for v in (fwk,fw,fcli,fcat))
            scope_txt = "EVERY allocation in the whole period" if all_selected else "the allocations matching your filters"
            if not messagebox.askyesno("Confirm Delete All",
                    f"Permanently delete {scope_txt} — {len(matches)} allocation(s), {fmt(th)} hours, ${fmt(tc)}?\n\n"
                    "This includes MANUAL entries, not just automated ones.\n\n"
                    "This cannot be undone from within the app (though your period is backed up automatically — "
                    "you could restore from ALLOCATE_PRO_backups if truly needed).",parent=d):
                return
            aids=[r[0] for r in matches]
            delete_all_btn.config(state="disabled",text="Deleting…")
            def done(n):
                d.destroy(); self.refresh(); messagebox.showinfo("Deleted",f"Deleted {n} allocation(s).",parent=self.root)
            def fail(exc):
                delete_all_btn.config(state="normal",text="🗑 Delete All Matching")
                messagebox.showerror("Delete failed",str(exc),parent=d)
            self._background_job(lambda:delete_allocations_batch(aids,self.user),done,fail,sync_after=True,label="delete_allocations_batch")
        delete_all_btn=mkbtn(body,"🗑 Delete All Matching",do_delete,DANGER); delete_all_btn.pack(side="bottom",pady=12)
        build_preview()

    def dashboard_dialog(self):
        d,body=branded_dialog(self.root,"Dashboard","At-a-glance status of all 6 weeks",820,600)
        inner=self._scrollable(body)
        # per-week status
        tk.Label(inner,text="Weekly status",fg=ACCENT,bg=BG_DARK,font=("Segoe UI",13,"bold")).grid(row=0,column=0,columnspan=5,sticky="w",padx=10,pady=(10,6))
        for j,t in enumerate(["Week","Est cost $","Wages $","Gap $","Status"]):
            tk.Label(inner,text=t,fg=TEXT2,bg=BG_DARK,font=("Segoe UI",9,"bold"),anchor="w").grid(row=1,column=j,sticky="w",padx=10,pady=2)
        tot_est=tot_wage=0
        for i,wk in enumerate(WEEKS):
            est=week_total_estimate_cost(wk); wage=week_total_wages(wk); gap=wage-est
            tot_est+=est; tot_wage+=wage
            bg=BG_PANEL if i%2==0 else BG_DARK
            short=gap<-1e-9
            tk.Label(inner,text=week_label_short(wk),fg=TEXT,bg=bg,font=FONT,anchor="w").grid(row=i+2,column=0,sticky="ew",padx=10,pady=1)
            tk.Label(inner,text="$"+fmt(est),fg=TEXT,bg=bg,font=FONT,anchor="w").grid(row=i+2,column=1,sticky="ew",padx=10,pady=1)
            tk.Label(inner,text="$"+fmt(wage),fg=TEXT,bg=bg,font=FONT,anchor="w").grid(row=i+2,column=2,sticky="ew",padx=10,pady=1)
            tk.Label(inner,text="$"+fmt(gap),fg=DANGER if short else SUCCESS,bg=bg,font=FONT,anchor="w").grid(row=i+2,column=3,sticky="ew",padx=10,pady=1)
            tk.Label(inner,text="⚠ SHORT" if short else "✓ OK",fg=DANGER if short else SUCCESS,bg=bg,font=FONTB,anchor="w").grid(row=i+2,column=4,sticky="ew",padx=10,pady=1)
        r=len(WEEKS)+2
        gap_t=tot_wage-tot_est
        tk.Label(inner,text="ALL WEEKS",fg=ACCENT,bg=BG_DARK,font=FONTB,anchor="w").grid(row=r,column=0,sticky="w",padx=10,pady=(8,2))
        tk.Label(inner,text="$"+fmt(tot_est),fg=ACCENT,bg=BG_DARK,font=FONTB,anchor="w").grid(row=r,column=1,sticky="w",padx=10,pady=(8,2))
        tk.Label(inner,text="$"+fmt(tot_wage),fg=ACCENT,bg=BG_DARK,font=FONTB,anchor="w").grid(row=r,column=2,sticky="w",padx=10,pady=(8,2))
        tk.Label(inner,text="$"+fmt(gap_t),fg=DANGER if gap_t<-1e-9 else SUCCESS,bg=BG_DARK,font=FONTB,anchor="w").grid(row=r,column=3,sticky="w",padx=10,pady=(8,2))
        for j,ms in enumerate([170,110,110,110,90]): inner.grid_columnconfigure(j,minsize=ms)
        # quick counts
        r+=2
        na=sum(len(allocations_for(wk)) for wk in WEEKS)
        tk.Label(inner,text=f"Totals:  {len(list_workers())} workers · {len(list_clients())} clients · {na} allocations",
                 fg=TEXT2,bg=BG_DARK,font=FONT).grid(row=r,column=0,columnspan=5,sticky="w",padx=10,pady=10)
        # reconciliation snapshot
        r+=1
        tk.Label(inner,text="Reconciliation (estimates placed):",fg=SECONDARY,bg=BG_DARK,font=FONTB).grid(row=r,column=0,columnspan=5,sticky="w",padx=10,pady=(6,2))
        r+=1
        te=tp=0
        for wk in WEEKS:
            e,pp,_=week_est_reconcile_totals(wk); te+=e; tp+=pp
        left=te-tp
        tk.Label(inner,text=f"Estimate ${fmt(te)} · reconciled ${fmt(tp)} · ${fmt(left)} left to reconcile",
                 fg=(SUCCESS if abs(left)<1e-9 else (ACCENT if left>0 else DANGER)),bg=BG_DARK,font=FONT).grid(row=r,column=0,columnspan=5,sticky="w",padx=10,pady=2)

    def cloud_dialog(self):
        d,body=branded_dialog(self.root,"Cloud Database",
            "Configure the central Turso database used by the whole app. Save + test here, then restart Allocate Pro.",760,510)
        inner=self._scrollable(body)
        cfg=load_cloud_config() or {}

        mode_text = "✓ CLOUD MODE ACTIVE" if CLOUD_ENABLED else "LOCAL MODE — add Turso credentials to switch to cloud"
        tk.Label(inner,text=mode_text,fg=SUCCESS if CLOUD_ENABLED else WARNING,bg=BG_DARK,
                 font=("Segoe UI",12,"bold")).pack(anchor="w",padx=16,pady=(14,10))

        tk.Label(inner,text="Turso database URL",fg=TEXT,bg=BG_DARK,font=FONTB).pack(anchor="w",padx=16,pady=(4,4))
        urlv=tk.StringVar(value=cfg.get("database_url",TURSO_DATABASE_URL if CLOUD_ENABLED else ""))
        tk.Entry(inner,textvariable=urlv,font=FONT,bg=BG_LIGHT,fg=TEXT,insertbackground=TEXT,relief="flat",width=62).pack(anchor="w",padx=16,ipady=5)
        tk.Label(inner,text="Example: libsql://allocate-pro-your-org.turso.io",fg=TEXT2,bg=BG_DARK,font=("Segoe UI",8)).pack(anchor="w",padx=16,pady=(2,0))

        tk.Label(inner,text="Database token",fg=TEXT,bg=BG_DARK,font=FONTB).pack(anchor="w",padx=16,pady=(14,4))
        keyv=tk.StringVar(value=cfg.get("auth_token",TURSO_AUTH_TOKEN if CLOUD_ENABLED else ""))
        tk.Entry(inner,textvariable=keyv,font=FONT,bg=BG_LIGHT,fg=TEXT,insertbackground=TEXT,relief="flat",width=62,show="•").pack(anchor="w",padx=16,ipady=5)
        tk.Label(inner,text="Keep this token private. It gives the app write access to the payroll database.",
                 fg=WARNING,bg=BG_DARK,font=("Segoe UI",8)).pack(anchor="w",padx=16,pady=(2,0))

        status=tk.Label(inner,text="",fg=TEXT2,bg=BG_DARK,font=FONT,justify="left",wraplength=700)
        status.pack(anchor="w",padx=16,pady=(14,4))

        def do_save_and_test():
            u=urlv.get().strip(); k=keyv.get().strip()
            if not u or not k:
                status.config(text="Enter both the database URL and token.",fg=WARNING); return
            save_cloud_config(u,k)
            status.config(text="Testing connection...",fg=TEXT2); d.update_idletasks()
            ok,msg=test_cloud_connection(u,k)
            status.config(text=("✓ "+msg) if ok else ("✗ "+msg), fg=SUCCESS if ok else DANGER)

        mkbtn(inner,"💾 Save & Test Connection",do_save_and_test,PRIMARY).pack(anchor="w",padx=16,pady=10)

        sep=tk.Frame(inner,bg=BG_LIGHT,height=1); sep.pack(fill="x",padx=16,pady=14)
        info=("How this version works:\n"
              "• The CURRENT live period uses one central Turso database.\n"
              "• Workers, clients, wages, allocations, users and reconciliation data all use that database.\n"
              "• Existing local data is imported automatically only when the cloud database is empty.\n"
              "• Period archives are stored in the cloud as portable snapshots and materialised when opened.\n"
              "• Your old local database is NOT deleted during migration.\n\n"
              "After a successful test, close Allocate Pro and open it again. The window title will show [CLOUD].")
        tk.Label(inner,text=info,fg=TEXT2,bg=BG_DARK,font=("Segoe UI",9),justify="left",wraplength=700).pack(anchor="w",padx=16,pady=(0,16))

    def rename_period_dialog(self):
        if DB_PATH!=DEFAULT_DB_PATH:
            messagebox.showinfo("Rename",
                "You can only rename the CURRENT (live) period from here.\n\n"
                "You're currently viewing an archived period — switch back to\n'Current (live)' first, or rename archives from the Period / Archive screen.")
            return
        d,body=branded_dialog(self.root,"Rename Current Period","Give this period a name you'll recognise",520,240)
        tk.Label(body,text="Period name:",fg=TEXT,bg=BG_DARK,font=FONTB).pack(anchor="w",padx=16,pady=(16,6))
