        dy_=ttk.Scrollbar(daycard,orient="vertical",command=day_tree.yview); dx_=ttk.Scrollbar(daycard,orient="horizontal",command=day_tree.xview)
        day_tree.configure(yscrollcommand=dy_.set,xscrollcommand=dx_.set)
        day_tree.tag_configure("odd",background=TREE_ODD,foreground=TEXT); day_tree.tag_configure("even",background=TREE_EVEN,foreground=TEXT)
        day_tree.tag_configure("clash",background=DANGER_BG,foreground=DANGER)
        day_tree.tag_configure("sameworker",foreground=WARNING); day_tree.tag_configure("sameclient",foreground=PRIMARY)
        day_tree.tag_configure("muted",foreground=TEXT2)
        dx_.pack(side="bottom",fill="x",padx=8,pady=(0,3)); dy_.pack(side="right",fill="y",padx=(0,6),pady=(0,3)); day_tree.pack(side="left",fill="both",expand=True,padx=(8,0),pady=(0,3))
        _responsive_tree_columns(day_tree,dx_,daycard,("day","time","worker","client","cat","hrs","status"),
                                 (90,105,120,130,50,55,170),(70,86,90,95,40,45,120))
        def _edit_day_row(_e=None):
            sel=day_tree.selection()
            if not sel: return
            try: self.edit_alloc(int(sel[0]),extra_refresh=lambda:(_reload_snapshot(),recompute()))
            except Exception: pass
        day_tree.bind("<Return>",_edit_day_row)
        # ---- type a new shift straight into the table (same fields as the form above) ----
        qrow=tk.Frame(daycard,bg=_mix_hex(CARD,PRIMARY,0.07),highlightbackground=_mix_hex(BORDER,PRIMARY,0.35),highlightthickness=1)
        qrow.pack(side="top",fill="x",padx=8,pady=(2,4),before=dx_)
        qrow1=tk.Frame(qrow,bg=qrow.cget("bg")); qrow1.pack(fill="x")
        qrow2=tk.Frame(qrow,bg=qrow.cget("bg")); qrow2.pack(fill="x",pady=(0,2))
        tk.Label(qrow1,text="＋ NEW",fg=PRIMARY,bg=qrow.cget("bg"),font=("Segoe UI Semibold",ui_pt(8),"bold")).pack(side="left",padx=(8,6))
        tk.Label(qrow2,text="",bg=qrow.cget("bg"),width=6).pack(side="left",padx=(8,6))
        def _qcb(var,values,width,post=None,ro=True,parent=None):
            cb=ttk.Combobox(parent or qrow1,textvariable=var,values=values,width=width,state=("readonly" if ro else "normal"),style="Modern.TCombobox",
                            postcommand=post,font=("Segoe UI",ui_pt(9)))
            cb.pack(side="left",padx=2,pady=4); cb.bind("<Return>",lambda e:do_save(),add="+"); return cb
        # the row's Day list always shows all 7 days (with dates); picking Sat/Sun sets the category
        qdayv=tk.StringVar(value="")
        def _q_opts():
            wk=wkv.get(); return [f"{nm} · {_short_day_date(wk,nm)}" if _short_day_date(wk,nm) else nm for nm in DAYS if nm]
        def _q_days(): q_day["values"]=_q_opts()
        q_day=_qcb(qdayv,[],15,post=_q_days)
        def _q_day_picked(_e=None):
            nm=qdayv.get().split(" · ")[0]
            if nm not in DAYS: return
            if catv.get()!="Public Holiday": catv.set({"Saturday":"Saturday","Sunday":"Sunday"}.get(nm,"Weekday"))
            dayv.set(nm)
            try: _rebuild_day_options()
            except Exception: pass
            recompute()
        q_day.bind("<<ComboboxSelected>>",_q_day_picked,add="+")
        def _q_day_follow(*_):
            nm=dayv.get(); want=(f"{nm} · {_short_day_date(wkv.get(),nm)}" if nm and _short_day_date(wkv.get(),nm) else nm)
            if qdayv.get()!=want: qdayv.set(want)
        dayv.trace_add("write",_q_day_follow); wkv.trace_add("write",_q_day_follow)
        q_st=_qcb(stv,TIME_OPTIONS,6,ro=False); tk.Label(qrow1,text="–",fg=TEXT2,bg=qrow.cget("bg")).pack(side="left")
        q_et=_qcb(etv,TIME_OPTIONS,6,ro=False)
        for _cb,_var in ((q_st,stv),(q_et,etv)):
            _cb.bind("<FocusOut>",lambda e,v=_var:v.set(normalize_time(v.get())) if normalize_time(v.get())!=v.get() else None,add="+")
        q_h=tk.Entry(qrow1,textvariable=hv,width=6,bg=CONTROL,fg=TEXT,insertbackground=TEXT,relief="flat",font=("Segoe UI Semibold",ui_pt(9)))
        q_h.pack(side="left",padx=(4,2),ipady=3); q_h.bind("<Return>",lambda e:do_save())
        tk.Label(qrow1,text="h",fg=TEXT2,bg=qrow.cget("bg")).pack(side="left")
        q_save=tk.Button(qrow1,text="↵ Save",command=lambda:do_save(),bg=PRIMARY,fg="#fff",relief="flat",bd=0,cursor="hand2",
                         font=("Segoe UI Semibold",ui_pt(9),"bold"),padx=10,pady=2,activebackground=SECONDARY,activeforeground="#fff")
        q_save.pack(side="left",padx=(6,6))
        Tooltip(q_save,"Same as Save Allocation below — clashes are still blocked")
        q_w=_qcb(wv,[""]+self._snapshot["workers"],14,parent=qrow2)
        q_c=_qcb(cv,[""]+self._snapshot["clients"],18,parent=qrow2)
        q_cat=_qcb(catv,CATEGORIES,12,parent=qrow2)

        # ---- double-click a cell to change it right there ----
        _cell={"w":None}
        def _cell_close(_e=None):
            w_=_cell["w"]; _cell["w"]=None
            if w_ is not None:
                try: w_.destroy()
                except Exception: pass
        def _cell_edit(e):
            iid=day_tree.identify_row(e.y); colid=day_tree.identify_column(e.x)
            if not iid or not colid: return
            try: col=day_tree.cget("displaycolumns")
            except Exception: col=()
            cols=list(col) if col and col!=("#all",) else list(day_tree.cget("columns"))
            try: name=cols[int(colid[1:])-1]
            except Exception: return
            if name not in ("time","worker","client","cat","hrs"):
                _edit_day_row(); return "break"
            try: aid=self._real_id(int(iid))      # a just-saved row may still show its temporary id
            except Exception: return
            r=next((x for x in self._snapshot["allocations"] if str(x[0])==str(aid)),None)
            if r is None: return
            bb=day_tree.bbox(iid,name)
            if not bb: return
            _cell_close()
            x,y,w_,h_=bb
            if name in ("worker","client","cat"):
                vals={"worker":self._snapshot["workers"],"client":self._snapshot["clients"],"cat":CATEGORIES}[name]
                cur={"worker":r[2],"client":r[3],"cat":r[4]}[name]
                var=tk.StringVar(value=cur)
                ed=ttk.Combobox(day_tree,textvariable=var,values=vals,state="readonly",style="Modern.TCombobox",font=("Segoe UI",ui_pt(9)))
                def commit(_e=None):
                    v=var.get(); _cell_close()
                    if v and v!=cur:
                        key={"worker":"worker","client":"client","cat":"category"}[name]
                        if self._apply_alloc_change(aid,{key:v},parent=d): dialog_state["snap"]=None; recompute()
                ed.bind("<<ComboboxSelected>>",commit); ed.bind("<Return>",commit)
            else:
                cur=(f"{r[12]}–{r[13]}" if name=="time" else fmt(float(r[5] or 0)))
                var=tk.StringVar(value=cur)
                ed=tk.Entry(day_tree,textvariable=var,bg=CONTROL,fg=TEXT,insertbackground=TEXT,relief="solid",bd=1,font=("Segoe UI Semibold",ui_pt(9)))
                def commit(_e=None):
                    v=var.get().strip(); _cell_close()
                    if not v or v==cur: return
                    if name=="hrs":
                        try: h_new=float(v.replace("h",""))
                        except Exception: messagebox.showerror("Hours","Type the hours as a number, e.g. 4.5",parent=d); return
                        ch={"hours":h_new,"end":""} if r[12] else {"hours":h_new}
                    else:
                        parts=[p for p in re.split(r"\s*[-–to]+\s*",v) if p]
                        if len(parts)!=2: messagebox.showerror("Times","Type it like 09:00-13:30",parent=d); return
                        s_,e_=normalize_time(parts[0]),normalize_time(parts[1]); span=hours_between(s_,e_)
                        if not span: messagebox.showerror("Times","Those times don't make a shift.",parent=d); return
                        ch={"start":s_,"end":e_,"hours":span}
                    if self._apply_alloc_change(aid,ch,parent=d): dialog_state["snap"]=None; recompute()
                ed.bind("<Return>",commit); ed.select_range(0,"end")
            ed.bind("<Escape>",_cell_close); ed.bind("<FocusOut>",lambda e_:d.after(120,_cell_close))
            ed.place(x=x,y=y,width=max(w_,ui_px(90)),height=h_); ed.focus_set(); _cell["w"]=ed
            return "break"
        day_tree.bind("<Double-1>",_cell_edit); day_tree._ap_cell_edit=_cell_edit
        day_tree.bind("<MouseWheel>",_cell_close,add="+")

        _day_state={"args":None}

        def _mins(t):
            try:
                h,m=[int(x) for x in normalize_time(t).split(":")]; return h*60+m
            except Exception:
                return None

        def _dp_week(): return bool(APP_FOLDS.get("dp_week",False))
        def _dp_by(): return "client" if APP_FOLDS.get("dp_by")=="client" else "worker"

        def draw_timeline(rows,w,c,day,me_win):
            tl.delete("all")
            by=_dp_by(); week=_dp_week() or not day
            me=(c if by=="client" else w)
            if not getattr(tl,"_ap_click",False):
                tl.bind("<Button-1>",_dp_grid_click); tl._ap_click=True
            if week: return draw_week_grid(rows,w,c,day,me_win,by,me)
            _dp_view["grid"]=None
            idx=_SHIFT_DAY_IDX.get(day,0)*1440
            bars=[]                      # (row key, start, end, label, clash, highlight)
            for r in rows:
                win=shift_window(r[6],r[7],r[8],r[4])
                if not win: continue
                key,lab_=(r[2],r[1]) if by=="client" else (r[1],r[2])
                hi_=(w and r[1]==w) if by=="client" else (c and r[2]==c)
                bars.append((key,win[0]-idx,win[1]-idx,lab_,_windows_clash(me_win,win) and (r[1]==w or r[2]==c),hi_))
            names=[]
            for b in bars:
                if b[0] not in names: names.append(b[0])
            if me and me not in names: names.insert(0,me)
            elif me: names.remove(me); names.insert(0,me)
            if not names:
                tl.configure(height=ui_px(26))
                tl.create_text(6,ui_px(13),anchor="w",fill=TEXT2,font=("Segoe UI",ui_pt(9)),
                               text=f"No shifts on {day} yet — pick a worker and times above to see where it fits")
                return
            lo=min([b[1] for b in bars]+([me_win[0]-idx] if me_win else [])+[6*60]); hi=max([b[2] for b in bars]+([me_win[1]-idx] if me_win else [])+[22*60])
            lo=(lo//60)*60; hi=((hi+59)//60)*60
            rh=ui_px(18); top=ui_px(16); lab=ui_px(96)
            height=top+rh*len(names)+ui_px(4); tl.configure(height=height)
            W=max(200,tl.winfo_width()); span=max(60,hi-lo)
            X=lambda m: lab+(W-lab-4)*(m-lo)/span
            step=120 if span>12*60 else 60
            t=lo
            while t<=hi:
                x=X(t); tl.create_line(x,top-2,x,height,fill=BORDER)
                hh=(t//60)%24; tl.create_text(x,top//2,text=f"{hh:02d}",fill=TEXT2,font=("Segoe UI",ui_pt(7)))
                t+=step
            for i,n in enumerate(names):
                y=top+i*rh
                tl.create_text(4,y+rh//2,text=n[:14],anchor="w",fill=(TEXT if n==me else TEXT2),
                               font=("Segoe UI Semibold" if n==me else "Segoe UI",ui_pt(8),"bold" if n==me else "normal"))
                for key,s,e,lb,clash,hi_ in bars:
                    if key!=n: continue
                    col=DANGER if clash else (ACCENT if hi_ else PRIMARY)
                    tl.create_rectangle(X(s),y+3,X(e),y+rh-3,fill=_mix_hex(CARD,col,0.55),outline=col)
                    if X(e)-X(s)>40: tl.create_text((X(s)+X(e))/2,y+rh//2,text=lb[:12],fill=TEXT,font=("Segoe UI",ui_pt(7)))
            if me_win:
                s,e=me_win[0]-idx,me_win[1]-idx
                y=top+(names.index(me) if me in names else 0)*rh
                bad=any(b[4] for b in bars)
                tl.create_rectangle(X(s),y+1,X(e),y+rh-1,outline=(DANGER if bad else SUCCESS),width=2,dash=(4,2))

        def draw_week_grid(rows,w,c,day,me_win,by,me):
            """Mon–Sun side by side: one line per worker (or client), each shift a bar at its time."""
            days=list(_SHIFT_DAY_IDX)
            per={}; names=[]
            for r in rows:
                key=(r[2] if by=="client" else r[1])
                if key not in names: names.append(key)
                per.setdefault(key,[]).append(r)
            if me and me not in names: names.insert(0,me)
            elif me: names.remove(me); names.insert(0,me)
            empty=not names
            names=names[:40]
            lo,hi=6*60,22*60
            for r in rows:
                win=shift_window(r[6],r[7],r[8],r[4])
                if win and r[6] in _SHIFT_DAY_IDX:
                    b=_SHIFT_DAY_IDX[r[6]]*1440; lo=min(lo,win[0]-b); hi=max(hi,min(win[1]-b,1440))
            lo=(lo//60)*60; hi=((hi+59)//60)*60; span=max(60,hi-lo)
            rh=ui_px(18); top=ui_px(28); lab=ui_px(96)
            height=top+rh*max(1,len(names))+ui_px(4); tl.configure(height=height)
            W=max(280,tl.winfo_width()); cw=(W-lab-4)/7.0
            _dp_view["grid"]=(lab,cw)
            try: we=parse_week_date(get_week_date(_day_state["args"][1]))
            except Exception: we=None
            for j,dn in enumerate(days):
                x0=lab+j*cw
                if dn==day: tl.create_rectangle(x0,0,x0+cw,height,fill=_mix_hex(CARD,PRIMARY,.10),outline="")
                elif dn in ("Saturday","Sunday"): tl.create_rectangle(x0,0,x0+cw,height,fill=_mix_hex(CARD,ACCENT,.06),outline="")
                tl.create_line(x0,0,x0,height,fill=BORDER)
                dd=day_date_for(we,dn) if we else None
                tl.create_text(x0+cw/2,ui_px(8),text=dn[:3].upper(),fill=(PRIMARY if dn==day else TEXT),font=("Segoe UI Semibold",ui_pt(7),"bold"))
                if dd: tl.create_text(x0+cw/2,ui_px(19),text=dd.strftime("%d %b"),fill=TEXT2,font=("Segoe UI",ui_pt(7)))
            X=lambda j,m: lab+j*cw+2+(cw-4)*max(0,min(1,(m-lo)/span))
            if empty:
                tl.create_text(lab+8,top+rh//2,anchor="w",fill=TEXT2,font=("Segoe UI",ui_pt(9)),text="No shifts this week yet")
            for i,n in enumerate(names):
                y=top+i*rh
                if i%2: tl.create_rectangle(lab,y,W,y+rh,fill=_mix_hex(CARD,TEXT2,.05),outline="")
                tl.create_text(4,y+rh//2,text=n[:14],anchor="w",fill=(TEXT if n==me else TEXT2),
                               font=("Segoe UI Semibold" if n==me else "Segoe UI",ui_pt(8),"bold" if n==me else "normal"))
                slot={}
                for r in per.get(n,[]):
                    if r[6] not in _SHIFT_DAY_IDX: continue
                    j=days.index(r[6]); b=_SHIFT_DAY_IDX[r[6]]*1440
                    other=(r[1] if by=="client" else r[2])
                    hi_=(w and r[1]==w) if by=="client" else (c and r[2]==c)
                    win=shift_window(r[6],r[7],r[8],r[4])
                    clash=bool(me_win and win and _windows_clash(me_win,win) and (r[1]==w or r[2]==c))
                    col=DANGER if clash else (ACCENT if hi_ else PRIMARY)
                    if win:
                        x1,x2=X(j,win[0]-b),X(j,win[1]-b); x2=max(x2,x1+3)
                    else:            # no times: a short hollow chip at the day's start
                        k=slot.get(j,0); slot[j]=k+1; x1=lab+j*cw+2+k*14; x2=x1+12
                    tl.create_rectangle(x1,y+3,x2,y+rh-3,fill=(_mix_hex(CARD,col,0.55) if win else CARD),outline=col)
                    if x2-x1>34: tl.create_text((x1+x2)/2,y+rh//2,text=other[:max(3,int((x2-x1)/7))],fill=TEXT,font=("Segoe UI",ui_pt(7)))
            if me_win and day in _SHIFT_DAY_IDX and me in names:
                j=days.index(day); b=_SHIFT_DAY_IDX[day]*1440; y=top+names.index(me)*rh
                tl.create_rectangle(X(j,me_win[0]-b),y+1,max(X(j,me_win[1]-b),X(j,me_win[0]-b)+3),y+rh-1,outline=SUCCESS,width=2,dash=(4,2))

        def draw_day(snap,wk,w,c,day):
            _day_state["args"]=(snap,wk,w,c,day)
            rows=list(snap.get("week_alloc",[]))
            _wk_mode=_dp_week()
            day_form=day
            if not _wk_mode:
                if day!=_dp_view.get("form"):
                    _dp_view["form"]=day
                    if day: _dp_view["day"]=day
                day=_dp_view.get("day") or day
                if not day:
                    used={r[6] for r in rows}
                    day=next((dn for dn in _SHIFT_DAY_IDX if dn in used),"Monday")
                _dp_view["day"]=day
            _dp_chips(wk,day,_wk_mode)
            if day and not _wk_mode: rows=[r for r in rows if (r[6] or "")==day]
            try: hh=float(hv.get() or 0)
            except Exception: hh=0.0
            st=normalize_time(stv.get().strip()); et=normalize_time(etv.get().strip())
            me_win=shift_window(day,st,et,hh) if (day and st and day==day_form) else None
            order={n:i for i,n in enumerate(_SHIFT_DAY_IDX)}
            rows.sort(key=lambda r:(order.get(r[6] or "",9),_mins(r[7]) if r[7] else 99999,r[1]))
            out=[]; clashes=[]
            for i,r in enumerate(rows):
                aid,rw,rc,rcat,rh_,_cost,rday,rst,ret=r
                win=shift_window(rday,rst,ret,rh_)
                tag="odd" if i%2 else "even"; status=""
                if me_win and win and _windows_clash(me_win,win) and (rw==w or rc==c):
                    tag="clash"; status=("⛔ "+rw+" is busy then" if rw==w else "⛔ "+rc+" already has a shift then"); clashes.append(r)
                elif w and rw==w: tag="sameworker"; status="same worker"
                elif c and rc==c: tag="sameclient"; status="same client"
                elif not (rst and ret): tag="muted"; status="no start/end time"
                out.append((str(aid),(day_with_date(wk,rday) if rday else "— no day",(f"{rst}–{ret}" if (rst or ret) else "—"),
                                      rw,rc,CAT_ABBR.get(rcat,rcat),fmt(float(rh_ or 0)),status),(tag,)))
            day_tree.configure(displaycolumns=(("time","worker","client","cat","hrs","status") if (day and not _wk_mode) else ("day","time","worker","client","cat","hrs","status")))
            kids=day_tree.get_children()
            if kids: day_tree.delete(*kids)
            for iid,vals,tags in out:
                try: day_tree.insert("","end",iid=iid,values=vals,tags=tags)
                except Exception: day_tree.insert("","end",values=vals,tags=tags)
            tot=sum(float(r[4] or 0) for r in rows); ncl=len({r[2] for r in rows})
            if day and _wk_mode:
                day_title.set(f"THIS WEEK  ·  {wk}")
                day_sub.set(f"{len(rows)} shift(s) · {ncl} client(s) · {fmt(tot)} h   ·   {day_with_date(wk,day)} is highlighted · red = would clash · double-click a row to edit")
            elif day:
                day_title.set(f"THIS DAY  ·  {day_with_date(wk,day)}")
                day_sub.set(f"{len(rows)} shift(s) · {ncl} client(s) · {fmt(tot)} h   ·   red = would clash (can't be saved) · amber = same worker · purple = same client · double-click a cell to change it · Enter opens the shift")
            else:
                day_title.set(f"THIS WEEK  ·  {wk}")
                day_sub.set(f"{len(rows)} shift(s) · {ncl} client(s) · {fmt(tot)} h   ·   pick a Day above to see that day's timeline and clashes")
            if not _wk_mode and day!=day_form:
                day_sub.set(f"{len(rows)} shift(s) · {ncl} client(s) · {fmt(tot)} h   ·   just looking — "+(f"your shift is on {day_form}" if day_form else "pick the Day above for your shift to check clashes"))
            if _wk_mode and not day_form:
                day_sub.set(f"{len(rows)} shift(s) · {ncl} client(s) · {fmt(tot)} h   ·   click a day in the grid to see its timeline")
            # one-line verdict for the shift being typed
            if day and w and me_win:
                if clashes:
                    day_note.config(text="⛔ Can't be saved — clashes with "+", ".join(f"{r[1]} → {r[2]} {r[7]}–{r[8]}" for r in clashes[:3]),fg=DANGER)
                else:
                    day_note.config(text=f"✓ {st}–{et or '?'} is free for {w}"+(f" and {c}" if c else ""),fg=SUCCESS)
            elif day and w:
                busy=[f"{r[7]}–{r[8]} {r[2]}" for r in rows if r[1]==w and r[7] and (r[6] or "")==day]
                day_note.config(text=(f"{w} that day: "+" · ".join(busy)) if busy else f"{w} has no other shift that day",fg=(WARNING if busy else TEXT2))
            else:
                day_note.config(text="")
            draw_timeline(rows,w,c,day,me_win)
        tl.bind("<Configure>",lambda e:(_day_state["args"] and draw_day(*_day_state["args"])))


        # ---------------- already added — this week, editable right here ----------------
        # Shows every allocation for the selected week by default — not gated behind
        # picking a Worker/Client up top — with its OWN Worker/Client/Category filters
        # so you can browse and narrow independently. Reads straight from the same
        # in-RAM week snapshot as everything above it — no extra DB call — and
        # edits/deletes go through the same local-first cache path as the rest of the app.
        already=card(intel,PRIMARY); already.grid(row=1,column=0,columnspan=2,sticky="nsew",pady=(6,0))
        arhead=tk.Frame(already,bg=CARD); arhead.pack(fill="x",padx=10,pady=(5,3))
        arh=tk.Frame(arhead,bg=CARD); arh.pack(side="left")
        tk.Label(arh,text="ALREADY ADDED — THIS WEEK",fg=TEXT,bg=CARD,font=("Segoe UI Semibold",10,"bold")).pack(anchor="w")
        already_sub=tk.StringVar(value="")
        tk.Label(arh,textvariable=already_sub,fg=TEXT2,bg=CARD,font=("Segoe UI",8)).pack(anchor="w")
        already_del_btn=mkbtn(arhead,"Delete selected",lambda:do_delete_already(),DANGER); already_del_btn.pack(side="right",pady=2)
        tk.Label(arhead,text="Double-click a row to edit  •  ",fg=TEXT2,bg=CARD,font=("Segoe UI",8)).pack(side="right")
        arfilt=tk.Frame(already,bg=CARD); arfilt.pack(fill="x",padx=10,pady=(0,5))
        aa_worker=tk.StringVar(); aa_client=tk.StringVar(); aa_cat=tk.StringVar()
        def arfilterbox(label,var,vals,width):
            box=tk.Frame(arfilt,bg=CARD); box.pack(side="left",padx=(0,8))
            tk.Label(box,text=label.upper(),fg=TEXT2,bg=CARD,font=("Segoe UI Semibold",7,"bold")).pack(anchor="w")
            ttk.Combobox(box,textvariable=var,values=[""]+vals,state="readonly",width=width,style="Modern.TCombobox").pack()
        arfilterbox("Worker",aa_worker,self._snapshot["workers"],16)
        arfilterbox("Client",aa_client,self._snapshot["clients"],16)
        arfilterbox("Category",aa_cat,CATEGORIES,14)
        already_tree=ttk.Treeview(already,columns=("worker","client","cat","hrs","cost","day","times"),show="headings",style="Allocation.Treeview",height=8,selectmode="browse")
        for col,txt,wid,anc in [("worker","Worker",150,"w"),("client","Client",150,"w"),("cat","Cat",60,"c"),("hrs","Hrs",60,"e"),("cost","Cost",90,"e"),("day","Day & date",130,"w"),("times","Start–End",110,"c")]:
            already_tree.heading(col,text=txt,anchor=anc); already_tree.column(col,width=wid,minwidth=55,anchor=anc,stretch=(col in ("worker","client")))
        ry=ttk.Scrollbar(already,orient="vertical",command=already_tree.yview); rx=ttk.Scrollbar(already,orient="horizontal",command=already_tree.xview)
        already_tree.configure(yscrollcommand=ry.set,xscrollcommand=rx.set)
        already_tree.tag_configure("odd",background=TREE_ODD,foreground=TEXT); already_tree.tag_configure("even",background=TREE_EVEN,foreground=TEXT)
        rx.pack(side="bottom",fill="x",padx=8,pady=(0,3)); ry.pack(side="right",fill="y",padx=(0,6),pady=(0,3)); already_tree.pack(side="left",fill="both",expand=True,padx=(8,0),pady=(0,3))
        _responsive_tree_columns(already_tree,rx,already,("worker","client","cat","hrs","cost","day","times"),
                                 (150,150,60,60,90,90,110),(95,95,48,48,68,68,86))
        def do_edit_already(event=None):
            sel=already_tree.selection()
            if not sel: return
            aid=sel[0]
            # edit_alloc handles a still-syncing (negative) id itself now — no block here.
            self.edit_alloc(int(aid),extra_refresh=lambda:(_reload_snapshot(),recompute()))
        already_tree.bind("<Double-1>",do_edit_already)
        def do_delete_already():
            sel=already_tree.selection()
            if not sel: return
            aid=sel[0]
            if not messagebox.askyesno("Delete","Delete this allocation?",parent=d): return
            old_row=next((r for r in self._snapshot["allocations"] if str(r[0])==str(aid)),None)
            self._cache_delete_allocation(int(aid)); _reload_snapshot(); recompute()
            def do_fire(real_id):
                def failed(exc):
                    if old_row:
                        restored=list(old_row); restored[0]=real_id
                        self._cache_restore_allocation_row(tuple(restored)); _reload_snapshot(); recompute()
                    messagebox.showerror("Delete failed",str(exc),parent=d)
                self._background_job(lambda: delete_allocation_atomic(real_id),None,failed,label="delete_allocation")
            self._run_when_id_ready(aid,do_fire)


        # Wide windows: STILL TO RECONCILE | WORKER WAGES | THIS DAY side by side.
        # Narrower ones: THIS DAY gets its own full-width row at the top of the tables.
        _lay={"mode":None}
        def _arrange(_e=None):
            wide=intel_wrap.winfo_width()>=ui_px(1500)
            mode="wide" if wide else "narrow"
            if _lay["mode"]==mode: return
            _lay["mode"]=mode
            if wide:
                for col in (0,1,2): intel.grid_columnconfigure(col,weight=1,uniform="intel")
                torec.grid(row=0,column=0,columnspan=1,sticky="nsew",padx=(0,5))
                rightintel.grid(row=0,column=1,columnspan=1,sticky="nsew",padx=(5,5))
                daycard.grid(row=0,column=2,columnspan=1,sticky="nsew",padx=(5,0))
                already.grid(row=1,column=0,columnspan=3,sticky="nsew",pady=(6,0))
            else:
                intel.grid_columnconfigure(2,weight=0,uniform="")
                for col in (0,1): intel.grid_columnconfigure(col,weight=1,uniform="intel")
                # the day comes FIRST on a laptop — it's what you look at while typing a shift
                daycard.grid(row=0,column=0,columnspan=2,sticky="nsew",pady=(0,6))
                torec.grid(row=1,column=0,columnspan=1,sticky="nsew",padx=(0,5))
                rightintel.grid(row=1,column=1,columnspan=1,sticky="nsew",padx=(5,0))
                already.grid(row=2,column=0,columnspan=2,sticky="nsew",pady=(6,0))
        intel_wrap.bind("<Configure>",_arrange,add="+")
        d.after(60,_arrange)

        # Day dropdown shows the REAL calendar date next to each day name (e.g.
        # "Monday · 04 Aug"), computed from the selected week's ending date — same
        # date math the reports/audit trail already use (allocation_date()). dayv
        # keeps storing the bare day name ("Monday") everywhere else in the app;
        # day_dispv is just what's shown in this one combobox.
        day_display_map={}
        def _short_day_date(wk,nm):
            if not nm or nm not in DAY_OFFSET: return ""
            try:
                y,m,dd=get_week_date(wk).split("-")
                real=_date(int(y),int(m),int(dd))+_timedelta(days=DAY_OFFSET[nm])
                return real.strftime("%d %b")
            except Exception:
                return ""
        def _rebuild_day_options(*_):
            wk=wkv.get(); cat=catv.get(); names=days_for_category(cat)
            day_display_map.clear(); opts=[]
            for nm in names:
                if not nm:
                    opts.append(""); day_display_map[""]=""; continue
                sd=_short_day_date(wk,nm)
                disp=f"{nm} · {sd}" if sd else nm
                opts.append(disp); day_display_map[disp]=nm
            day_combo["values"]=opts
            cur=dayv.get()
            day_dispv.set(next((disp for disp,nm in day_display_map.items() if nm==cur),""))
        def _on_day_display_change(*_):
            dayv.set(day_display_map.get(day_dispv.get(),""))
        day_dispv.trace_add("write",_on_day_display_change)
        wkv.trace_add("write",_rebuild_day_options)

        def on_category(*_):
            cat=catv.get(); allowed=days_for_category(cat)
            if cat=="Saturday":dayv.set("Saturday")
            elif cat=="Sunday":dayv.set("Sunday")
            elif dayv.get() not in allowed:dayv.set("")
            _rebuild_day_options()
            recompute()
        catv.trace_add("write",on_category)
        _rebuild_day_options()

        dialog_state={"week":None,"snap":None}
        def _reload_snapshot():
            wk=wkv.get(); dialog_state["week"]=wk; dialog_state["snap"]=self._allocation_snapshot_cached(wk)
        d._ap_live=True
        def _team_changed():
            if not d.winfo_exists(): return
            dialog_state["snap"]=None; recompute()
            try: flag.config(text="↻ Updated with a teammate's changes",fg=CYAN)
            except Exception: pass
        if not hasattr(self,"_team_listeners"): self._team_listeners=[]
        self._team_listeners.append(_team_changed)
        d.bind("<Destroy>",lambda e:(e.widget is d) and _team_changed in self._team_listeners and self._team_listeners.remove(_team_changed),add="+")
        def _snap():
            if dialog_state["snap"] is None or dialog_state["week"]!=wkv.get(): _reload_snapshot()
            return dialog_state["snap"]

        def recompute(*_):
            # No DB calls here — safe on every keystroke.
            wk=wkv.get(); w=wv.get(); c=cv.get(); cat=catv.get(); day=dayv.get(); snap=_snap()
            try: draw_day(snap,wk,w,c,day)
            except Exception: pass
            wage_left=snap["wage_left"]; estimate=snap["estimate"]; period_estimate=snap["period_estimate"]; period_added=snap["period_added"]; week_alloc=snap["week_alloc"]
            week_client_alloc=snap.get("week_client_alloc",{}); worker_day_clients=snap.get("worker_day_clients",{}); duplicate_keys=snap.get("duplicate_keys",set())

            # The worker's OWN rates (global unless they have an exception) drive every
            # $ figure on this screen, exactly as the save will.
            wrates=self._snapshot.get("worker_rates",{})
            def rate_for(cat_):
                return effective_rate(w,cat_,wrates,week=wk) if w else global_rates_for_week(wk).get(cat_,0)
            # Worker KPI
            if w:
                paid=float(self._snapshot.get("wages",{}).get((w,wk),0.0) or 0.0)
                wl=float(wage_left.get(w,0.0) or 0.0); rec=paid-wl
                wage_kpi.set(("-$"+fmt(-wl)) if wl<0 else "$"+fmt(wl))
                cover=worker_estimated_hours(max(0.0,wl),w,wrates,week=wk)
                cover_txt=" · ".join(f"{CAT_ABBR[cc]} {fmt(cover[cc])}h" for cc in CATEGORIES)
                has_exc=any(k[0]==w for k in wrates)
                # Name the week explicitly: wages are per week, and this card silently
                # follows the Week dropdown above, which is easy to misread as a total.
                kpi_sub_w.set(f"{w} • {wk} • Paid ${fmt(paid)} → Reconciled ${fmt(rec)}  •  Could still cover: {cover_txt}"+("  •  💲 own rates" if has_exc else ""))
            else:
                wage_kpi.set("Pick worker"); kpi_sub_w.set("Paid → Reconciled → Remaining")

            # Read-only CareMile source note for the selected worker/week. Approved days only.
            if w:
                srcrows=[r for r in self._snapshot.get("cmv_info",[]) if r[1]==wk and r[2]==w and str(r[11] or "").strip().lower()=="approved"]
                days=[]
                for rr in srcrows:
                    try: dl=datetime.strptime(rr[4],"%Y-%m-%d").strftime("%a %d %b")
                    except Exception: dl=rr[5] or rr[4]
                    if dl and dl not in days: days.append(dl)
                cmv_ref_var.set(("CMV source worked days: "+" • ".join(days)+"  •  reference only") if days else "CMV source: no approved worked days imported for this worker/week.")
            else:
                cmv_ref_var.set("CMV source: pick a worker to see approved worked days (reference only).")

            # Client KPIs + breakdown, always based on six weekly estimates saved in Clients.
            details=[]
            if c:
                for cat2 in CATEGORIES:
                    plan=float(estimate.get((c,cat2),0.0) or 0.0)
                    placed=float(week_client_alloc.get((c,cat2),0.0) or 0.0)
                    left=plan-placed
                    total=float(period_estimate.get((c,cat2),0.0) or 0.0)
                    added=float(period_added.get((c,cat2),0.0) or 0.0)
                    pleft=total-added
                    if plan>1e-9 or placed>1e-9 or total>1e-9 or added>1e-9:
                        details.append(f"{CAT_ABBR[cat2]}: week {fmt(plan)}h est / {fmt(placed)}h allocated / {fmt(left)}h left   •   period {fmt(total)}h est / {fmt(added)}h allocated / {fmt(pleft)}h left")
                plan=float(estimate.get((c,cat),0.0) or 0.0); placed=float(week_client_alloc.get((c,cat),0.0) or 0.0); left=plan-placed
                total=float(period_estimate.get((c,cat),0.0) or 0.0); added=float(period_added.get((c,cat),0.0) or 0.0); pleft=total-added
                week_kpi.set(f"{fmt(left)}h left")
                kpi_sub_week.set(f"{c} • {CAT_ABBR.get(cat,cat)} • Estimate {fmt(plan)}h → Allocated {fmt(placed)}h")
                period_kpi.set(f"{fmt(pleft)}h left")
                kpi_sub_period.set(f"6 weeks • Estimate {fmt(total)}h → Allocated {fmt(added)}h")
                detail_var.set("   |   ".join(details) if details else "No weekly estimates are set for this client.")
            else:
                week_kpi.set("Pick client"); period_kpi.set("Pick client")
                kpi_sub_week.set("This week's estimate"); kpi_sub_period.set("All 6 weekly estimates")
                detail_var.set("The weekly client estimates already saved in Clients will appear here.")

            # Outstanding estimates table.
            outstanding_tree.delete(*outstanding_tree.get_children())
            fcli=tr_fc.get(); fcat=tr_fcat.get(); oi=0
            for cc in snap["clients"]:
                if fcli and cc!=fcli: continue
                for cat2 in CATEGORIES:
                    if fcat and cat2!=fcat: continue
                    plan=float(estimate.get((cc,cat2),0.0) or 0.0); placed=float(week_client_alloc.get((cc,cat2),0.0) or 0.0); left=plan-placed
                    if left>1e-9:
                        outstanding_tree.insert("","end",values=(cc,CAT_ABBR[cat2],fmt(plan),fmt(placed),fmt(left),"$"+fmt(left*GLOBAL_RATES[cat2])),tags=("odd" if oi%2 else "even",)); oi+=1
            if oi==0: outstanding_tree.insert("","end",values=("✓ All estimates reconciled","","","","",""),tags=("success",))

            # All workers' wages — readable and always visible. Sorted highest
            # remaining wage first (most room to allocate), descending from there.
            wages_tree.delete(*wages_tree.get_children())
            worker_rows=[]
            for ww in snap["workers"]:
                paid=float(self._snapshot.get("wages",{}).get((ww,wk),0.0) or 0.0); leftv=float(wage_left.get(ww,0.0) or 0.0); rec=paid-leftv
                worker_rows.append((ww,paid,rec,leftv))
            worker_rows.sort(key=lambda r:r[3],reverse=True)
            for i,(ww,paid,rec,leftv) in enumerate(worker_rows):
                tag="danger" if leftv<-1e-9 else ("success" if abs(leftv)<1e-9 and paid>0 else ("odd" if i%2 else "even"))
                wages_tree.insert("","end",values=(ww,"$"+fmt(paid),"$"+fmt(rec),("-$"+fmt(-leftv) if leftv<0 else "$"+fmt(leftv))),tags=(tag,))

            # Already-added table — EVERY allocation for the selected week by default,
            # narrowed only by this panel's own Worker/Client/Category filters (not tied
            # to the Worker/Client fields up top in Allocation Details).
            already_tree.delete(*already_tree.get_children())
            aaw=aa_worker.get(); aac=aa_client.get(); aacat=aa_cat.get()
            already_rows=[r for r in week_alloc if (not aaw or r[1]==aaw) and (not aac or r[2]==aac) and (not aacat or r[3]==aacat)]
            for i,r in enumerate(already_rows):
                raid,rw,rc,rcat,rh,rcost,rday,rst,ret=r
                rtimes=f"{rst or ''}–{ret or ''}" if (rst or ret) else "—"
                already_tree.insert("","end",iid=str(raid),values=(rw,rc,CAT_ABBR.get(rcat,rcat),fmt(rh),"$"+fmt(rcost),day_with_date(wk,rday),rtimes),tags=("odd" if i%2 else "even",))
            already_sub.set(f"{len(already_rows)} allocation(s) this week" if already_rows else "Nothing added yet this week")

            try:h=float(hv.get())
            except Exception:h=None
            if h is not None and h>0:
                r_=rate_for(cat); is_exc=bool(w) and (w,cat) in wrates
                value_kpi.set("$"+fmt(h*r_)); kpi_sub_value.set(f"{fmt(h)}h • {CAT_ABBR.get(cat,cat)} @ ${fmt(r_)}/h"+(f"  ({w}'s rate)" if is_exc else ""))
            else:
                value_kpi.set("$0.00"); kpi_sub_value.set("Current allocation")

            if w and c and cat and h is not None and h>0:
                cost=h*rate_for(cat); wl=float(wage_left.get(w,0.0) or 0.0)
                client_period_left_h=float(period_estimate.get((c,cat),0.0) or 0.0)-float(period_added.get((c,cat),0.0) or 0.0)
                after_w=wl-cost; after_c=client_period_left_h-h
                plan_week=float(estimate.get((c,cat),0.0) or 0.0); placed_week=float(week_client_alloc.get((c,cat),0.0) or 0.0)
                plbl.config(text=f"Preview  •  {w} → {c}  •  {fmt(h)}h {CAT_ABBR.get(cat,cat)}  •  ${fmt(cost)}  •  Worker remaining after ${fmt(after_w)}  •  Week allocated {fmt(placed_week+h)}h / {fmt(plan_week)}h",fg=DANGER if (after_w<-1e-9 or after_c<-1e-9) else TEXT)
                if after_w<-1e-9 or after_c<-1e-9:
                    bits=[]
                    if after_w<-1e-9:bits.append(f"worker over by ${fmt(-after_w)}")
                    if after_c<-1e-9:bits.append(f"6-week estimate over by {fmt(-after_c)}h")
                    savebtn.config(state="normal",bg=WARNING,text="Save anyway — "+", ".join(bits))
                else: savebtn.config(state="normal",bg=PRIMARY,text="Save Allocation   ↵")
            else:
                plbl.config(text="Pick a worker and client to see the reconciliation preview.",fg=TEXT); savebtn.config(state="normal",bg=PRIMARY,text="Save Allocation   ↵")

            if w and day:
                others=sorted(x for x in worker_day_clients.get((w,day),set()) if x!=c); dup=(w,c,cat,day) in duplicate_keys; warnings=[]
                if others:warnings.append(f"{w} already has {', '.join(others)} on {day}")
                if dup:warnings.append(f"Possible duplicate: {w} already has {c}/{CAT_ABBR.get(cat,cat)} on {day}")
                try: _hh=float(hv.get() or 0)
                except Exception: _hh=0
                _conf=shift_conflicts([(r[0],r[1],r[2],r[3],r[4],r[6],r[7],r[8]) for r in snap["week_alloc"]],
                                      w,c,day,normalize_time(stv.get().strip()),normalize_time(etv.get().strip()),_hh) if stv.get().strip() else []
                if _conf:
                    _bits=[(f"{w} is already on {_r[2]} {_r[6]}–{_r[7]}" if _k=="worker" else f"{c} already has {_r[1]} {_r[6]}–{_r[7]}")
                           for _k,_r in sorted(_conf,key=lambda x:x[0]!="worker")][:2]
                    warnings.insert(0,"⛔ CLASH — "+" · ".join(_bits)+" · this can't be saved")
                flag.config(text="   •   ".join(warnings),fg=(DANGER if _conf else WARNING))
                if _conf: savebtn.config(state="normal",bg=DANGER,text="⛔ Clash — change the day or time")
            else: flag.config(text="")

        for v in (wkv,wv,cv,catv,dayv,hv,tr_fc,tr_fcat,aa_worker,aa_client,aa_cat,stv,etv): v.trace_add("write",recompute)
        on_category()

        def do_save():
            wk=wkv.get(); w=wv.get(); c=cv.get(); cat=catv.get(); day=dayv.get()
            if not w or not c:
                messagebox.showerror("Missing information","Choose both a worker and a client.",parent=d); return
            try:h=float(hv.get())
            except Exception:messagebox.showerror("Invalid hours","Type hours as a number, e.g. 5 or 5.5.",parent=d); return
            if h<=0:messagebox.showerror("Invalid hours","Hours must be greater than zero.",parent=d); return
            if self._clash_block(d,wk,w,c,day,normalize_time(stv.get().strip()),normalize_time(etv.get().strip()),h):
                flag.config(text="⛔ Not saved — this shift clashes with another one (see message)",fg=DANGER); return

            sig=(wk,w,c,cat,day); snap=_snap()
            # Every Save creates its OWN allocation row. This used to silently merge a new
            # entry into an existing row with the same worker/client/category/day — adding
            # the hours together, replacing that row's start/end times with the new ones,
            # and showing no extra line in the table. Entering two separate shifts on the
            # same day therefore looked like the second one "never came through", and the
            # first shift's clock times were overwritten. Each shift is now its own row.
            same_key=[r for r in snap["week_alloc"] if r[1]==w and r[2]==c and r[3]==cat and (r[6] or "")==day]
            if same_key:
                prev=sum(float(r[4] or 0) for r in same_key)
                if not messagebox.askyesno("Already an entry for this day",
                    f"{w} → {c} · {CAT_ABBR.get(cat,cat)}"+(f" · {day_with_date(wk,day)}" if day else "")+
                    f" already has {fmt(prev)}h in {wk}"+(f" across {len(same_key)} entries" if len(same_key)>1 else "")+".\n\n"
                    f"Add these {fmt(h)}h as a SEPARATE entry?\n\n"
                    f"(Yes keeps both rows and both sets of times — {fmt(prev)}h + {fmt(h)}h = {fmt(prev+h)}h total.)",parent=d):
                    return
            elif sig in [r[0] for r in recent]:
                if not messagebox.askyesno("Possible duplicate",f"You already added {w} → {c} · {CAT_ABBR.get(cat,cat)}"+(f" · {day}" if day else "")+f" in {wk} this session.\n\nAdd it again anyway?",parent=d): return

            existing_aid=None
            final_hours=h
            start_time=normalize_time(stv.get().strip()); end_time=normalize_time(etv.get().strip())
            # LOCAL-FIRST UX: update RAM immediately. Turso never owns the click.
            old_row=next((r for r in self._snapshot["allocations"] if existing_aid and str(r[0])==str(existing_aid)),None)
            provisional_id=existing_aid if existing_aid else -int(time.time_ns()%2_000_000_000)-1
            self._cache_upsert_allocation(provisional_id,wk,w,c,cat,final_hours,day,self.user,start_time,end_time,existing=bool(existing_aid))
            _reload_snapshot(); session_count[0]+=1
            label=f"{w} → {c} · {CAT_ABBR.get(cat,cat)}"+(f" · {day}" if day else "")+f" · {fmt(h)}h"
            recent.insert(0,(sig,label)); del recent[4:]
            countlbl.config(text=f"Added this session: {session_count[0]}")
            hv.set(""); stv.set(""); etv.set(""); self._select_week(wk,publish=False); recompute()
            savebtn.config(state="normal",bg=PRIMARY,text="Save Allocation   ↵")
            flag.config(text="✓ Saved locally • cloud sync running in background",fg=SUCCESS); he.focus_set()

            def work_with(real_existing):
                return save_allocation_atomic(wk,w,c,cat,final_hours,day,self.user,existing_aid=real_existing,start_time=start_time,end_time=end_time,update_estimate_to=None)
            def done(result_aid):
                if not existing_aid:
                    self._cache_replace_allocation_id(provisional_id,result_aid)
                try: flag.config(text="✓ Synced • ready",fg=SUCCESS)
                except Exception: pass
            def failed(e):
                if existing_aid:
                    self._cache_restore_allocation_row(old_row)
                else:
                    self._cache_restore_allocation_row(None,replace_id=provisional_id)
                _reload_snapshot(); recompute()
                try:
                    flag.config(text="Cloud sync failed — local change was rolled back",fg=DANGER)
                    messagebox.showerror("Cannot sync allocation",str(e),parent=d)
                except Exception:
                    messagebox.showerror("Cannot sync allocation",str(e),parent=self.root)
            # Adding hours onto a row that is itself still syncing (temporary negative id):
            # the cloud doesn't know that id yet, so an UPDATE against it would match
            # nothing and silently succeed — the merged hours would then vanish on the
            # next refresh. Wait for the real id exactly like Edit/Delete already do.
            if existing_aid is not None and str(existing_aid).startswith("-"):
                self._run_when_id_ready(existing_aid,
                    lambda real: self._background_job(lambda:work_with(real),done,failed,label="save_allocation"),
                    lambda: failed(Exception("The allocation you were adding onto never reached the cloud, so this addition was not saved.")))
            else:
                self._background_job(lambda:work_with(existing_aid),done,failed,label="save_allocation")

        # Opened from the Audit page: start with the suggested worker / client / day / hours.
        if prefill:
            def _apply_prefill():
                try:
                    p=prefill
                    if p.get("week") in WEEKS: wkdisp.set(week_label_short(p["week"]))
                    if p.get("worker"): wv.set(p["worker"])
                    if p.get("client"): cv.set(p["client"])
                    if p.get("category") in CATEGORIES: catv.set(p["category"])
                    if p.get("day"):
                        dayv.set(p["day"])
                        try: _rebuild_day_options()
                        except Exception: pass
                    if p.get("start"): stv.set(normalize_time(p["start"]))
                    if p.get("end"): etv.set(normalize_time(p["end"]))
                    elif p.get("hours") not in (None,""): hv.set(fmt_h(float(p["hours"])).rstrip("h"))
                    recompute()
                    src={"roster":"the roster","CareMile":"the CareMile shift"}.get(p.get("_from"),"the Audit")
                    flag.config(text=f"Filled in from {src} — check it, then Save",fg=CYAN)
                    he.focus_set(); he.icursor("end")
                except Exception:
                    pass
            d.after(150,_apply_prefill)

