    def search_dialog(self):
        d=tk.Toplevel(self.root); d.title("ALLOCATE PRO — Search"); d.configure(bg=BG_DARK); d.geometry("900x640"); window_sizable(d,"Search")
        tk.Label(d,text="🔍 Search allocations",fg=ACCENT,bg=BG_DARK,font=("Segoe UI",13,"bold")).pack(anchor="w",padx=16,pady=12)
        f=tk.Frame(d,bg=BG_DARK); f.pack(fill="x",padx=16)
        wkv=tk.StringVar(); wv=tk.StringVar(); cv=tk.StringVar(); catv=tk.StringVar(); dayv=tk.StringVar()
        def combo(lbl,var,vals):
            cell=tk.Frame(f,bg=BG_DARK); cell.pack(side="left",padx=6)
            tk.Label(cell,text=lbl,fg=TEXT2,bg=BG_DARK,font=("Segoe UI",8)).pack(anchor="w")
            ttk.Combobox(cell,textvariable=var,values=[""]+vals,state="readonly",width=14).pack()
        combo("Week",wkv,WEEKS); combo("Worker",wv,list_workers()); combo("Client",cv,list_clients())
        combo("Category",catv,CATEGORIES); combo("Day",dayv,[x for x in DAYS if x])
        res=tk.Frame(d,bg=BG_DARK); res.pack(fill="both",expand=True,padx=16,pady=10)
        def run():
            for w in res.winfo_children(): w.destroy()
            rows=allocations_for()
            def keep(r):
                _,week,worker,client,cat,hrs,rate,cost,day,note,created_by=r
                return ((not wkv.get() or week==wkv.get()) and (not wv.get() or worker==wv.get())
                    and (not cv.get() or client==cv.get()) and (not catv.get() or cat==catv.get())
                    and (not dayv.get() or day==dayv.get()))
            rows=[r for r in rows if keep(r)]
            hdr=tk.Frame(res,bg=BG_DARK); hdr.pack(fill="x")
            for t,wd in [("Week",10),("Worker",14),("Client",14),("Cat",12),("Hrs",7),("Cost",10),("Day",10)]:
                tk.Label(hdr,text=t,fg=ACCENT,bg=BG_DARK,font=FONTB,width=wd,anchor="w").pack(side="left")
            for r in rows:
                _,week,worker,client,cat,hrs,rate,cost,day,note,created_by=r
                rw=tk.Frame(res,bg=BG_PANEL); rw.pack(fill="x",pady=1)
                for val,wd in [(week,10),(worker,14),(client,14),(cat,12),(fmt(hrs),7),("$"+fmt(cost),10),(day or "—",10)]:
                    tk.Label(rw,text=val,fg=TEXT,bg=BG_PANEL,font=FONT,width=wd,anchor="w").pack(side="left")
            th=sum(r[5] for r in rows); tc=sum(r[7] for r in rows)
            tk.Label(res,text=f"\n{len(rows)} results  —  {fmt(th)} hours  —  ${fmt(tc)}",fg=SUCCESS,bg=BG_DARK,font=FONTB).pack(anchor="w",pady=8)
        for v in (wkv,wv,cv,catv,dayv): v.trace_add("write",lambda *a:run())
        mkbtn(d,"Search",run,ACCENT,"#000").pack(pady=4)
        run()

